-- CodeCart PRO: новые описания модулей (структура и стили). Меняет только поле description.
SET NAMES utf8mb4;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt; Професійні HTML-листи замовлень, статусів та реєстрації для інтернет-магазину &lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Красиві листи клієнту та адміністратору після оформлення замовлення.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Окремі шаблони повідомлень при зміні статусу замовлення.&lt;/p&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=51 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Order Email PRO replaces plain default order notifications with controlled HTML email templates for customers and administrators.&lt;/p&gt;&lt;p&gt;Order email is one of the first post-purchase contacts with the store. Clear branded messages reduce confusion about products, totals and order status while giving the administrator a consistent notification format.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that want professional multilingual order/status emails with preview, testing and delivery diagnostics.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=51 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Order Email PRO заменяет простые стандартные письма о заказах управляемыми HTML-шаблонами для клиента и администратора.&lt;/p&gt;&lt;p&gt;Письмо после заказа — один из первых контактов с магазином. Понятное брендированное сообщение уменьшает путаницу по товарам, сумме и статусу и делает коммуникацию профессиональнее.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;HTML-письма клиенту и администратору&lt;/li&gt;&lt;li&gt;Товары и итоги заказа&lt;/li&gt;&lt;li&gt;Логотип и фирменные цвета&lt;/li&gt;&lt;li&gt;Мультиязычные шаблоны&lt;/li&gt;&lt;li&gt;Защита от дублирования&lt;/li&gt;&lt;li&gt;Безопасное включение после настройки&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которым нужны красивые мультиязычные письма о заказах/статусах с preview, тестом и диагностикой.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=51 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;UTF8MB4 Converter PRO&lt;/strong&gt; — професійний модуль CodeCart PRO для OpenCart 3.x та ocStore 3.0.x, який допомагає безпечно перевести базу даних магазину на сучасне кодування &lt;strong&gt;utf8mb4&lt;/strong&gt; та привести таблиці магазину до надійного двигуна &lt;strong&gt;InnoDB&lt;/strong&gt; .&lt;/p&gt;&lt;p&gt; Модуль особливо корисний для інтернет-магазинів, які працюють із багатомовним контентом, SEO-текстами, імпортом товарів, emoji, Unicode-символами, маркетинговими матеріалами, CRM, прайсами постачальників, Excel, Google Sheets, API та зовнішніми сервісами.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Російська мова&lt;/li&gt;&lt;li&gt;Українська мова&lt;/li&gt;&lt;li&gt;English language&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Старе MySQL кодування &lt;strong&gt;utf8&lt;/strong&gt; насправді часто є &lt;strong&gt;utf8mb3&lt;/strong&gt; і підтримує не весь сучасний Unicode. Через це деякі символи можуть зберігатися неправильно, перетворюватися на знаки питання, пошкоджуватися або викликати помилки при збереженні даних.&lt;/p&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=52 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;UTF8MB4 Converter PRO audits the OpenCart/ocStore database and helps migrate legacy character sets to utf8mb4 and tables to InnoDB in a controlled way.&lt;/p&gt;&lt;p&gt;Old MySQL utf8 is often utf8mb3 and cannot store the full Unicode range. Encoding problems may damage modern symbols, imported content, multilingual text and AI-generated copy, so conversion should begin with an audit and a full database backup.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Older or migrated OpenCart/ocStore stores that still contain legacy charsets/collations or MyISAM tables.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=52 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;UTF8MB4 Converter PRO проверяет базу OpenCart/ocStore и помогает контролируемо перевести старые кодировки в utf8mb4, а таблицы — в InnoDB.&lt;/p&gt;&lt;p&gt;Старый MySQL utf8 часто является utf8mb3 и не хранит весь Unicode. Ошибки кодировки могут портить импорт, мультиязычный и AI-контент, поэтому конвертацию нужно начинать с аудита и полного backup.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Аудит кодировки таблиц и колонок&lt;/li&gt;&lt;li&gt;Конвертация в utf8mb4&lt;/li&gt;&lt;li&gt;Переход MyISAM/Aria в InnoDB&lt;/li&gt;&lt;li&gt;Проверка подключения БД&lt;/li&gt;&lt;li&gt;Предупреждения по индексам&lt;/li&gt;&lt;li&gt;Контроль новых таблиц модулей&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Старым или мигрированным магазинам OpenCart/ocStore с legacy charset/collation или MyISAM таблицами.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=52 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Product Reviews Writer PRO&lt;/strong&gt; допомагає створювати чернетки текстів для відгуків через AI або локальні шаблони, керувати ними через чергу та перевіряти результат в адмінці перед будь-яким використанням.&lt;/p&gt;&lt;p&gt;&lt;strong&gt;Синтетичний текст не можна видавати за справжній відгук покупця.&lt;/strong&gt; Безпечний сценарій використання — demo/test/AI-generated матеріали, внутрішнє тестування, підготовка чернеток для модерації або інші випадки, де походження створеного тексту чітко розкрито.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;AI-чернетки або локальні шаблонні тексти.&lt;/li&gt;&lt;li&gt;Режими: тільки AI, тільки шаблони або AI з fallback на шаблон.&lt;/li&gt;&lt;li&gt;Галузеві промпти для різних типів товарів.&lt;/li&gt;&lt;li&gt;Модерація до використання: перегляд, редагування, схвалення, відхилення або видалення.&lt;/li&gt;&lt;li&gt;Постійна черга для пакетної генерації великого каталогу.&lt;/li&gt;&lt;li&gt;UA / RU / EN для багатомовних магазинів.&lt;/li&gt;&lt;li&gt;Налаштування діапазону рейтингу, списків авторів і лімітів генерації.&lt;/li&gt;&lt;li&gt;Статуси, журнал і діагностика помилок черги.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль корисний розробникам і власникам магазинів, яким потрібно швидко створювати тестовий контент для демо-каталогів, перевіряти дизайн блоку відгуків, готувати текстові чернетки або моделювати різні сценарії перед запуском реального магазину.&lt;/p&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=53 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Reviews Writer PRO generates review drafts for OpenCart products through AI or local templates, with queue processing, language control and administrator review before publication.&lt;/p&gt;&lt;p&gt;Synthetic content must not be presented as genuine customer testimony. The safe use case is clearly labelled demo/test/synthetic review content, drafting assistance or internal content testing where the administrator reviews and identifies generated material appropriately.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;AI-generated or template-based review drafts.&lt;/li&gt;&lt;li&gt;AI-only, template-only or AI-with-template-fallback modes.&lt;/li&gt;&lt;li&gt;Industry-oriented prompts for different product niches.&lt;/li&gt;&lt;li&gt;Draft moderation before any publication: review, edit, approve, reject or delete.&lt;/li&gt;&lt;li&gt;Persistent queue for batch generation in large catalogs.&lt;/li&gt;&lt;li&gt;UA/RU/EN generation for multilingual stores.&lt;/li&gt;&lt;li&gt;Configurable rating ranges, author-name pools and generation limits.&lt;/li&gt;&lt;li&gt;Logs, statuses and error diagnostics for queued work.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores and developers that need controlled review-draft generation for testing, demos or clearly disclosed synthetic content.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=53 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Reviews Writer PRO создаёт черновики отзывов к товарам OpenCart через AI или локальные шаблоны, с очередью, языками и проверкой администратором до публикации.&lt;/p&gt;&lt;p&gt;Синтетический текст нельзя выдавать за реальный отзыв покупателя. Безопасный сценарий — явно маркированные demo/test/AI-generated материалы, внутреннее тестирование или черновики, которые администратор проверяет и корректно обозначает.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;AI-черновики или локальные шаблонные тексты.&lt;/li&gt;&lt;li&gt;Режимы только AI, только шаблоны или AI с fallback на шаблон.&lt;/li&gt;&lt;li&gt;Отраслевые промпты для разных товарных ниш.&lt;/li&gt;&lt;li&gt;Модерация черновика до публикации: просмотр, редактирование, одобрение, отклонение или удаление.&lt;/li&gt;&lt;li&gt;Постоянная очередь для массовой генерации большого каталога.&lt;/li&gt;&lt;li&gt;Генерация UA/RU/EN для мультиязычных магазинов.&lt;/li&gt;&lt;li&gt;Диапазоны рейтингов, списки авторов и лимиты генерации.&lt;/li&gt;&lt;li&gt;Логи, статусы и диагностика ошибок очереди.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам и разработчикам, которым нужны управляемые черновики отзывов для тестов, демо или явно раскрытого synthetic-контента.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=53 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Image Manager PRO&lt;/strong&gt; спрощує щоденну роботу з товарними зображеннями в OpenCart та ocStore. Модуль допомагає швидко бачити фото товару в адмінці, працювати з основними й додатковими зображеннями та контролювати позиції, де фотографія відсутня.&lt;/p&gt;&lt;p&gt;Це практичний інструмент для магазинів, у яких адміністратор регулярно додає товари, перевіряє фото, виправляє помилки галереї або працює з великим каталогом. Замість постійного переходу між карткою товару, файловим менеджером і витриною потрібна інформація доступна ближче до списку товарів.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Показ основного зображення товару в адмінці у зручному форматі.&lt;/li&gt;&lt;li&gt;Збільшення зображення для швидкої візуальної перевірки без відкриття кожного товару.&lt;/li&gt;&lt;li&gt;Контроль товарів без фотографій і коректна робота з no-image.&lt;/li&gt;&lt;li&gt;Робота з основними та додатковими зображеннями товару.&lt;/li&gt;&lt;li&gt;Допомагає знаходити невдалі, відсутні або неправильно прив’язані фото під час наповнення каталогу.&lt;/li&gt;&lt;li&gt;Не змінює самі файли зображень без окремої дії адміністратора.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;У каталозі з сотнями товарів помилки з фото легко пропустити. Image Manager PRO скорочує час перевірки й дозволяє швидше довести картки товарів до однакового візуального стандарту.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Контент-менеджерам, адміністраторам OpenCart, веб-студіям та магазинам із великою кількістю товарних фотографій.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;li&gt;Працює зі стандартною системою зображень OpenCart/ocStore&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=54 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Image Manager PRO simplifies daily work with product images in the OpenCart admin area: visual checks, missing-image control and standard image management stay close to the product list.&lt;/p&gt;&lt;p&gt;Large catalogs accumulate missing, outdated or wrongly assigned images. A faster visual workflow reduces the need to open every product card or browse server folders just to confirm basic image state.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Quick visual control of the main product image in OpenCart admin.&lt;/li&gt;&lt;li&gt;Image enlargement for catalog checks without opening every storefront page.&lt;/li&gt;&lt;li&gt;Detection of products with missing images and controlled no-image fallback.&lt;/li&gt;&lt;li&gt;Work with main and additional product images through the standard image system.&lt;/li&gt;&lt;li&gt;Useful during catalog filling, supplier imports and recurring photo-quality review.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Catalog managers and stores with many product photos, imports and recurring image-quality checks.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=54 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Image Manager PRO упрощает ежедневную работу с изображениями товаров в админке OpenCart: визуальную проверку, контроль отсутствующих фото и работу со стандартной системой изображений.&lt;/p&gt;&lt;p&gt;В большом каталоге накапливаются отсутствующие, старые и неправильно привязанные фото. Быстрый визуальный контроль уменьшает необходимость открывать каждую карточку и искать файлы по папкам сервера.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Быстрый визуальный контроль основного изображения товара в админке.&lt;/li&gt;&lt;li&gt;Увеличение изображения для проверки каталога без открытия каждой страницы витрины.&lt;/li&gt;&lt;li&gt;Контроль товаров без фото и корректный no-image fallback.&lt;/li&gt;&lt;li&gt;Работа с основными и дополнительными изображениями через стандартную систему OpenCart.&lt;/li&gt;&lt;li&gt;Полезен при наполнении каталога, импорте поставщиков и регулярной проверке фото.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Контент-менеджерам и магазинам с большим количеством фотографий и регулярными импортами.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=54 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Translate Expert Pro&lt;/strong&gt; — комплексный модуль для быстрого перевода и проверки мультиязычного интернет-магазина. Он помогает переводить отдельные поля в админке, обрабатывать мультиязычные таблицы базы данных, находить отсутствующие значения и проверять PHP language-файлы.&lt;/p&gt;&lt;p&gt;Модуль подходит владельцам магазинов, разработчикам, веб-студиям, переводчикам и контент-менеджерам, которым необходимо быстро запускать новые языковые версии сайта и поддерживать локализацию в актуальном состоянии.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;перевод одного выбранного поля;&lt;/li&gt;&lt;li&gt;перевод всех поддерживаемых полей текущей языковой вкладки;&lt;/li&gt;&lt;li&gt;работа с input, textarea, Summernote и CKEditor;&lt;/li&gt;&lt;li&gt;последовательная обработка без резкой параллельной нагрузки на API;&lt;/li&gt;&lt;li&gt;сохранение полного контроля над результатом.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Для перевода можно использовать один из популярных профессиональных сервисов:&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;В отличие от простых модулей, которые переводят только видимые поля карточки товара, Translate Expert Pro умеет работать с безопасными мультиязычными таблицами базы данных.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;отсутствующие языковые ключи;&lt;/li&gt;&lt;li&gt;пустые переводы;&lt;/li&gt;&lt;li&gt;дублирующиеся ключи;&lt;/li&gt;&lt;li&gt;текст на другом языке;&lt;/li&gt;&lt;li&gt;ошибки кавычек и структуры PHP-строк;&lt;/li&gt;&lt;li&gt;неправильные апострофы;&lt;/li&gt;&lt;li&gt;скопированные файлы, которые не были переведены.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=59 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Translate Expert PRO accelerates multilingual OpenCart administration by translating supported text fields, rich editors, database language rows and PHP language files while protecting technical fragments.&lt;/p&gt;&lt;p&gt;Manual localization of products, categories, SEO fields and extension language files is repetitive and error-prone. The module brings translation tools into the admin workflow so content can be reviewed in context instead of copied back and forth through external services.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Multilingual stores, content teams and developers maintaining UA/RU/EN and additional language versions.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=59 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Translate Expert PRO ускоряет мультиязычную работу в админке OpenCart: переводит поддерживаемые поля, rich editors, language_id строки БД и PHP language-файлы с защитой технических фрагментов.&lt;/p&gt;&lt;p&gt;Ручная локализация товаров, категорий, SEO-полей и языковых файлов занимает много времени. Модуль переносит перевод в админку, чтобы результат можно было проверять в контексте.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Перевод полей прямо в админке&lt;/li&gt;&lt;li&gt;Автоопределение исходного языка&lt;/li&gt;&lt;li&gt;Товары, категории и статьи&lt;/li&gt;&lt;li&gt;Перевод language-файлов&lt;/li&gt;&lt;li&gt;Массовая обработка&lt;/li&gt;&lt;li&gt;Безопасное исключение технических полей&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Мультиязычным магазинам, контент-командам и разработчикам, которые поддерживают UA/RU/EN и другие языки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=59 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;p&gt;&lt;span&gt;🚀&lt;/span&gt; Sitemap PRO - комплексний SEO-модуль для автоматичного створення та оновлення XML-карт сайту в OpenCart 3.x та &lt;a href=&quot;https://opencartforum.com/opencart/&quot; rel=&quot;&quot;&gt;ocStore&lt;/a&gt; 3.0.x.&lt;/p&gt;&lt;p&gt;Модуль допомагає пошуковим системам швидше виявляти товари, категорії, виробників, інформаційні сторінки, статті, зображення та відео. Для кожної активної мови створюються окремі Sitemap-файли, а загальний Sitemap Index поєднує їх у єдину коректну структуру.&lt;/p&gt;&lt;p&gt;🗺 Звичайні XML Sitemap&lt;/p&gt;&lt;p&gt;Sitemap PRO формує карти товарів, категорій, виробників, інформаційних сторінок, статей та інших розділів магазину, що підтримуються.&lt;/p&gt;&lt;p&gt;Для кожної сторінки враховуються URL-адреса, дата зміни, частота оновлення та пріоритет. Можна вибрати формування посилань товарів без категорії або з головною категорією залежно від структури canonical URL конкретного сайту.&lt;/p&gt;&lt;p&gt;Великі карти автоматично поділяються на безпечні частини з урахуванням обмежень пошукових систем за кількістю URL та розміром файлу XML.&lt;/p&gt;&lt;p&gt;&lt;span&gt;🌍&lt;/span&gt; Мультимовність&lt;/p&gt;&lt;p&gt;Для кожної активної мови створюється власна карта сайту з правильними мовними URL.&lt;/p&gt;&lt;p&gt;Наприклад, магазин з українською, англійською, німецькою та датською мовами отримає окремі Sitemap-файли для кожної мови. Всі створені карти автоматично додаються до головного Sitemap Index.&lt;/p&gt;&lt;p&gt;Це дозволяє пошуковим системам правильно оминати та індексувати мультимовні версії сторінок без змішування URL різних мов.&lt;/p&gt;&lt;p&gt;&lt;span&gt;📸&lt;/span&gt; Image Sitemap&lt;/p&gt;&lt;p&gt;Модуль створює окремі карти зображень для товарів, категорій, виробників, статей та інформаційних сторінок.&lt;/p&gt;&lt;p&gt;У карту можуть включатись основні та додаткові зображення, а також фотографії, знайдені в описах. Sitemap PRO не створює і не перетискає зображення під час генерації XML, тому процес працює швидко і не створює надмірного навантаження на сервер.&lt;/p&gt;&lt;p&gt;При виборі WebP або AVIF модуль використовує готові файли, що вже існують. Якщо потрібний формат відсутній, застосовується оригінальне зображення.&lt;/p&gt;&lt;p&gt;У зв\'язку з AVIF WebP Image PRO модуль отримує готові оптимізовані зображення сучасних форматів та додає їх до Image Sitemap без повторної конвертації.&lt;/p&gt;&lt;p&gt;&lt;span&gt;🎬&lt;/span&gt; Video Sitemap&lt;/p&gt;&lt;p&gt;Sitemap PRO формує окремі карти відео для кожної активної мови магазину.&lt;/p&gt;&lt;p&gt;Для кожного відеозапису вказуються сторінка, прев\'ю, назва, опис та коректна URL-адреса програвача. Підтримуються дані YouTube та відео, додані через сумісні модулі.&lt;/p&gt;&lt;p&gt;У зв\'язку з Product Video Gallery PRO модуль автоматично отримує відео з карток товарів та створює повноцінні Video Sitemap. Це дозволяє одночасно показувати відео у товарній галереї, формувати VideoObject та передавати відеоконтент пошуковим системам.&lt;/p&gt;&lt;p&gt;&lt;span&gt;🔔&lt;/span&gt; Пінг пошукових систем&lt;/p&gt;&lt;p&gt;Після успішної генерації Sitemap модуль може надсилати повідомлення пошуковим системам про те, що картки сайту оновлені.&lt;/p&gt;&lt;p&gt;Пінг виконується лише після успішного запису файлів XML. При помилці генерації повідомлення не надсилається, а попередня робоча версія картки зберігається.&lt;/p&gt;&lt;p&gt;Функція допомагає швидше повідомляти пошукові системи про нові товари, змінені сторінки, зображення та відео без очікування наступного планового обходу сайту.&lt;/p&gt;&lt;p&gt;&lt;span&gt;⚙️&lt;/span&gt; Ручна та автоматична генерація&lt;/p&gt;&lt;p&gt;Всі карти можна створити однією кнопкою або оновити окремо:&lt;/p&gt;&lt;p&gt;звичайну карту конкретної мови;&lt;/p&gt;&lt;p&gt;Image Sitemap конкретної мови;&lt;/p&gt;&lt;p&gt;Video Sitemap конкретної мови;&lt;/p&gt;&lt;p&gt;всі мовні карти вибраного типу;&lt;/p&gt;&lt;p&gt;повний комплект Sitemap.&lt;/p&gt;&lt;p&gt;Для автоматизації підтримуються Cron та PHP CLI. Модуль виводить готові команди, включаючи формат налаштувань панелі Mirohost, і дозволяє копіювати їх одним натисканням.&lt;/p&gt;&lt;p&gt;Cron може створювати звичайні карти, зображення та відео за розкладом. Якщо окремий тип Sitemap вимкнено, він автоматично пропускається.&lt;/p&gt;&lt;p&gt;🛡 Безпечна генерація&lt;/p&gt;&lt;p&gt;Нові файли XML записуються атомарно. Існуюча робоча карта не видаляється до успішного завершення нової генерації.&lt;/p&gt;&lt;p&gt;Якщо процес перервано через тайм-аут, обмеження пам\'яті, помилки PHP або проблеми із записом файлу, модуль зберігає причину помилки і не залишає сайт без Sitemap.&lt;/p&gt;&lt;p&gt;При вимкненому статусі модуль не запускає генерацію, Cron, CLI та пінг пошукових систем.&lt;/p&gt;&lt;p&gt;&lt;span&gt;📊&lt;/span&gt; Діагностика та управління&lt;/p&gt;&lt;p&gt;В адміністративній панелі відображаються:&lt;/p&gt;&lt;p&gt;статус останньої генерації;&lt;/p&gt;&lt;p&gt;мова та виконаний етап;&lt;/p&gt;&lt;p&gt;кількість URL, зображень та відео;&lt;/p&gt;&lt;p&gt;кількість створених файлів;&lt;/p&gt;&lt;p&gt;час виконання;&lt;/p&gt;&lt;p&gt;використання пам\'яті;&lt;/p&gt;&lt;p&gt;повернення до оригінальних зображень;&lt;/p&gt;&lt;p&gt;пропущені та відсутні джерела;&lt;/p&gt;&lt;p&gt;докладні повідомлення про помилки.&lt;/p&gt;&lt;p&gt;Біля кожної картки доступна окрема перегенерація, копіювання адреси, відкриття XML та перевірка стану. Повна URL-адреса відображається при наведенні, навіть якщо поле візуально скорочено.&lt;/p&gt;&lt;p&gt;&lt;span&gt;🔗&lt;/span&gt; Єдина система CodeCart PRO&lt;/p&gt;&lt;p&gt;Sitemap PRO найбільш ефективно працює разом із двома додатковими модулями.&lt;/p&gt;&lt;p&gt;AVIF WebP Image PRO оптимізує оригінали, створює AVIF та WebP, обслуговує кеш та сучасні формати зображень.&lt;/p&gt;&lt;p&gt;Product Video Gallery PRO додає відео до галереї товару, підтримує популярні відеоплатформи та формує структуровані дані.&lt;/p&gt;&lt;p&gt;Sitemap PRO об\'єднує ст&lt;/p&gt;&lt;p&gt;ранки, зображення та відео в коректні XML-карти та повідомляє пошукові системи про оновлення.&lt;/p&gt;&lt;p&gt;Разом ці модулі створюють комплексну систему технічного SEO для інтернет-магазину.&lt;/p&gt;&lt;p&gt;&lt;span&gt;✅&lt;/span&gt; Сумісність&lt;/p&gt;&lt;p&gt;OpenCart 3.0.x.&lt;/p&gt;&lt;p&gt;&lt;a href=&quot;https://opencartforum.com/opencart/&quot; rel=&quot;&quot;&gt;ocStore&lt;/a&gt; 3.0.x,&lt;/p&gt;&lt;p&gt;PHP 7.4–8.5&lt;/p&gt;&lt;p&gt;Стандартні шаблони OpenCart.&lt;/p&gt;&lt;p&gt;UniShop2 3.6.x.&lt;/p&gt;&lt;p&gt;Мультимовні та мультимагазинні конфігурації.&lt;/p&gt;&lt;p&gt;Sitemap PRO – це зручне рішення для автоматичної індексації сторінок, зображень та відео, яке поєднує генерацію XML, Cron, пінг пошукових систем та детальну діагностику в одній професійній панелі.&lt;/p&gt;&lt;h3&gt;🔐 Важливо перед встановленням&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Перед встановленням або оновленням модуля обов’язково зробіть повну резервну копію файлів сайту та бази даних.&lt;/strong&gt; Після встановлення перевірте модуль на тестовому сценарії, а для OCMOD-рішень оновіть модифікатори та очистіть відповідний кеш.&lt;/p&gt;&lt;div class=&quot;ccp-demo&quot; style=&quot;background: rgb(247, 251, 255); border: 1px solid rgb(207, 224, 245); border-radius: 14px; padding: 20px 22px; margin: 22px 0px;&quot;&gt;&lt;h3 style=&quot;color: rgb(11, 79, 165); margin: 0px 0px 10px;&quot;&gt;🖥 Демо та перевірка перед купівлею&lt;/h3&gt;&lt;p style=&quot;color: rgb(31, 41, 55); margin: 0px;&quot;&gt;Тестова адмінка: &lt;a href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;https://demo.codecartpro.com/admin/&lt;/a&gt;&lt;br&gt;&lt;strong&gt;Логін:&lt;/strong&gt; Demo   &lt;strong&gt;Пароль:&lt;/strong&gt; Demo.&lt;/p&gt;&lt;p style=&quot;margin: 0px;&quot;&gt;&lt;font color=&quot;#9c0000&quot;&gt;&lt;span style=&quot;font-size: 13px;&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися; перевіряйте наявність потрібної функції перед купівлею.&lt;/span&gt;&lt;/font&gt;&lt;/p&gt;&lt;/div&gt;' WHERE `product_id`=62 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Sitemap PRO builds a configurable SEO sitemap for products, categories, manufacturers, information content, blog pages, images and multilingual URLs.&lt;/p&gt;&lt;p&gt;Large stores need more than a single opaque XML output: entity inclusion, lastmod, hreflang, images, file size and problematic URLs should be controllable so search engines receive a current and intentional site structure.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;SEO-focused stores with large or multilingual catalogs that need more control than the basic OpenCart sitemap.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=62 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Sitemap PRO формирует управляемую SEO-карту сайта для товаров, категорий, производителей, информации, блога, изображений и мультиязычных URL.&lt;/p&gt;&lt;p&gt;Большому магазину недостаточно одного непрозрачного XML: важно контролировать сущности, lastmod, hreflang, изображения, размер файлов и проблемные URL, чтобы поисковик получал актуальную структуру.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;XML sitemap для каталога&lt;/li&gt;&lt;li&gt;Товары и категории&lt;/li&gt;&lt;li&gt;Управление включением страниц&lt;/li&gt;&lt;li&gt;lastmod и пагинация&lt;/li&gt;&lt;li&gt;Мультиязычные URL&lt;/li&gt;&lt;li&gt;Диагностика и стабильная генерация&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Большим и мультиязычным магазинам, которым нужно больше контроля, чем даёт базовый sitemap OpenCart.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=62 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;AI Store Assistant PRO&lt;/strong&gt; перетворює звичайний інтернет-магазин на магазин з інтелектуальним консультантом. Покупець ставить питання своїми словами, а модуль розуміє запит, шукає відповідні товари в реальному каталозі, перевіряє актуальні характеристики, ціну та наявність, порівнює варіанти, показує картки товарів та допомагає перейти до покупки.&lt;/p&gt;&lt;p&gt; Головна перевага - робота з &lt;strong&gt;перевіреними даними магазину&lt;/strong&gt; . AI використовується для розуміння природної мови та ведення діалогу, а ціни, залишки, характеристики та товари перевіряються через інструменти OpenCart. Це значно знижує ризик вигаданих відповідей і робить AI справді корисним для реальних продажів.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Помічник розуміє продовження розмови. Після показу кількох моделей покупець може написати &quot;а другий скільки важить?&quot;, &quot;Покажи ще&quot;, &quot;є дешевше?&quot; або «який з них кращий?» - І модуль продовжить роботу з уже знайденими товарами.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;AI Store Assistant PRO вміє використовувати не лише товари, а й категорії, виробників, інформаційні сторінки, інструкції та статті магазину.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;✅ підбір товарів за запитом та характеристиками;&lt;/li&gt;&lt;li&gt;✅ порівняння кількох моделей;&lt;/li&gt;&lt;li&gt;✅ пошук аксесуарів та пов&amp;#x27;язаних товарів;&lt;/li&gt;&lt;li&gt;✅ виведення актуальних карток товарів;&lt;/li&gt;&lt;li&gt;✅ перехід за посиланням безпосередньо на товар;&lt;/li&gt;&lt;li&gt;✅ додавання товару до кошика за безпечних умов;&lt;/li&gt;&lt;li&gt;✅ орієнтовний розрахунок доставки через активні способи доставки OpenCart;&lt;/li&gt;&lt;li&gt;✅ опціональна безпечна перевірка статусу замовлення;&lt;/li&gt;&lt;li&gt;✅ передача розмови живому менеджеру.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=63 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Store Assistant PRO is a storefront sales consultant that understands natural-language questions, searches the real catalog and verifies current product data before answering.&lt;/p&gt;&lt;p&gt;AI is used to understand intent and conduct the conversation, while product links, prices, stock and characteristics are checked against OpenCart data. This separation reduces hallucinated catalog facts and makes the assistant useful for real product selection.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Natural-language product search with support for models, brands, units and follow-up questions.&lt;/li&gt;&lt;li&gt;Live verification of current product price, special price and stock before the answer.&lt;/li&gt;&lt;li&gt;Product cards and links refer to the exact products mentioned by the assistant.&lt;/li&gt;&lt;li&gt;Knowledge sources can include products, categories, manufacturers, information pages and supported blog/news content.&lt;/li&gt;&lt;li&gt;Persistent local knowledge index with optional semantic search for indirect queries.&lt;/li&gt;&lt;li&gt;Product comparison, related/accessory search and safe add-to-cart scenarios.&lt;/li&gt;&lt;li&gt;Lead capture and handoff to a human manager with conversation context.&lt;/li&gt;&lt;li&gt;Two-way Telegram workflow for manager takeover and return to AI.&lt;/li&gt;&lt;li&gt;Multiple AI providers/models with controlled fallback.&lt;/li&gt;&lt;li&gt;Dialog history, leads, ratings, logs, conversion-related events and regression tests.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Technical, B2B and large-catalog stores where customers need help choosing products, comparing models or escalating to a human manager.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=63 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Store Assistant PRO — витринный продавец-консультант, который понимает вопросы обычным языком, ищет товары в реальном каталоге и проверяет актуальные данные перед ответом.&lt;/p&gt;&lt;p&gt;AI отвечает за понимание запроса и диалог, а ссылки, цены, остатки и характеристики проверяются по данным OpenCart. Это снижает риск выдуманных фактов и делает помощника полезным для реального подбора.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Поиск товаров обычным языком с распознаванием моделей, брендов, единиц и уточняющих вопросов.&lt;/li&gt;&lt;li&gt;Проверка актуальной цены, акции и остатка непосредственно перед ответом.&lt;/li&gt;&lt;li&gt;Карточки и ссылки ведут именно на товары, названные консультантом.&lt;/li&gt;&lt;li&gt;База знаний может включать товары, категории, производителей, информационные страницы и поддерживаемый блог/новости.&lt;/li&gt;&lt;li&gt;Постоянный локальный индекс знаний и опциональный semantic search для непрямых запросов.&lt;/li&gt;&lt;li&gt;Сравнение товаров, поиск аксессуаров/аналогов и безопасные add-to-cart сценарии.&lt;/li&gt;&lt;li&gt;Сбор лида и передача живому менеджеру вместе с контекстом диалога.&lt;/li&gt;&lt;li&gt;Двусторонняя работа через Telegram: менеджер принимает диалог и затем может вернуть его AI.&lt;/li&gt;&lt;li&gt;Несколько AI-провайдеров/моделей с контролируемым fallback.&lt;/li&gt;&lt;li&gt;История диалогов, лиды, оценки, логи, конверсионные события и регрессионные тесты.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Техническим, B2B и большим магазинам, где покупателю нужна помощь с выбором, сравнением моделей и передачей диалога менеджеру.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=63 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Abandoned Cart PRO&lt;/strong&gt; — професійний модуль для OpenCart та ocStore, який допомагає повертати покупців, що додали товари до кошика, але не завершили оформлення замовлення.&lt;/p&gt;&lt;p&gt;Замість того щоб назавжди втрачати такого клієнта, магазин може зберегти покинутий кошик, автоматично надіслати персональне нагадування та повернути покупця безпосередньо до вибраних товарів.&lt;/p&gt;&lt;p&gt;💰 &lt;strong&gt;Головна користь модуля — робота з уже залученими покупцями.&lt;/strong&gt; Магазин уже витратив кошти на рекламу, SEO, контент або інші канали залучення. Abandoned Cart PRO допомагає отримати додаткові замовлення від відвідувачів, які були максимально близькими до покупки.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Для покинутих кошиків можна налаштувати автоматичну серію нагадувань із потрібною періодичністю та кількістю відправлень.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;У комплекті передбачено кілька готових варіантів оформлення email-повідомлень для різних мов.&lt;/p&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=64 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Abandoned Cart PRO records incomplete carts, sends scheduled reminders and helps a customer return to the same cart through a personal recovery link.&lt;/p&gt;&lt;p&gt;A cart that was not checked out is not always a lost customer: the buyer may have been distracted, postponed the decision or closed the site. Timely reminders can recover some of that existing purchase intent without buying the traffic again.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores with meaningful cart abandonment and email marketing workflows, including UniShop2 quick-order scenarios where supported.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=64 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Abandoned Cart PRO сохраняет незавершённые корзины, отправляет напоминания по расписанию и возвращает покупателя в его корзину по персональной ссылке.&lt;/p&gt;&lt;p&gt;Незавершённая корзина не всегда означает потерянного клиента: покупатель мог отвлечься, отложить решение или закрыть сайт. Напоминание даёт шанс вернуть уже существующий интерес без повторной покупки трафика.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Сбор брошенных корзин и контактов&lt;/li&gt;&lt;li&gt;Email-напоминания по расписанию&lt;/li&gt;&lt;li&gt;Персональное восстановление корзины&lt;/li&gt;&lt;li&gt;Купоны для возврата клиента&lt;/li&gt;&lt;li&gt;Статистика, журнал и cron&lt;/li&gt;&lt;li&gt;Поддержка UniShop2 checkout&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с заметным количеством брошенных корзин и email-маркетингом, включая поддерживаемые UniShop2 Quick Order сценарии.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=64 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Attribute Manager PRO&lt;/strong&gt; допомагає системно керувати характеристиками товарів: створювати набори атрибутів, повторно використовувати їх у різних товарах і швидше заповнювати технічні параметри каталогу.&lt;/p&gt;&lt;p&gt;Модуль особливо корисний для техніки, обладнання, запчастин, електроніки та інших категорій, де картка товару містить десятки характеристик. Він зменшує ручне дублювання однакових полів і допомагає підтримувати єдину структуру даних.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Створення та повторне використання шаблонів характеристик.&lt;/li&gt;&lt;li&gt;Масове додавання атрибутів до вибраних товарів.&lt;/li&gt;&lt;li&gt;Швидке заповнення типових груп характеристик для однотипних товарів.&lt;/li&gt;&lt;li&gt;Контроль структури атрибутів і зменшення дублювання однакових назв.&lt;/li&gt;&lt;li&gt;Зручніший сценарій роботи з великими категоріями товарів.&lt;/li&gt;&lt;li&gt;Допомагає підготувати чисті характеристики для фільтрів, порівняння та SEO.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Єдина структура характеристик робить каталог зрозумілішим для покупця і спрощує подальше використання атрибутів у фільтрах та порівнянні.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам техніки, інструменту, агротоварів, запчастин, електроніки та будь-яким каталогам із великою кількістю характеристик.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=65 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Attribute Manager PRO turns repeated product characteristics into reusable attribute templates and bulk catalog workflows.&lt;/p&gt;&lt;p&gt;Technical catalogs often repeat the same groups of parameters across hundreds of products. Templates and controlled bulk actions reduce duplicate attribute names and make filter/comparison data more consistent.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Equipment, parts, electronics and other stores with many structured product characteristics.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=65 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Attribute Manager PRO превращает повторяющиеся характеристики товаров в шаблоны и управляемые массовые операции.&lt;/p&gt;&lt;p&gt;В техническом каталоге одни и те же группы параметров повторяются в сотнях товаров. Шаблоны уменьшают дубли названий и делают данные для фильтра/сравнения более единообразными.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Шаблоны групп характеристик&lt;/li&gt;&lt;li&gt;Импорт атрибутов из товара&lt;/li&gt;&lt;li&gt;Добавление, замена или обновление&lt;/li&gt;&lt;li&gt;Быстрое создание атрибутов&lt;/li&gt;&lt;li&gt;Штатное сохранение товара&lt;/li&gt;&lt;li&gt;Удобно для больших каталогов&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам техники, запчастей, электроники и другим каталогам с большим количеством характеристик.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=65 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;AVIF WebP Image PRO&lt;/strong&gt; оптимізує систему зображень OpenCart та допомагає використовувати сучасні формати WebP і AVIF, зменшуючи вагу сторінок без ручної конвертації кожної фотографії.&lt;/p&gt;&lt;p&gt;Фото часто займають найбільшу частину сторінки товару. Модуль потрібен, щоб автоматизувати створення оптимізованих версій, контролювати підтримку форматів на сервері та зберігати стабільну роботу стандартного механізму resize.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Підтримка WebP та AVIF для зображень каталогу.&lt;/li&gt;&lt;li&gt;Робота через стандартний механізм resize OpenCart замість окремої несумісної галереї.&lt;/li&gt;&lt;li&gt;Перевірка підтримки GD, WebP, AVIF та Imagick на сервері.&lt;/li&gt;&lt;li&gt;Діагностика доступності кешу зображень для запису.&lt;/li&gt;&lt;li&gt;Черга для керованої оптимізації оригінальних зображень.&lt;/li&gt;&lt;li&gt;Очищення службових метаданих і обслуговування через cron там, де це передбачено.&lt;/li&gt;&lt;li&gt;Можливість працювати з великим каталогом пакетами, без спроби обробити все за один запит.&lt;/li&gt;&lt;li&gt;Орієнтація на швидкість сторінок, PageSpeed і Core Web Vitals.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Сучасні формати дозволяють зменшити трафік і прискорити завантаження каталогу, особливо на мобільних пристроях.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із великою кількістю фотографій, UniShop2, мобільним трафіком і вимогами до швидкості завантаження.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;li&gt;GD / Imagick — залежно від доступних функцій сервера&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=66 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AVIF WebP Image PRO integrates modern WebP/AVIF image generation into the OpenCart image pipeline with server diagnostics, caching and controlled processing.&lt;/p&gt;&lt;p&gt;Images are often the heaviest part of product and category pages. Modern formats can reduce transfer size, but a production store also needs browser/server fallbacks and safe cache behavior rather than blind file replacement.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Image-heavy stores and UniShop2 installations focused on page speed, mobile traffic and Core Web Vitals.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=66 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AVIF WebP Image PRO интегрирует WebP/AVIF в стандартный процесс изображений OpenCart с диагностикой сервера, кешированием и контролируемой обработкой.&lt;/p&gt;&lt;p&gt;Изображения часто занимают основную часть веса страницы. Современные форматы уменьшают трафик, но рабочему магазину нужны fallback и безопасный cache, а не слепая замена исходников.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;WebP и AVIF без замены оригиналов&lt;/li&gt;&lt;li&gt;Fallback для совместимости браузеров&lt;/li&gt;&lt;li&gt;Настройка качества&lt;/li&gt;&lt;li&gt;Диагностика GD и Imagick&lt;/li&gt;&lt;li&gt;Cron-прогрев кеша&lt;/li&gt;&lt;li&gt;Безопасное обслуживание изображений&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с большим количеством фото и UniShop2, где важны скорость, мобильный трафик и Core Web Vitals.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=66 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Catalog Quality Audit PRO&lt;/strong&gt; допомагає знаходити проблеми в картках товарів до того, як їх побачить покупець або пошукова система. Модуль перевіряє заповнення каталогу й формує зрозумілий список позицій, які потребують уваги.&lt;/p&gt;&lt;p&gt;У великому магазині легко пропустити товар без фото, опису, метаданих, характеристик або інших важливих даних. Ручна перевірка сотень сторінок займає багато часу, тому аудит краще виконувати централізовано.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Перевірка якості та повноти карток товарів.&lt;/li&gt;&lt;li&gt;Пошук товарів із відсутніми або слабко заповненими даними.&lt;/li&gt;&lt;li&gt;Контроль зображень, описів, SEO-полів та інших важливих елементів каталогу.&lt;/li&gt;&lt;li&gt;Фільтрація результатів за типом проблеми.&lt;/li&gt;&lt;li&gt;Зручний перехід від знайденої проблеми до редагування товару.&lt;/li&gt;&lt;li&gt;Підходить для регулярної перевірки після імпорту або масових змін.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль не генерує якість автоматично, а показує, де саме каталог потребує доопрацювання. Це дає адміністратору контроль і не створює прихованих масових змін.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Власникам магазинів, SEO-фахівцям, контент-менеджерам і веб-студіям, які підтримують великий каталог.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=67 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Catalog Quality Audit PRO checks product, category and manufacturer data for missing, duplicated or weakly populated fields before those problems reach customers or search engines.&lt;/p&gt;&lt;p&gt;As a catalog grows, missing images, SEO fields, identifiers and inconsistent relationships become hard to spot manually. A centralized audit shows where attention is needed without changing the data automatically.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Store owners, SEO specialists and content teams maintaining medium or large catalogs.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=67 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Catalog Quality Audit PRO проверяет товары, категории и производителей на отсутствующие, дублированные и слабо заполненные данные.&lt;/p&gt;&lt;p&gt;С ростом каталога вручную сложно заметить отсутствие фото, SEO-полей, идентификаторов и ошибки связей. Централизованный аудит показывает проблемные места без автоматического изменения данных.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Аудит товаров, категорий и брендов&lt;/li&gt;&lt;li&gt;Поиск дублей и SEO keyword&lt;/li&gt;&lt;li&gt;Контроль meta title и description&lt;/li&gt;&lt;li&gt;Проверка изображений и цен&lt;/li&gt;&lt;li&gt;CSV-отчёты и сохранённые фильтры&lt;/li&gt;&lt;li&gt;Admin-only без нагрузки витрины&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Владельцам магазинов, SEO-специалистам и контент-командам средних и больших каталогов.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=67 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Checkout Simple PRO&lt;/strong&gt; робить checkout коротшим і зрозумілішим: покупець бачить тільки потрібні поля, а сума, доставка та оплата оновлюються без зайвих переходів між стандартними кроками OpenCart.&lt;/p&gt;&lt;p&gt;Модуль потрібен магазинам, де стандартне оформлення створює зайве тертя. Чим менше непотрібних полів і повторних завантажень, тим простіше клієнту завершити покупку.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Гостьове оформлення замовлення без обов’язкової реєстрації.&lt;/li&gt;&lt;li&gt;Гнучке керування полями checkout: показ, обов’язковість і порядок.&lt;/li&gt;&lt;li&gt;AJAX-перерахунок підсумків без повного перезавантаження сторінки.&lt;/li&gt;&lt;li&gt;Робота зі стандартними способами доставки й оплати OpenCart.&lt;/li&gt;&lt;li&gt;Інтеграція зі сценаріями доставки Новою поштою, якщо відповідний модуль доступний.&lt;/li&gt;&lt;li&gt;Сумісність із UniShop2 та типовими AJAX-сценаріями оформлення.&lt;/li&gt;&lt;li&gt;Збереження стандартної логіки створення замовлення OpenCart.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Головна перевага — зменшення кількості дій між кошиком і завершеним замовленням без відмови від стандартної моделі даних OpenCart.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із мобільним трафіком, UniShop2, великою часткою гостьових покупців або високим відсотком відмов на етапі checkout.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=68 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Checkout Simple PRO shortens the OpenCart checkout flow by keeping only the required fields and updating totals, shipping and payment without unnecessary full-page steps.&lt;/p&gt;&lt;p&gt;Every unnecessary field or reload between cart and order completion adds friction. The module focuses on a simpler guest-friendly checkout while preserving the standard OpenCart order model and configured shipping/payment methods.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores with mobile traffic, guest checkout and measurable drop-off during the standard checkout process.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=68 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Checkout Simple PRO сокращает оформление OpenCart: оставляет нужные поля и обновляет итоги, доставку и оплату без лишних полноэкранных шагов.&lt;/p&gt;&lt;p&gt;Каждое ненужное поле и перезагрузка между корзиной и заказом добавляет трение. Модуль упрощает guest checkout, сохраняя стандартную модель заказа и настроенные способы доставки/оплаты.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Компактный checkout&lt;/li&gt;&lt;li&gt;Управление полями формы&lt;/li&gt;&lt;li&gt;Адаптивный интерфейс&lt;/li&gt;&lt;li&gt;Меньше шагов до заказа&lt;/li&gt;&lt;li&gt;Совместимость со штатной логикой&lt;/li&gt;&lt;li&gt;Понятный UX без перегрузки&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с мобильным трафиком, гостевыми заказами и заметными отказами на стандартном checkout.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=68 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;EU Cookie Consent PRO&lt;/strong&gt; керує згодою користувача на cookie та допомагає магазину коректно працювати з аналітичними й рекламними сервісами до і після вибору відвідувача.&lt;/p&gt;&lt;p&gt;Простого банера «ми використовуємо cookie» недостатньо, якщо сайт запускає аналітику або рекламу до отримання згоди. Модуль потрібен для керованої логіки категорій cookie та передачі стану згоди в Google-інструменти.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Банер згоди з налаштовуваним текстом і діями користувача.&lt;/li&gt;&lt;li&gt;Розподіл cookie за категоріями та можливість керувати згодою.&lt;/li&gt;&lt;li&gt;Підтримка Google Consent Mode v2.&lt;/li&gt;&lt;li&gt;Сценарії для Google Tag Manager, Analytics і Ads.&lt;/li&gt;&lt;li&gt;Збереження вибору користувача та журнал згод там, де він увімкнений.&lt;/li&gt;&lt;li&gt;Мультимовні тексти для різних мов магазину.&lt;/li&gt;&lt;li&gt;Адаптація для UniShop2 та мобільної витрини.&lt;/li&gt;&lt;li&gt;Можливість повторно відкрити налаштування cookie.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає відокремити необхідні cookie від аналітичних і рекламних та не запускати необов’язкові сценарії до відповідної згоди.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які працюють із користувачами ЄС/ЄЕЗ, Google Analytics, Google Ads, GTM та іншими сервісами, що використовують необов’язкові cookie.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=69 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;EU Cookie Consent PRO manages cookie consent categories and Google Consent Mode v2 so analytics/advertising behavior can follow the visitor\'s choice.&lt;/p&gt;&lt;p&gt;A banner alone is not enough if optional analytics or advertising scripts run before consent. The module provides a controlled consent state and integration points, while the store owner remains responsible for the legal wording and policy.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores serving EU/EEA visitors and using Google Analytics, Ads, GTM or other optional-cookie services.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=69 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;EU Cookie Consent PRO управляет категориями cookie и Google Consent Mode v2, чтобы аналитика и реклама учитывали выбор посетителя.&lt;/p&gt;&lt;p&gt;Одного баннера недостаточно, если необязательные скрипты запускаются до согласия. Модуль хранит управляемое состояние consent, а владелец сайта остаётся ответственным за юридические тексты и политику.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Категории cookies и согласия&lt;/li&gt;&lt;li&gt;Управление аналитическими скриптами&lt;/li&gt;&lt;li&gt;Мультиязычный баннер&lt;/li&gt;&lt;li&gt;Настройка дизайна&lt;/li&gt;&lt;li&gt;Повторное открытие настроек&lt;/li&gt;&lt;li&gt;Ориентация на GDPR/ePrivacy&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с посетителями из ЕС/ЕЭЗ, Google Analytics, Ads, GTM и другими сервисами необязательных cookie.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=69 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Expert Author Schema PRO&lt;/strong&gt; додає до контентних сторінок зрозумілий блок автора/експерта та структуровані дані Schema.org, щоб явно показати, хто підготував матеріал і яка організація стоїть за сайтом.&lt;/p&gt;&lt;p&gt;Модуль корисний для інформаційних матеріалів, технічних статей, категорій і блогів, де важливі прозоре авторство, довіра та коректна структурована розмітка.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Видимий експертний блок із даними автора.&lt;/li&gt;&lt;li&gt;JSON-LD Schema без необхідності вручну вставляти script у кожну статтю.&lt;/li&gt;&lt;li&gt;Підтримка Article і BlogPosting для контентних матеріалів.&lt;/li&gt;&lt;li&gt;Підтримка CollectionPage для категорій.&lt;/li&gt;&lt;li&gt;Підтримка Organization там, де це доречно.&lt;/li&gt;&lt;li&gt;Робота зі стандартним блогом ocStore.&lt;/li&gt;&lt;li&gt;Підтримка новин і категорій UniShop2.&lt;/li&gt;&lt;li&gt;Можливість підключення до вибраних маршрутів OpenCart.&lt;/li&gt;&lt;li&gt;Режим тільки Schema або видимий блок + Schema.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Правильне авторство робить контент зрозумілішим для користувача і допомагає не змішувати експертні матеріали з анонімними текстами.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із блогом, технічними статтями, експертними оглядами, новинами та інформаційними категоріями.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=70 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Expert Author Schema PRO adds visible author/expert information and corresponding Schema.org data to supported content pages.&lt;/p&gt;&lt;p&gt;Clear authorship helps visitors understand who prepared an article or expert material. The module can add Article/BlogPosting/CollectionPage/Organization-related data, but existing theme/SEO Schema should be checked first to avoid duplicates.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores with blogs, technical articles, expert reviews and content where transparent authorship matters.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=70 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Expert Author Schema PRO добавляет видимый блок автора/эксперта и соответствующие Schema.org данные на поддерживаемые контентные страницы.&lt;/p&gt;&lt;p&gt;Понятное авторство показывает, кто подготовил материал. Модуль может добавлять Article/BlogPosting/CollectionPage/Organization данные, но сначала нужно проверить Schema темы/SEO-модуля, чтобы не получить дубли.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Профили авторов и экспертов&lt;/li&gt;&lt;li&gt;Авторский блок в контенте&lt;/li&gt;&lt;li&gt;Schema.org для авторства&lt;/li&gt;&lt;li&gt;Поддержка SEO и E-E-A-T&lt;/li&gt;&lt;li&gt;Мультиязычные данные&lt;/li&gt;&lt;li&gt;Контроль отображения в админке&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с блогом, техническими статьями и экспертным контентом, где важно прозрачное авторство.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=70 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Google Reviews PRO&lt;/strong&gt; інтегрує сценарії Google Customer Reviews у магазин OpenCart та допомагає коректно передавати дані замовлення для запрошення покупця залишити відгук.&lt;/p&gt;&lt;p&gt;Модуль потрібен магазинам, які використовують екосистему Google і хочуть підвищувати довіру за рахунок підтверджених відгуків та рейтингових елементів Google.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Інтеграція Google Customer Reviews.&lt;/li&gt;&lt;li&gt;Налаштування Merchant ID.&lt;/li&gt;&lt;li&gt;Підтримка рейтингового badge Google, якщо він доступний для акаунта.&lt;/li&gt;&lt;li&gt;Передача даних замовлення, необхідних для опитування покупця.&lt;/li&gt;&lt;li&gt;Робота з GTIN товарів там, де Google використовує товарні ідентифікатори.&lt;/li&gt;&lt;li&gt;Діагностика основних налаштувань інтеграції.&lt;/li&gt;&lt;li&gt;OCMOD-підключення без ручного редагування ядра.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Відгук після реальної покупки має вищу довіру, ніж випадковий текст у картці товару. Google Customer Reviews допомагає будувати репутацію магазину на основі завершених замовлень.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які працюють із Google Merchant Center, Google Shopping або хочуть посилити довіру до бренду через відгуки Google.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=71 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Google Reviews PRO integrates the official Google Customer Reviews opt-in flow and related store-rating elements after a completed order.&lt;/p&gt;&lt;p&gt;The review is collected by Google from a real buyer, not generated by the module. Correct Merchant ID, order data and Google program eligibility remain required.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores using Google Merchant Center / Customer Reviews that want official post-purchase review collection.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=71 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Google Reviews PRO подключает официальный Google Customer Reviews opt-in и связанные рейтинговые элементы после завершённого заказа.&lt;/p&gt;&lt;p&gt;Отзыв собирает Google у реального покупателя — модуль его не генерирует. Для работы нужны корректный Merchant ID, данные заказа и соответствие требованиям программы Google.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Импорт и показ Google-отзывов&lt;/li&gt;&lt;li&gt;Рейтинг и количество отзывов&lt;/li&gt;&lt;li&gt;Адаптивный блок на витрине&lt;/li&gt;&lt;li&gt;Управление отображением&lt;/li&gt;&lt;li&gt;Кеширование данных&lt;/li&gt;&lt;li&gt;Усиление доверия к магазину&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с Google Merchant Center / Customer Reviews, которым нужен официальный сбор отзывов после покупки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=71 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Nova Poshta PRO&lt;/strong&gt; автоматизує вибір доставки Новою поштою в checkout і роботу менеджера з відправленнями після оформлення замовлення.&lt;/p&gt;&lt;p&gt;Модуль прибирає ручне введення міст і відділень, допомагає використовувати актуальні довідники та скорочує кількість помилок під час створення відправлення.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Вибір міста та відділення Нової пошти у checkout.&lt;/li&gt;&lt;li&gt;Робота з API Нової пошти та актуальними довідниками.&lt;/li&gt;&lt;li&gt;Підтримка адресної доставки там, де вона налаштована.&lt;/li&gt;&lt;li&gt;Розрахунок і відображення умов доставки відповідно до конфігурації магазину.&lt;/li&gt;&lt;li&gt;Створення та робота з ТТН із замовлення.&lt;/li&gt;&lt;li&gt;Збереження службових даних доставки в контексті замовлення.&lt;/li&gt;&lt;li&gt;Контроль статусу відправлення.&lt;/li&gt;&lt;li&gt;Email-повідомлення клієнту про зміну статусу ТТН, якщо функція ввімкнена.&lt;/li&gt;&lt;li&gt;Діагностика API та журнал для пошуку проблем інтеграції.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Покупець отримує зрозумілий вибір доставки, а менеджер — менше ручної роботи після замовлення.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Українським магазинам, які регулярно відправляють замовлення Новою поштою та хочуть пов’язати checkout із подальшою роботою менеджера.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=72 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Nova Poshta PRO connects OpenCart checkout and order management with Nova Poshta city/branch data and shipment workflows.&lt;/p&gt;&lt;p&gt;Manual city and branch entry creates avoidable mistakes. API-backed selection and shipment data reduce routine work for both the buyer and the order manager.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Ukrainian stores that regularly ship orders through Nova Poshta and want checkout plus post-order logistics in one workflow.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=72 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Nova Poshta PRO связывает checkout OpenCart и работу менеджера с городами/отделениями Новой почты и сценариями отправки.&lt;/p&gt;&lt;p&gt;Ручной ввод города и отделения создаёт лишние ошибки. API-выбор и данные отправления уменьшают рутину для покупателя и менеджера.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Города и отделения Новой Почты&lt;/li&gt;&lt;li&gt;Поиск и выбор в checkout&lt;/li&gt;&lt;li&gt;Обновление справочников&lt;/li&gt;&lt;li&gt;Удобный мобильный выбор&lt;/li&gt;&lt;li&gt;Настройка способа доставки&lt;/li&gt;&lt;li&gt;Интеграция с заказом OpenCart&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Украинским магазинам, которые регулярно отправляют заказы Новой почтой и хотят связать checkout с дальнейшей логистикой.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=72 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Import Export PRO&lt;/strong&gt; призначений для масової роботи з товарами, прайсами постачальників і зовнішніми фідами. Модуль допомагає переносити великі обсяги даних без ручного редагування кожної картки.&lt;/p&gt;&lt;p&gt;Це інструмент для регулярного оновлення цін, залишків, описів, зображень та інших товарних даних із контрольованим сценарієм імпорту й експорту.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Імпорт товарів із CSV, XLSX, XML, JSON та інших підтримуваних джерел.&lt;/li&gt;&lt;li&gt;Робота з локальними файлами та публічними URL постачальників.&lt;/li&gt;&lt;li&gt;Підтримка Basic Auth для закритих фідів.&lt;/li&gt;&lt;li&gt;Оновлення існуючих товарів і додавання нових за вибраним ідентифікатором.&lt;/li&gt;&lt;li&gt;Масова робота з цінами, залишками, описами, SEO-полями та зображеннями.&lt;/li&gt;&lt;li&gt;Очищення HTML, невидимих символів і типового сміття з Excel/Word перед записом.&lt;/li&gt;&lt;li&gt;Експорт каталогу для подальшої обробки або передачі.&lt;/li&gt;&lt;li&gt;Cron-режими для регулярних задач там, де вони налаштовані.&lt;/li&gt;&lt;li&gt;Пакетна обробка, щоб не намагатися завантажити великий каталог одним HTTP-запитом.&lt;/li&gt;&lt;li&gt;Журнал і діагностика для контролю помилок імпорту.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Масовий імпорт завжди має ризик вплинути на тисячі записів, тому головна цінність модуля — не тільки швидкість, а й контроль над тим, що саме оновлюється.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із прайсами постачальників, великим каталогом, частими змінами цін/залишків або необхідністю експортувати дані для зовнішніх систем.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=73 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Import Export PRO performs bulk import, update and export of product catalog data from common supplier and exchange formats.&lt;/p&gt;&lt;p&gt;The module is intended for recurring mass work with prices, stock, descriptions, images and SEO data, where controlled field mapping and batching are safer than editing thousands of products manually.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores with supplier price lists, large catalogs or frequent bulk updates and exports.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=73 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Import Export PRO выполняет массовый импорт, обновление и экспорт каталога из распространённых форматов поставщиков и обмена.&lt;/p&gt;&lt;p&gt;Модуль предназначен для регулярной массовой работы с ценами, остатками, описаниями, изображениями и SEO, где mapping и batch безопаснее ручного редактирования тысяч товаров.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Массовый импорт товаров&lt;/li&gt;&lt;li&gt;Экспорт каталога&lt;/li&gt;&lt;li&gt;Обновление существующих записей&lt;/li&gt;&lt;li&gt;Контроль полей и соответствий&lt;/li&gt;&lt;li&gt;Пакетная обработка больших каталогов&lt;/li&gt;&lt;li&gt;Журнал и диагностика&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с прайсами поставщиков, большим каталогом и частыми массовыми обновлениями/выгрузками.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=73 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Language Suggest PRO&lt;/strong&gt; визначає, що відвідувачу може бути зручніша інша мовна версія магазину, і акуратно пропонує перейти на неї без примусового редиректу.&lt;/p&gt;&lt;p&gt;Модуль покращує UX мультимовного магазину: користувач сам приймає рішення, а його поточний маршрут не змінюється без згоди.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Підказка переходу на відповідну мову магазину.&lt;/li&gt;&lt;li&gt;Без примусового редиректу.&lt;/li&gt;&lt;li&gt;Компактна панель або модальне вікно.&lt;/li&gt;&lt;li&gt;Розташування зверху, знизу або по центру.&lt;/li&gt;&lt;li&gt;Мультимовні тексти за language_id.&lt;/li&gt;&lt;li&gt;Змінні {current_language}, {suggested_language}, {store_name}.&lt;/li&gt;&lt;li&gt;Налаштування кольорів, скруглення та ширини.&lt;/li&gt;&lt;li&gt;Виключення маршрутів із wildcard-масками.&lt;/li&gt;&lt;li&gt;Безпечне виключення checkout/*, account/* та api/*.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Користувач не втрачає сторінку, на яку прийшов із пошуку або реклами, і не потрапляє на іншу мову без свого рішення.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Мультимовним магазинам в Україні та ЄС, де важливо запропонувати правильну мову без агресивних автоматичних перенаправлень.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=74 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Language Suggest PRO detects that another storefront language may be more convenient and politely suggests switching without forcing a redirect.&lt;/p&gt;&lt;p&gt;A forced redirect can break the landing page a visitor came from and create a poor experience. The module leaves the decision to the user while preserving multilingual context.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Multilingual stores serving audiences that commonly arrive with a browser language different from the current storefront language.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=74 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Language Suggest PRO определяет, что посетителю может быть удобнее другая языковая версия, и аккуратно предлагает переключиться без принудительного редиректа.&lt;/p&gt;&lt;p&gt;Принудительный редирект может увести пользователя со страницы входа и ухудшить UX. Модуль оставляет решение пользователю и сохраняет контекст мультиязычного сайта.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Определение языкового контекста&lt;/li&gt;&lt;li&gt;Ненавязчивая подсказка&lt;/li&gt;&lt;li&gt;Мультиязычный текст&lt;/li&gt;&lt;li&gt;Запоминание выбора&lt;/li&gt;&lt;li&gt;Адаптивное отображение&lt;/li&gt;&lt;li&gt;Без принудительного SEO-редиректа&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Мультиязычным магазинам, где язык браузера посетителя часто отличается от текущей версии витрины.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=74 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Link Checker PRO&lt;/strong&gt; сканує сайт і допомагає знаходити биті внутрішні посилання, помилки 4xx/5xx, небажані редиректи, недоступні зображення та інші URL-проблеми.&lt;/p&gt;&lt;p&gt;Після імпорту товарів, зміни SEO URL, видалення категорій або редизайну на сайті часто залишаються старі посилання. Модуль показує не лише проблемний URL, а й сторінку-джерело, де його потрібно виправити.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Перевірка внутрішніх URL.&lt;/li&gt;&lt;li&gt;Пошук HTTP-помилок 4xx і 5xx.&lt;/li&gt;&lt;li&gt;Пошук редиректів, які доцільно замінити кінцевою адресою.&lt;/li&gt;&lt;li&gt;Перевірка зображень, lazy-load джерел і статичних файлів.&lt;/li&gt;&lt;li&gt;Опціональна перевірка зовнішніх посилань із захистом від приватних/локальних адрес.&lt;/li&gt;&lt;li&gt;Старт зі сторінки, sitemap.xml або власного списку URL.&lt;/li&gt;&lt;li&gt;Підтримка sitemap index першого рівня та gzip-карти за наявності gzdecode.&lt;/li&gt;&lt;li&gt;Налаштування глибини, ліміту URL, таймаута, затримки й розміру пакета.&lt;/li&gt;&lt;li&gt;Фільтрація результатів за типом проблеми.&lt;/li&gt;&lt;li&gt;Cron для регулярної технічної перевірки, якщо потрібна автоматизація.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Биті посилання погіршують UX, створюють зайві переходи для пошукового робота й часто маскують помилки після масових змін.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;SEO-фахівцям, адміністраторам, магазинам після міграції, імпорту, зміни SEO URL або великих змін структури.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=75 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Link Checker PRO crawls configured site URLs to find broken internal links, HTTP errors, redirects, inaccessible images and other URL problems.&lt;/p&gt;&lt;p&gt;After imports, SEO URL changes and content cleanup, old links often remain in product/category/article text. The useful result is not only the bad URL but also the source page where it can be fixed.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;SEO specialists and stores after migration, imports or major URL/content changes.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=75 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Link Checker PRO сканирует сайт и ищет битые внутренние ссылки, HTTP-ошибки, редиректы, недоступные изображения и другие URL-проблемы.&lt;/p&gt;&lt;p&gt;После импорта, смены SEO URL и чистки контента старые ссылки остаются в описаниях. Важно видеть не только плохой URL, но и страницу-источник, где его нужно исправить.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Поиск 404 и ошибочных URL&lt;/li&gt;&lt;li&gt;Проверка внутренних ссылок&lt;/li&gt;&lt;li&gt;Статусы HTTP-ответов&lt;/li&gt;&lt;li&gt;Фильтры результатов&lt;/li&gt;&lt;li&gt;Пакетное сканирование&lt;/li&gt;&lt;li&gt;SEO-контроль структуры сайта&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;SEO-специалистам и магазинам после миграции, импорта или крупных изменений URL/контента.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=75 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Live ALT TITLE Image PRO&lt;/strong&gt; додає відсутні alt і title до зображень на витрині OpenCart за шаблонами, не змушуючи вручну редагувати кожен Twig-файл або кожну картинку.&lt;/p&gt;&lt;p&gt;Alt потрібен не лише для SEO зображень, а й для доступності та зрозумілого опису контенту. Модуль корисний там, де тема або сторонні блоки виводять картинки без заповнених атрибутів.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Автоматичне додавання alt, якщо атрибут відсутній.&lt;/li&gt;&lt;li&gt;Автоматичне додавання title, якщо атрибут відсутній.&lt;/li&gt;&lt;li&gt;Підтримка товарів і категорій.&lt;/li&gt;&lt;li&gt;Робота з банерами, логотипами та HTML-контентом у підтримуваних зонах.&lt;/li&gt;&lt;li&gt;Мультимовні шаблони.&lt;/li&gt;&lt;li&gt;Змінні для назви товару, категорії, магазину та інших доступних даних.&lt;/li&gt;&lt;li&gt;Захист уже заповнених alt/title від перезапису.&lt;/li&gt;&lt;li&gt;Робота на рівні витрини без масового переписування карток товарів.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає закрити типову технічну прогалину в темах і сторонніх блоках, не змінюючи самі файли зображень.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;SEO-фахівцям, магазинам із великою кількістю зображень та власникам тем, де не всі картинки отримують коректні alt/title.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=76 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Live ALT TITLE Image PRO adds missing alt/title attributes to supported storefront images from language-aware templates without mass-rewriting product records.&lt;/p&gt;&lt;p&gt;Alt text helps accessibility and image understanding, but themes and custom blocks often omit it. The module fills missing attributes at storefront output while preserving values that already exist.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;SEO-focused stores with many product/category/banner images or themes where image alt/title output is inconsistent.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=76 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Live ALT TITLE Image PRO добавляет отсутствующие alt/title к поддерживаемым изображениям витрины по мультиязычным шаблонам без массовой перезаписи товаров.&lt;/p&gt;&lt;p&gt;Alt важен для доступности и понимания изображений, но темы и кастомные блоки часто оставляют его пустым. Модуль дополняет отсутствующие атрибуты и не перезаписывает уже заполненные.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;ALT и TITLE для изображений&lt;/li&gt;&lt;li&gt;Языковые шаблоны&lt;/li&gt;&lt;li&gt;Товары, категории и контент&lt;/li&gt;&lt;li&gt;Работа на уровне HTML-вывода&lt;/li&gt;&lt;li&gt;Предпросмотр и диагностика&lt;/li&gt;&lt;li&gt;Без массового изменения изображений в БД&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;SEO-ориентированным магазинам с большим количеством фото и темами, где alt/title выводятся непоследовательно.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=76 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Payment PRO Hub&lt;/strong&gt; об’єднує кілька платіжних сценаріїв у одному модулі та дає адміністратору єдине місце для налаштування доступності, комісій, статусів і діагностики оплат.&lt;/p&gt;&lt;p&gt;Замість набору розрізнених модулів із різними інтерфейсами магазин отримує централізований платіжний шар, який легше підтримувати та перевіряти.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Stripe Checkout.&lt;/li&gt;&lt;li&gt;LiqPay Checkout.&lt;/li&gt;&lt;li&gt;WayForPay із callback і перевіркою статусу.&lt;/li&gt;&lt;li&gt;Monobank / MonoPay invoice.&lt;/li&gt;&lt;li&gt;Portmone.&lt;/li&gt;&lt;li&gt;Fondy Checkout URL і callback validation.&lt;/li&gt;&lt;li&gt;NovaPay internet acquiring з RSA x-sign flow.&lt;/li&gt;&lt;li&gt;Банківський переказ із мультимовною інструкцією.&lt;/li&gt;&lt;li&gt;Оплата при отриманні.&lt;/li&gt;&lt;li&gt;Правила доступності способів оплати.&lt;/li&gt;&lt;li&gt;Глобальні та індивідуальні комісії через окремий order total.&lt;/li&gt;&lt;li&gt;Підтримка AJAX-checkout і динамічно вставлених блоків оплати, що важливо для UniShop2.&lt;/li&gt;&lt;li&gt;Webhook/callback та контроль стану платежу для провайдерів, які це підтримують.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Єдиний інтерфейс спрощує контроль платіжної логіки та зменшує кількість різних точок конфігурації.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які використовують кілька українських і міжнародних способів оплати та хочуть централізувати платіжну інфраструктуру.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=77 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Payment PRO Hub centralizes several payment methods, availability rules, fees, callbacks and diagnostics in one OpenCart payment module.&lt;/p&gt;&lt;p&gt;A store with many separate payment extensions often has inconsistent configuration and callback handling. A unified hub reduces the number of independent integration points while keeping each provider\'s credentials and validation separate.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores using several Ukrainian/international payment methods and wanting centralized payment administration.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=77 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Payment PRO Hub объединяет несколько способов оплаты, правила доступности, комиссии, callback и диагностику в одном платёжном модуле OpenCart.&lt;/p&gt;&lt;p&gt;Набор разрозненных payment-расширений часто создаёт разные настройки и обработку callback. Единый hub уменьшает количество отдельных точек интеграции, сохраняя отдельную проверку каждого провайдера.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Единый центр управления оплатой&lt;/li&gt;&lt;li&gt;Мультиязычные названия и описания&lt;/li&gt;&lt;li&gt;Иконки платёжных систем&lt;/li&gt;&lt;li&gt;Журналы и CSV-экспорт&lt;/li&gt;&lt;li&gt;Диагностика интеграций&lt;/li&gt;&lt;li&gt;Контроль уведомлений и webhook&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с несколькими украинскими и международными способами оплаты, которым нужно единое управление.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=77 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Product Currency Input PRO&lt;/strong&gt; дозволяє вводити вихідну ціну товару у валюті постачальника та автоматично розраховувати стандартну ціну OpenCart у базовій валюті магазину.&lt;/p&gt;&lt;p&gt;Модуль корисний імпортерам і магазинам, які закуповують у EUR, USD, DKK або іншій валюті, але продають у валюті магазину. Важливо, що на витрині використовується звичайний product.price — окремої нестандартної логіки ціни для покупця немає.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Вихідна ціна товару у валюті постачальника.&lt;/li&gt;&lt;li&gt;Вибір будь-якої активної валюти OpenCart.&lt;/li&gt;&lt;li&gt;Автоматичний розрахунок стандартного product.price.&lt;/li&gt;&lt;li&gt;Курс зі стандартної таблиці валют OpenCart.&lt;/li&gt;&lt;li&gt;Ручний курс для окремого товару.&lt;/li&gt;&lt;li&gt;Режим 1:1 для спеціальних сценаріїв.&lt;/li&gt;&lt;li&gt;Відображення застосованого курсу та розрахованої ціни.&lt;/li&gt;&lt;li&gt;Список товарів із валютними даними в адмінці.&lt;/li&gt;&lt;li&gt;Масовий перерахунок вибраних або відфільтрованих товарів.&lt;/li&gt;&lt;li&gt;Cron-перерахунок пакетами, якщо він налаштований.&lt;/li&gt;&lt;li&gt;Журнал і діагностика перерахунків.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Менеджеру не потрібно вручну перераховувати кожну закупівельну ціну при зміні курсу.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Імпортерам, B2B-магазинам і продавцям, які закуповують товари в одній валюті, а продають в іншій.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=78 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Currency Input PRO stores a supplier/source price in another active currency and calculates the standard OpenCart product.price in the store base currency.&lt;/p&gt;&lt;p&gt;The storefront still uses normal OpenCart pricing. The module helps importers and B2B stores avoid manually recalculating supplier prices every time the exchange rate changes.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Importers and stores purchasing in EUR/USD/DKK or another currency while selling in the store\'s base currency.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=78 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Currency Input PRO хранит исходную цену поставщика в другой активной валюте и рассчитывает стандартный product.price в базовой валюте магазина.&lt;/p&gt;&lt;p&gt;На витрине остаётся обычная цена OpenCart. Модуль избавляет импортёров от ручного пересчёта каждой закупочной цены при изменении курса.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Исходная цена в валюте поставщика&lt;/li&gt;&lt;li&gt;Автоматический пересчёт&lt;/li&gt;&lt;li&gt;Штатное поле product.price&lt;/li&gt;&lt;li&gt;Ручной или системный курс&lt;/li&gt;&lt;li&gt;Массовый пересчёт&lt;/li&gt;&lt;li&gt;Cron после обновления курсов&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Импортёрам и магазинам, которые закупают в EUR/USD/DKK или другой валюте, а продают в базовой валюте сайта.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=78 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;SEO Meta PRO&lt;/strong&gt; допомагає швидко заповнювати SEO-поля товарів, категорій і виробників за керованими шаблонами та перевіряти результат до запису в базу.&lt;/p&gt;&lt;p&gt;Модуль потрібен не для «магічного SEO», а для контрольованого закриття порожніх або однотипних метаданих у великому каталозі. Він особливо корисний після імпорту товарів або запуску нового магазину.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Генерація Meta Title.&lt;/li&gt;&lt;li&gt;Генерація Meta Description.&lt;/li&gt;&lt;li&gt;Генерація Meta Keywords там, де поле використовується.&lt;/li&gt;&lt;li&gt;Генерація Meta H1.&lt;/li&gt;&lt;li&gt;Підтримка товарів, категорій і виробників.&lt;/li&gt;&lt;li&gt;Окремі шаблони для активних мов магазину.&lt;/li&gt;&lt;li&gt;Змінні {name}, {model}, {sku}, {manufacturer}, {category}, {store_name}, {price}, {quantity}, {language_code}.&lt;/li&gt;&lt;li&gt;Попередній перегляд перед записом.&lt;/li&gt;&lt;li&gt;Вибір рядків перед застосуванням.&lt;/li&gt;&lt;li&gt;Безпечний режим «тільки порожні».&lt;/li&gt;&lt;li&gt;Окремий overwrite-режим для усвідомленого перезапису.&lt;/li&gt;&lt;li&gt;Safe mode для очищення HTML, зайвих пробілів і контролю довжини.&lt;/li&gt;&lt;li&gt;Журнал операцій.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Перед масовим застосуванням можна побачити, які значення будуть створені, і не перезаписувати вручну оптимізовані сторінки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;SEO-фахівцям і магазинам із великим каталогом, де потрібно швидко привести метадані до єдиного стандарту.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=79 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SEO Meta PRO generates Meta Title, Meta Description, Meta Keywords and H1 for products, categories and manufacturers from language-aware templates with preview and overwrite controls.&lt;/p&gt;&lt;p&gt;The module is intended to fill missing or standardized metadata at scale, not to replace SEO strategy. Preview and \'empty only\' mode protect pages that were already optimized manually.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;SEO specialists and catalogs with many missing or inconsistent metadata fields after import or launch.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=79 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SEO Meta PRO генерирует Meta Title, Meta Description, Meta Keywords и H1 для товаров, категорий и производителей по мультиязычным шаблонам с preview и контролем перезаписи.&lt;/p&gt;&lt;p&gt;Модуль нужен для массового заполнения отсутствующих/типовых метаданных, а не для замены SEO-стратегии. Preview и режим «только пустые» защищают уже оптимизированные страницы.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Meta title, description и H1&lt;/li&gt;&lt;li&gt;Шаблоны с данными товара&lt;/li&gt;&lt;li&gt;Массовая генерация&lt;/li&gt;&lt;li&gt;Предпросмотр&lt;/li&gt;&lt;li&gt;Работа с товарами и категориями&lt;/li&gt;&lt;li&gt;Контроль длины и качества&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;SEO-специалистам и большим каталогам с пустыми или неоднородными метаданными после импорта/запуска.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=79 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;SEO URL PRO&lt;/strong&gt; створює чисті SEO URL для основних сутностей OpenCart, допомагає масово заповнювати keyword і безпечніше змінювати старі адреси завдяки історії та 301-редиректам.&lt;/p&gt;&lt;p&gt;Головна цінність модуля — не лише автоматична транслітерація. Для живого магазину важливо, щоб зміна URL не обривала старі посилання, а масова генерація не перезаписувала адреси без попереднього контролю.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Товари, категорії, виробники та інформаційні сторінки.&lt;/li&gt;&lt;li&gt;Підтримка новин UniShop2 та їх категорій, якщо відповідні таблиці доступні.&lt;/li&gt;&lt;li&gt;Шаблони URL і змінні.&lt;/li&gt;&lt;li&gt;Транслітерація та очищення slug.&lt;/li&gt;&lt;li&gt;Стоп-слова після транслітерації.&lt;/li&gt;&lt;li&gt;Контроль конфліктів і ID-суфікса.&lt;/li&gt;&lt;li&gt;Швидкі кнопки генерації у формах редагування.&lt;/li&gt;&lt;li&gt;Живий preview перед збереженням.&lt;/li&gt;&lt;li&gt;Масова AJAX-генерація пакетами.&lt;/li&gt;&lt;li&gt;Історія старих URL.&lt;/li&gt;&lt;li&gt;301-редирект на нову адресу після контрольованої зміни.&lt;/li&gt;&lt;li&gt;Діагностика seo_url та проблемних адрес.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;У картці товару або категорії модуль не повинен підміняти стандартне збереження: він формує значення, а запис виконується разом із основною формою OpenCart.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;SEO-фахівцям, магазинам після імпорту, міграції або масового створення товарів, а також проектам із регулярною зміною назв.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=80 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SEO URL PRO generates clean slugs for OpenCart entities and keeps URL history/301 redirects so intentional URL changes do not simply break old addresses.&lt;/p&gt;&lt;p&gt;For a live indexed store, mass slug generation must be previewed and old URLs should be preserved through controlled redirects where appropriate. The module therefore combines generation with history and diagnostics.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores after import/migration and SEO teams managing large numbers of product, category, manufacturer and content URLs.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=80 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SEO URL PRO генерирует чистые slug для сущностей OpenCart и хранит историю/301-редиректы, чтобы осознанная смена URL не обрывала старые адреса.&lt;/p&gt;&lt;p&gt;В проиндексированном магазине массовую генерацию нужно проверять через preview, а старые адреса сохранять редиректом там, где это нужно. Поэтому модуль объединяет генерацию, историю и диагностику.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;SEO URL для товаров и категорий&lt;/li&gt;&lt;li&gt;Производители и контент&lt;/li&gt;&lt;li&gt;Массовая генерация&lt;/li&gt;&lt;li&gt;Предпросмотр&lt;/li&gt;&lt;li&gt;История старых URL&lt;/li&gt;&lt;li&gt;301-редиректы&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам после импорта/миграции и SEO-командам, которые управляют большим количеством URL товаров, категорий, брендов и контента.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=80 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Smart Filter PRO SEO&lt;/strong&gt; допомагає покупцю швидше знайти товар у великій категорії за ціною, брендом, наявністю, атрибутами та опціями, а магазину — керувати поведінкою фільтрованих URL для SEO.&lt;/p&gt;&lt;p&gt;Фільтр має вирішувати дві задачі одночасно: бути швидким для користувача й не створювати неконтрольовану кількість індексованих комбінацій параметрів. Модуль поєднує AJAX-відбір із окремою SEO-логікою.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;AJAX-оновлення списку товарів без повного перезавантаження.&lt;/li&gt;&lt;li&gt;Динамічні лічильники значень.&lt;/li&gt;&lt;li&gt;Фільтр за ціною у поточній валюті OpenCart.&lt;/li&gt;&lt;li&gt;Фільтр за виробником.&lt;/li&gt;&lt;li&gt;Фільтр за наявністю.&lt;/li&gt;&lt;li&gt;Фільтр за атрибутами.&lt;/li&gt;&lt;li&gt;Фільтр за опціями.&lt;/li&gt;&lt;li&gt;Checkbox, radio, select, dropdown і swatch.&lt;/li&gt;&lt;li&gt;Мобільна виїзна панель.&lt;/li&gt;&lt;li&gt;Split-режим: частина груп зверху, частина у боковій колонці.&lt;/li&gt;&lt;li&gt;Керування canonical/noindex для технічних комбінацій.&lt;/li&gt;&lt;li&gt;SEO-посадкові сторінки для вибраних корисних комбінацій.&lt;/li&gt;&lt;li&gt;Індекс/службова оптимізація для прискорення фільтрації великого каталогу.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Для покупця фільтр скорочує шлях від категорії до потрібного товару. Для SEO важливо не індексувати мільйони випадкових комбінацій, а виділяти лише ті сторінки, які мають реальний пошуковий попит.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Великим каталогам техніки, запчастин, обладнання, електроніки та іншим магазинам, де покупець вибирає товар за параметрами.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=81 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Smart Filter PRO SEO provides fast AJAX filtering by price, manufacturer, stock, attributes and options while separately controlling the SEO behavior of filtered URLs.&lt;/p&gt;&lt;p&gt;A useful catalog filter must solve two problems: help the buyer narrow the assortment quickly and avoid creating an uncontrolled number of indexable parameter combinations. The module combines storefront filtering with canonical/noindex and selected SEO landing-page logic.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Large technical catalogs where customers choose products by measurable characteristics and SEO teams need control over filter URLs.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=81 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Smart Filter PRO SEO фильтрует товары по цене, бренду, наличию, атрибутам и опциям через AJAX и отдельно управляет SEO-поведением фильтрованных URL.&lt;/p&gt;&lt;p&gt;Хороший фильтр решает две задачи: помогает покупателю быстро сузить ассортимент и не создаёт миллионы индексируемых комбинаций. Модуль объединяет витринную фильтрацию с canonical/noindex и выбранными SEO-посадочными.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;AJAX-фильтрация без перезагрузки&lt;/li&gt;&lt;li&gt;Цена, бренд и наличие&lt;/li&gt;&lt;li&gt;Атрибуты и опции&lt;/li&gt;&lt;li&gt;Счётчики значений&lt;/li&gt;&lt;li&gt;Мобильная панель&lt;/li&gt;&lt;li&gt;SEO landing, canonical и noindex&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Большим техническим каталогам, где товар выбирают по параметрам, а SEO-команде нужен контроль URL фильтра.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=81 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Telegram Notify PRO&lt;/strong&gt; надсилає інформацію про нові замовлення та зміни статусу в Telegram, щоб менеджеру не потрібно було постійно перевіряти адмінку або чекати email.&lt;/p&gt;&lt;p&gt;Модуль особливо корисний там, де швидкість реакції впливає на продаж: швидкі замовлення, консультації, заявки у неробочий час або кілька менеджерів в одному Telegram-чаті.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Повідомлення про нові стандартні замовлення OpenCart/ocStore.&lt;/li&gt;&lt;li&gt;Підтримка швидких замовлень UniShop2 через окремий source marker.&lt;/li&gt;&lt;li&gt;Повідомлення про зміну статусу замовлення.&lt;/li&gt;&lt;li&gt;Кілька чатів, груп або каналів.&lt;/li&gt;&lt;li&gt;Формат chat_id або chat_id|topic_id.&lt;/li&gt;&lt;li&gt;Telegram Forum topics / message_thread_id.&lt;/li&gt;&lt;li&gt;Окремі шаблони для звичайного, швидкого замовлення та зміни статусу.&lt;/li&gt;&lt;li&gt;Шаблони UA / RU / EN.&lt;/li&gt;&lt;li&gt;Telegram HTML-розмітка: bold, italic, code, pre, blockquote, spoiler та посилання.&lt;/li&gt;&lt;li&gt;Live preview шаблону в адмінці.&lt;/li&gt;&lt;li&gt;Посилання на товари і можливість додавати товарні зображення.&lt;/li&gt;&lt;li&gt;Контроль доставки й адреси у повідомленні.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Менеджер отримує замовлення у звичному месенджері практично одразу після події і може швидше зв’язатися з клієнтом.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із активними менеджерами, швидкими замовленнями, декількома відповідальними особами або потребою отримувати події поза адмінкою.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=82 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Telegram Notify PRO sends new-order, quick-order and status-change notifications to configured Telegram chats/topics using multilingual templates.&lt;/p&gt;&lt;p&gt;Managers can receive operational store events in the messenger they already monitor instead of continuously refreshing the OpenCart admin panel. Templates determine exactly which order data is sent.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that need fast manager notifications, UniShop2 quick-order alerts or multiple Telegram recipients/topics.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=82 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Telegram Notify PRO отправляет новые заказы, быстрые заявки и изменения статуса в настроенные Telegram-чаты/топики по мультиязычным шаблонам.&lt;/p&gt;&lt;p&gt;Менеджер получает рабочие события в привычном мессенджере вместо постоянного обновления админки. Шаблон определяет, какие данные заказа реально отправляются.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Новые заказы в Telegram&lt;/li&gt;&lt;li&gt;Данные клиента и товаров&lt;/li&gt;&lt;li&gt;Гибкие шаблоны сообщений&lt;/li&gt;&lt;li&gt;Несколько получателей&lt;/li&gt;&lt;li&gt;Тестовая отправка&lt;/li&gt;&lt;li&gt;Журнал и диагностика&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которым нужны быстрые уведомления менеджеров, UniShop2 Quick Order и несколько Telegram-получателей/топиков.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=82 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Uni Dark Theme PRO&lt;/strong&gt; додає до UniShop2 керований dark mode із режимами Light, Dark і System, зберігає вибір користувача та адаптує ключові блоки теми до темної палітри.&lt;/p&gt;&lt;p&gt;Це не просто інверсія кольорів. Для нормальної темної теми потрібно окремо опрацювати картки, меню, модальні вікна, checkout, quick order, корзину, fly-блоки та інші елементи UniShop2.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Режими Light, Dark і System.&lt;/li&gt;&lt;li&gt;Підтримка prefers-color-scheme у режимі System.&lt;/li&gt;&lt;li&gt;Збереження вибору в localStorage і cookie.&lt;/li&gt;&lt;li&gt;Lazy-load dark CSS: у світлому режимі основний dark CSS не завантажується в head.&lt;/li&gt;&lt;li&gt;JS із defer без блокування першого рендеру.&lt;/li&gt;&lt;li&gt;Налаштування фону, тексту, карток, кнопок, корзини та акцентів.&lt;/li&gt;&lt;li&gt;HEX-поля й color picker в адмінці.&lt;/li&gt;&lt;li&gt;Additional CSS для точкової адаптації.&lt;/li&gt;&lt;li&gt;Перемикач теми для desktop/mobile.&lt;/li&gt;&lt;li&gt;Адаптація UniShop2: checkout, quick order, modal cart, fly-block, fly-menu, товарні картки та опції.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Користувач може вибрати комфортний режим або довірити вибір системній темі пристрою.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам на UniShop2, які хочуть сучасний темний режим із контрольованою палітрою та без повної переробки шаблону.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;li&gt;UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=83 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Uni Dark Theme PRO adds Light, Dark and System modes to UniShop2 with saved user preference, configurable colors and dedicated adaptation of key storefront blocks.&lt;/p&gt;&lt;p&gt;A real dark theme is more than color inversion: cards, menus, modals, checkout, quick order, fly blocks and options require explicit styling. Dark assets are loaded only when needed rather than burdening every light-mode page.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;UniShop2 stores that want a modern dark mode without maintaining a separate theme fork.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;li&gt;UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=83 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Uni Dark Theme PRO добавляет в UniShop2 режимы Light, Dark и System с сохранением выбора пользователя, настройкой цветов и адаптацией ключевых блоков витрины.&lt;/p&gt;&lt;p&gt;Полноценная тёмная тема — не простая инверсия: карточки, меню, модальные окна, checkout, quick order, fly-блоки и опции требуют отдельной стилизации. Dark assets подключаются только когда нужны.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Тёмный режим для UniShop2&lt;/li&gt;&lt;li&gt;Переключатель light/dark/system&lt;/li&gt;&lt;li&gt;Lazy-загрузка dark CSS&lt;/li&gt;&lt;li&gt;Сохранение выбора пользователя&lt;/li&gt;&lt;li&gt;Изолированный CSS без глобальных конфликтов&lt;/li&gt;&lt;li&gt;Адаптация основных страниц магазина&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам на UniShop2, которым нужен современный dark mode без отдельного форка темы.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;li&gt;UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=83 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Language Inspector PRO&lt;/strong&gt; додає для авторизованого адміністратора візуальний інспектор текстів прямо на витрині. Редагувати можна тільки той текст, походження якого модуль знає точно до формування HTML.&lt;/p&gt;&lt;p&gt;На відміну від небезпечного пошуку «такого самого тексту» по базі, модуль працює з точним provenance: language code, route, key і файл для мовних рядків або entity_id + language_id + дозволене поле для товарів і категорій. Якщо джерело не можна довести однозначно, редагування не пропонується.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Візуальний режим для адміністратора на витрині.&lt;/li&gt;&lt;li&gt;Точне визначення мовного файла, route і language key.&lt;/li&gt;&lt;li&gt;Редагування дозволених полів товару та категорії за конкретним ID і language_id.&lt;/li&gt;&lt;li&gt;Жодного LIKE-пошуку, nearest-match або вгадування сутності за видимим текстом.&lt;/li&gt;&lt;li&gt;Кожне редаговане джерело має серверно підписаний proof.&lt;/li&gt;&lt;li&gt;Proof містить hash вихідного значення: якщо дані змінилися після відкриття сторінки, конфлікт не перезаписується мовчки.&lt;/li&gt;&lt;li&gt;Адміністративне редагування не відкривається звичайним відвідувачам.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль особливо зручний для пошуку дрібних помилок перекладу: адміністратор бачить фразу саме там, де вона виводиться, і не шукає вручну серед десятків language-файлів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Мультимовним магазинам, адміністраторам і розробникам, які часто виправляють локалізацію, назви та короткі тексти без довгого пошуку по файлах і БД.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=85 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Language Inspector PRO lets an authorized administrator edit storefront translations from the storefront while preserving exact provenance of the text source.&lt;/p&gt;&lt;p&gt;The module deliberately avoids blind database search by visible text. Editing is enabled only when the controller can identify the exact language source, so the same phrase appearing in several places is not silently changed in the wrong record.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Version 1.3.0 intentionally prefers safety over coverage. Product/category text is editable only where the controller has attached exact provenance metadata. Product cards, menu category names, third-party modules, custom Twig loops and theme-specific content are not made editable merely because their visible text matches a database value. Support for such locations should be added only with a dedicated exact provenance hook.&lt;/li&gt;&lt;li&gt;After enabling the module, the pencil is shown only to an authorized administrator. The inspector edits only sources whose provenance is known exactly; it never searches the database by visible text.&lt;/li&gt;&lt;li&gt;Language Inspector PRO is a storefront visual source inspector and editor for OpenCart/ocStore administrators. It edits only data whose origin is known exactly before the HTML reaches the browser. It never searches the database for matching visible text and never guesses an entity by text comparison.&lt;/li&gt;&lt;li&gt;Create a full backup of the website files and database before installation or update. The module creates its own language-file backups before each language edit, but this does not replace a complete site backup.&lt;/li&gt;&lt;li&gt;Product and category fields are editable only when the page controller provides an exact entity ID, language ID and field name. If exact provenance is unavailable, the text remains read-only.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Developers and multilingual store administrators who frequently correct language strings, product/category text and other supported content.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=85 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Language Inspector PRO позволяет авторизованному администратору исправлять переводы с витрины, сохраняя точное происхождение каждой редактируемой строки.&lt;/p&gt;&lt;p&gt;Модуль принципиально не ищет запись в базе по видимому тексту. Редактирование доступно только когда контроллер знает точный источник, поэтому одинаковая фраза в нескольких местах не изменяется случайно.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;После включения модуль показывает карандаш только авторизованному администратору. Редактируются только источники, происхождение которых определено точно; поиск по видимому тексту в базе данных не используется.&lt;/li&gt;&lt;li&gt;Самостоятельный визуальный редактор OpenCart/ocStore со строгим отслеживанием источника. Языковые строки отслеживаются от Language Loader до DOM. Данные товаров и категорий изменяются только по точным entity_id + language_id + field, без поиска по тексту.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Разработчикам и администраторам мультиязычных магазинов, которым часто нужно быстро исправлять языковые строки и поддерживаемый контент.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=85 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Multi Store CRM Connector PRO&lt;/strong&gt; надає центральній Multi-Store CRM захищений API тільки для читання клієнтів, їх основної компанії/міста/країни та замовлень із OpenCart/ocStore.&lt;/p&gt;&lt;p&gt;Коннектор принципово не змінює замовлення, клієнтів, статуси, залишки або інші бізнес-дані магазину. Синхронізація спрямована тільки з сайту в CRM, що дозволяє збирати дані кількох магазинів у одному Windows-застосунку без ризику зворотного запису на сайти.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Строго read-only runtime API: робочі операції виконують SELECT.&lt;/li&gt;&lt;li&gt;HMAC-SHA256 підпис запитів із секретним токеном.&lt;/li&gt;&lt;li&gt;Клієнти синхронізуються курсором customer_id.&lt;/li&gt;&lt;li&gt;Замовлення — складеним курсором date_modified + order_id без OFFSET.&lt;/li&gt;&lt;li&gt;Diagnostics endpoint передає версії платформи/PHP/БД, обов’язкові таблиці, counts і watermarks.&lt;/li&gt;&lt;li&gt;CRM перед синхронізацією може перевірити read_only=true, capabilities і наявність потрібних таблиць.&lt;/li&gt;&lt;li&gt;Збережена сумісність зі старим page/modified_since API для поетапного оновлення CRM і Connector.&lt;/li&gt;&lt;li&gt;Модуль після встановлення залишається OFF до налаштування токена й CRM.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Cursor-синхронізація краще підходить для великих таблиць, ніж постійне пагінування OFFSET, і дозволяє продовжувати читання з відомої точки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Компаніям із кількома магазинами OpenCart/ocStore, які хочуть бачити клієнтів і замовлення в єдиній CRM для Windows 11.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;Multi-Store CRM&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=86 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Multi Store CRM Connector PRO provides a read-only API layer that lets a Windows CRM import customers, orders and store-source information from several OpenCart/ocStore stores.&lt;/p&gt;&lt;p&gt;The connector is intentionally one-way: CRM can read and synchronize data, but it does not receive endpoints that modify orders, customers, statuses or other business data on the store.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The connector only reads customers and orders. It has no endpoints that modify store business data.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Businesses consolidating several OpenCart/ocStore stores into one desktop CRM while keeping the websites authoritative and read-only from CRM.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=86 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Multi Store CRM Connector PRO создаёт read-only API-слой, через который Windows CRM импортирует клиентов, заказы и источник данных из нескольких OpenCart/ocStore магазинов.&lt;/p&gt;&lt;p&gt;Синхронизация намеренно односторонняя: CRM читает данные, но не получает endpoints для изменения заказов, клиентов, статусов и других бизнес-данных на сайтах.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Запросы CRM подписываются HMAC-SHA256. Runtime API коннектора содержит только операции чтения SELECT. Перед синхронизацией CRM проверяет read_only=true, capabilities и обязательные таблицы. CRM не имеет endpoint для изменения заказов, клиентов или статусов магазина.&lt;/li&gt;&lt;li&gt;Удалите модуль стандартными средствами OpenCart/ocStore. Удаление коннектора не удаляет заказы или клиентов магазина.&lt;/li&gt;&lt;li&gt;4. После установки модуль остается выключенным. Проверьте/сгенерируйте секретный токен и включите модуль вручную только после настройки CRM.&lt;/li&gt;&lt;li&gt;Коннектор только читает клиентов и заказы. В нем нет методов изменения рабочих данных магазина.&lt;/li&gt;&lt;li&gt;3. Откройте Расширения -&gt; Расширения -&gt; Модули -&gt; Multi-Store CRM Connector PRO.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Компаниям с несколькими OpenCart/ocStore магазинами, которым нужна единая desktop CRM без обратной записи в сайты.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=86 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Smart Search PRO&lt;/strong&gt; посилює стандартний пошук OpenCart, але не замінює тему, картки товарів, ціни, сортування або пагінацію. Модуль визначає релевантні product_id, після чого штатна модель OpenCart продовжує застосовувати категорії, бренди, статус, store, ціни, акції та інші стандартні умови.&lt;/p&gt;&lt;p&gt;Це важливо для технічних каталогів, де покупець шукає не тільки назву, а модель, SKU, EAN, MPN, розмір, напругу або артикул. Пошук захищає технічні токени на кшталт FTH-062, 12 V, 25 mm і 3/4 inch від неправильного «виправлення».&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Пошук по індексу з налаштовуваними вагами релевантності.&lt;/li&gt;&lt;li&gt;Cross-language RU/UA/EN: пошук може знайти запис іншою мовою, але результат показується поточною мовою витрини.&lt;/li&gt;&lt;li&gt;Підвищений пріоритет точного model, SKU, EAN, UPC, JAN, ISBN і MPN.&lt;/li&gt;&lt;li&gt;Захист технічних токенів.&lt;/li&gt;&lt;li&gt;Альтернатива розкладки клавіатури та fallback транслітерації.&lt;/li&gt;&lt;li&gt;Словник синонімів в адмінці.&lt;/li&gt;&lt;li&gt;Локальна підказка друкарської помилки тільки після нульового результату й не для технічних запитів.&lt;/li&gt;&lt;li&gt;Легка autocomplete для стандартного пошуку; для UniShop2/UniStore другий dropdown не створюється.&lt;/li&gt;&lt;li&gt;Аналітика запитів і звіт нульових результатів без зберігання IP.&lt;/li&gt;&lt;li&gt;Опціональне click tracking результатів.&lt;/li&gt;&lt;li&gt;Пакетна перебудова індексу й точковий reindex при зміні товару.&lt;/li&gt;&lt;li&gt;Зміна категорії/виробника позначає індекс dirty; cron може перебудувати його пакетами, а до готовності використовується штатний fallback пошуку.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль робить пошук кориснішим для каталогу з моделями, кодами й синонімами без створення окремої альтернативної сторінки результатів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам техніки, запчастин, обладнання, агротоварів та іншим каталогам, де точний артикул і технічні характеристики важливі не менше назви товару.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=87 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Smart Search PRO replaces slow broad catalog matching with an indexed product-search layer that understands exact identifiers, words, transliteration, synonyms and technical queries.&lt;/p&gt;&lt;p&gt;The module is designed for real catalog searches such as models, SKU/EAN/MPN, voltage or dimensions, where a generic LIKE search often returns weak results or misses the product entirely.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;UniShop2: compatible when live search uses ModelCatalogProduct::getProducts(), without a second dropdown. Proprietary non-standard filter keys are not claimed as automatically compatible.&lt;/li&gt;&lt;li&gt;Optional Cron automatically rebuilds a dirty index in batches; while rebuilding, native OpenCart search remains the safe fallback.&lt;/li&gt;&lt;li&gt;Security note: saved cron secrets are not embedded into the rendered admin HTML. Use the copy buttons in the Cron tab; the full command is returned only by an authenticated admin request.&lt;/li&gt;&lt;li&gt;5. Configure while OFF. Then enable and save the module, rebuild the index, and test. Until a complete index exists, storefront search safely falls back to the native OpenCart search.&lt;/li&gt;&lt;li&gt;6. Copy the protected Cron command from the Cron / Automation tab and schedule it every 5 minutes or less often if you want automatic maintenance after category/manufacturer changes.&lt;/li&gt;&lt;li&gt;Lightweight autocomplete for the standard OpenCart search; automatically skipped when config_theme identifies UniShop2/UniStore so their own live-search remains the only dropdown.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores with medium or large catalogs where customers search by model, brand, identifier, technical characteristics or imperfect spelling.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=87 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Smart Search PRO добавляет индексированный поиск товаров, который учитывает точные идентификаторы, слова, транслитерацию, синонимы и технические запросы.&lt;/p&gt;&lt;p&gt;Он рассчитан на реальные запросы по model, SKU/EAN/MPN, напряжению, размерам и характеристикам, где обычный широкий LIKE-поиск часто даёт слабую выдачу или не находит товар.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам со средним и большим каталогом, где покупатели ищут по моделям, брендам, кодам и техническим параметрам.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=87 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Quick Price Edit PRO&lt;/strong&gt; дозволяє змінити стандартне поле product.price безпосередньо в Каталог → Товари — через іконку олівця або подвійний клік по ціні.&lt;/p&gt;&lt;p&gt;Модуль навмисно робить тільки одну задачу й не змішує її з акціями, знижками, опціями або закупівельними цінами. Це робить сценарій простим і передбачуваним.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Редагування product.price прямо у списку товарів.&lt;/li&gt;&lt;li&gt;Enter зберігає значення, Esc скасовує редагування.&lt;/li&gt;&lt;li&gt;Не змінює specials, discounts, option prices і purchase prices.&lt;/li&gt;&lt;li&gt;AJAX приймає POST, перевіряє user_token та права catalog/product access/modify.&lt;/li&gt;&lt;li&gt;product_id приводиться до int, ціна нормалізується перед записом.&lt;/li&gt;&lt;li&gt;CSS/JS завантажуються тільки коли модуль увімкнений.&lt;/li&gt;&lt;li&gt;У стані OFF робочий AJAX і assets не працюють.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Підходить для щоденних невеликих правок, коли відкривати повну картку товару заради одного поля занадто довго.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Менеджерам каталогу та магазинам, де часто коригується базова ціна окремих товарів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=88 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Quick Price Edit PRO lets an administrator change the standard product.price directly in the OpenCart product list without opening every product card.&lt;/p&gt;&lt;p&gt;The module is intentionally narrow: it edits the regular base price only and does not silently change specials, discounts or option prices.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Edit the standard product price directly in Catalog &gt; Products. Special prices, discounts and option prices are not modified.&lt;/li&gt;&lt;li&gt;AJAX accepts POST only, validates user_token with hash_equals(), checks catalog/product access/modify permissions, validates product_id and price, casts IDs to int and escapes the normalized price.&lt;/li&gt;&lt;li&gt;Quick editing of the standard product.price value directly in Catalog &gt; Products.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores where managers frequently adjust base prices and need a faster but controlled catalog-list workflow.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=88 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Quick Price Edit PRO позволяет менять стандартное поле product.price прямо в списке товаров OpenCart без открытия каждой карточки.&lt;/p&gt;&lt;p&gt;Модуль специально узкий по назначению: он изменяет только обычную базовую цену и не трогает скрытно акции, скидки или цены опций.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Быстрое редактирование стандартной цены товара непосредственно в Каталог &gt; Товары. Акции, скидки и цены опций не изменяются.&lt;/li&gt;&lt;li&gt;При выключенном модуле Quick Price Edit не обрабатывает AJAX, а его CSS/JavaScript не подключаются в Каталог &gt; Товары.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, где менеджеры часто корректируют базовые цены и хотят делать это быстрее из списка товаров.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=88 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Phone Verification PRO&lt;/strong&gt; підтверджує, що клієнт контролює вказаний номер телефону, за допомогою одноразового коду OTP перед вибраними діями магазину.&lt;/p&gt;&lt;p&gt;Генерація OTP, rate limit і довіра до підтвердженого номера відокремлені від конкретного сервісу доставки. Провайдери можна розташувати за префіксами телефонів і використовувати fallback, якщо перший канал недоступний.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;E.164 нормалізація телефону та опціональний код країни за замовчуванням.&lt;/li&gt;&lt;li&gt;OTP 4–8 цифр, стандартно 6; код зберігається тільки як password_hash.&lt;/li&gt;&lt;li&gt;Phone/IP/session у verification-таблицях зберігаються як HMAC hashes; читабельним лишається тільки маскований номер.&lt;/li&gt;&lt;li&gt;Cooldown повторного надсилання, ліміт спроб, hourly abuse limit і добовий safety cap.&lt;/li&gt;&lt;li&gt;Довіра зареєстрованого клієнта та session-bound trust для гостя.&lt;/li&gt;&lt;li&gt;Telegram Gateway, Twilio Verify, SMSClub, AlphaSMS, SMS.RU, SMSC.RU, SMS Aero, UniSender, Infobip, Vonage, Mobizon, Telnyx, Sinch та інші реалізовані адаптери.&lt;/li&gt;&lt;li&gt;TurboSMS і SMS-Fly доступні як HTTPS presets; є Generic HTTPS SMS/Viber сценарії.&lt;/li&gt;&lt;li&gt;Preset endpoints — тільки HTTPS/POST із блокуванням localhost/private/reserved IP і redirect.&lt;/li&gt;&lt;li&gt;Підтримка стандартного checkout/registration і динамічних телефонних полів UniShop2/AJAX checkout.&lt;/li&gt;&lt;li&gt;У стані OFF Events, assets і provider calls відсутні; cron потрібен лише опціонально для очищення старих verification rows.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Підтвердження номера зменшує кількість фейкових контактів і помилок у телефоні до моменту, коли менеджер починає обробляти замовлення.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із реєстрацією, гостьовим checkout або дорогим ручним опрацюванням замовлень, де достовірність номера критична.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=89 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Phone Verification PRO confirms a customer phone number with a one-time code and can protect selected registration, account or checkout scenarios from invalid or automated phone submissions.&lt;/p&gt;&lt;p&gt;Verification is useful when the phone number is operationally important for delivery or manager contact. Rate limits, code lifetime and provider handling are part of the security model so an OTP endpoint cannot become an uncontrolled SMS sender.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;OTP verification of customer phone numbers in selected store workflows.&lt;/li&gt;&lt;li&gt;Configurable code lifetime, resend delay and attempt/rate limits.&lt;/li&gt;&lt;li&gt;Provider integration with controlled error handling instead of exposing provider failures to the customer.&lt;/li&gt;&lt;li&gt;Server-side verification state linked to the customer/session workflow.&lt;/li&gt;&lt;li&gt;Useful for registration, account or checkout scenarios where a valid phone is operationally required.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that rely on valid phone contacts for checkout, delivery or customer accounts and need configurable OTP verification.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=89 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Phone Verification PRO подтверждает номер телефона одноразовым кодом и может защищать выбранные сценарии регистрации, аккаунта или checkout от неверных и автоматизированных номеров.&lt;/p&gt;&lt;p&gt;Проверка полезна там, где телефон реально нужен для доставки или связи менеджера. Rate limit, срок действия кода и работа провайдера ограничивают злоупотребление OTP-отправкой.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;OTP-подтверждение номера телефона в выбранных сценариях магазина.&lt;/li&gt;&lt;li&gt;Настраиваемый срок кода, задержка повторной отправки и лимиты попыток/rate limit.&lt;/li&gt;&lt;li&gt;Интеграция SMS-провайдера с контролируемой обработкой ошибок.&lt;/li&gt;&lt;li&gt;Серверное состояние подтверждения, привязанное к пользовательскому сценарию.&lt;/li&gt;&lt;li&gt;Подходит для регистрации, аккаунта и checkout, где валидный телефон реально нужен для работы магазина.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которым нужен подтверждённый телефон клиента для checkout, доставки или личного кабинета.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=89 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Google Product Category Field PRO&lt;/strong&gt; додає до категорії OpenCart числове поле Google Product Category ID для використання у Merchant Center і товарних фідах.&lt;/p&gt;&lt;p&gt;Це окрема сутність і вона не має відношення до головної категорії товару або SEO metadata. Спочатку фід визначає категорію товару, а вже потім читає Google Product Category ID з неї, з можливістю успадкування від батьківської категорії.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Числове поле google_product_category_id у категорії.&lt;/li&gt;&lt;li&gt;Значення зберігається окремо від main_category/main_category_id.&lt;/li&gt;&lt;li&gt;Підтримка успадкування Google Category від батьківської категорії, якщо поле порожнє.&lt;/li&gt;&lt;li&gt;OFF вимикає інтеграцію форми та збереження, але вже записані значення не видаляються.&lt;/li&gt;&lt;li&gt;Uninstall зберігає колонку й дані, щоб випадково не втратити розмітку каталогу.&lt;/li&gt;&lt;li&gt;Першочергове визначення головної категорії фіда залишається незалежним: product_to_category.main_category → product.main_category_id → fallback.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль дає просте місце для зберігання офіційного ID таксономії Google без змішування його з внутрішніми категоріями магазину.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які працюють із Google Merchant Center і хочуть заповнювати Google Product Category на рівні власних категорій.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=90 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Google Product Category Field PRO adds a dedicated numeric Google Product Category ID field to OpenCart categories for feeds and Merchant integrations.&lt;/p&gt;&lt;p&gt;Google Product Category ID is not the store\'s main category, not an SEO field and not the internal category ID. Keeping it as a separate category attribute avoids mixing unrelated concepts.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Adds a numeric Google Product Category ID to OpenCart categories for Merchant Center feeds. It is not a main-category field and is not SEO metadata.&lt;/li&gt;&lt;li&gt;Feed main category precedence remains separate: product_to_category.main_category, then product.main_category_id, then fallback assigned category. Google Product Category ID is read only after the feed has selected the product category, with inheritance through category parents when empty.&lt;/li&gt;&lt;li&gt;Database field is missing. Reinstall the module or create it during a maintenance window.&lt;/li&gt;&lt;li&gt;2. Install Google Product Category Field PRO in Extensions &gt; Modules. Installation creates category.google_product_category_id once, using ALGORITHM=INPLACE, LOCK=NONE and never falls back to blocking COPY.&lt;/li&gt;&lt;li&gt;OFF means the module does not add or save the field in the category editor. Existing values remain stored for safe re-enabling.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores using Google Merchant feeds that want category-level Google taxonomy mapping available to feed modules.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=90 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Google Product Category Field PRO добавляет отдельное числовое поле Google Product Category ID в категории OpenCart для фидов и Merchant-интеграций.&lt;/p&gt;&lt;p&gt;Google Product Category ID — не главная категория товара, не SEO-поле и не внутренний category_id. Отдельное поле не позволяет смешивать разные сущности.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;После включения поле появляется в Каталог &gt; Категории &gt; Данные. Сохраняйте только числовой ID таксономии Google. Наследование от родителя выполняет товарный фид.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с Google Merchant-фидами, которым нужно хранить соответствие категорий таксономии Google.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=90 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;AI Ready PRO&lt;/strong&gt; готує магазин до роботи з AI-агентами й LLM: створює спеціальні AI-файли, індекс каталогу та інструменти WebMCP для пошуку й отримання реальних товарних даних.&lt;/p&gt;&lt;p&gt;Мета — щоб AI не вгадував структуру магазину за випадковими HTML-сторінками, а міг отримати контрольований опис сайту, каталог, актуальні ціни/залишки та безпечні інструменти взаємодії.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;llms.txt і llms-full.txt для машинного опису сайту.&lt;/li&gt;&lt;li&gt;AI Sitemap та службові AI/MCP metadata файли.&lt;/li&gt;&lt;li&gt;WebMCP Search Products і Get Product для структурованого пошуку по каталогу.&lt;/li&gt;&lt;li&gt;Підтримка актуальної ціни й залишку у відповідях, якщо live-режими ввімкнені.&lt;/li&gt;&lt;li&gt;Захищені cart actions: POST JSON, same-origin перевірки, session-bound action token і короткоживучий grant, прив’язаний до конкретного product_id.&lt;/li&gt;&lt;li&gt;Add To Cart має серверну ідемпотентність: повтор того самого дозволеного запиту не додає товар удруге.&lt;/li&gt;&lt;li&gt;Update Cart Item задає абсолютну кількість; повторне видалення безпечно відтворюється протягом короткого вікна.&lt;/li&gt;&lt;li&gt;AI-index може позначатися dirty після масових змін і перебудовуватися контрольовано.&lt;/li&gt;&lt;li&gt;Product Feed, IndexNow і UCP-функції зберігаються як окремі інструменти модуля.&lt;/li&gt;&lt;li&gt;Модуль не передає секретні ключі у відкриті AI-файли.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;AI Ready PRO потрібен не «для красивого бейджа AI», а для структурованої взаємодії агентів із реальним каталогом.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які готуються до AI-пошуку, WebMCP/агентних сценаріїв, ChatGPT/Gemini/Claude-подібних інструментів і машинного читання каталогу.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=91 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Ready PRO prepares an OpenCart catalog for machine-readable AI discovery through llms files, AI sitemap data, MCP/WebMCP tools and a structured product index.&lt;/p&gt;&lt;p&gt;The module is not tied to one chatbot. Its purpose is to let compatible AI agents search and retrieve real catalog products with current links, prices and availability while keeping heavy index regeneration in controlled background workflows.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;After bulk product, SEO URL, translation, article or supplier import updates, other modules should mark the AI index outdated through helper system/library/codecart_ai_ready_integration.php. It does not run heavy generation immediately; it only sets a dirty flag for cron.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that want their catalog to be understandable to AI agents and future search/discovery interfaces without exposing unsafe write access by default.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=91 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Ready PRO подготавливает каталог OpenCart к машинному чтению через llms-файлы, AI sitemap, MCP/WebMCP инструменты и структурированный индекс товаров.&lt;/p&gt;&lt;p&gt;Модуль не привязан к одному чат-боту. Его задача — дать совместимому AI-агенту искать реальные товары с актуальными ссылками, ценами и наличием, а тяжёлую перестройку индекса выполнять контролируемо.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;После реального вызова search_products или get_product показывает на витрине общую human + AI панель с теми же товарами, которые получил агент: реальные изображения, актуальная цена, наличие, locale и источник OpenCart. Панель появляется только после WebMCP-вызова, не изменяет каталог и ничего не добавляет в корзину. Включено по умолчанию при активном WebMCP.&lt;/li&gt;&lt;li&gt;Добавлен быстрый live fallback внутри того же Search Products: если постоянный индекс не содержит достаточно сильных кандидатов, модуль добирает их напрямую по живым названиям/категориям/моделям с теми же фильтрами цены и наличия. Это устраняет необходимость переходить в обычный браузерный поиск для перепроверки каталога.&lt;/li&gt;&lt;li&gt;AI Ready PRO подготавливает магазин OpenCart/ocStore к современному поиску, AI discovery, безопасным read-only AI-сценариям и опциональному WebMCP-действию с корзиной. Модуль генерирует LLMS-файлы, масштабируемый AI Sitemap, MCP/WebMCP endpoints, OpenAI-compatible Product Feed, поддерживает IndexNow и опциональный Google UCP Cart transfer.&lt;/li&gt;&lt;li&gt;После массовых правок товаров, SEO URL, переводов, статей или импортов другие модули должны пометить AI индекс устаревшим через helper system/library/codecart_ai_ready_integration.php. Это не запускает тяжёлую генерацию сразу, а только ставит dirty-флаг для cron.&lt;/li&gt;&lt;li&gt;Реальные WebMCP-вызовы search_products/get_product могут сразу показывать найденные товары в открытой витрине: изображение, название, модель, цена, наличие и ссылка. Дополнительный WebMCP tool-вызов для отрисовки не нужен.&lt;/li&gt;&lt;li&gt;Добавлен AI Catalog Search Engine. Он строит серверную taxonomy товаров, Product Type Resolver, Facet Schema, нормализованные факты и постоянный обратный индекс каталога.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которые хотят сделать каталог понятным для AI-агентов и новых поисковых интерфейсов без небезопасной записи в сайт по умолчанию.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=91 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;OpenCart Theme PRO&lt;/strong&gt; — самостійна тема-вітрина й набір інтегрованих інструментів для OpenCart/ocStore 3.x. Вона формує сучасні картки товарів, галерею, каруселі, блог, розширені відгуки, швидкі заявки, SEO-розмітку й оптимізований checkout.&lt;/p&gt;&lt;p&gt;Це не доповнення до UniShop2: одночасно активними дві теми бути не можуть. Коли тема вимкнена або вибрана інша storefront theme, її витринна логіка не повинна виконуватися.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Сучасна адаптивна витрина й товарні картки.&lt;/li&gt;&lt;li&gt;Галерея товару з коректним збереженням реального aspect ratio без штучного білого полотна.&lt;/li&gt;&lt;li&gt;Перемикання додаткових зображень, prev/next і синхронізація AVIF/WebP/JPEG XL source із fallback на оригінал.&lt;/li&gt;&lt;li&gt;Товарні каруселі.&lt;/li&gt;&lt;li&gt;Власний блог і розширені відгуки.&lt;/li&gt;&lt;li&gt;Швидкі заявки та інтегрований checkout.&lt;/li&gt;&lt;li&gt;SEO URL, sitemap і Schema.org інструменти.&lt;/li&gt;&lt;li&gt;Діагностика й адмін-налаштування теми.&lt;/li&gt;&lt;li&gt;Інформаційний режим каталогу: можна приховати ціни, кількість, cart і checkout, залишивши контент та рекомендації.&lt;/li&gt;&lt;li&gt;Три базові мови інтерфейсу: UA/RU/EN.&lt;/li&gt;&lt;li&gt;Scoped assets і storefront endpoints; після встановлення тема не активується сама.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Тема об’єднує ключові storefront-функції в одному узгодженому дизайні, тому не потрібно складати базову вітрину з десятків дрібних модифікаторів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Новим магазинам і проектам, яким потрібна повноцінна сучасна тема для OpenCart/ocStore 3.x із вбудованими ecommerce-функціями.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;Самостійна тема, не UniShop2 add-on&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=92 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;OpenCart Theme PRO is a commercial storefront theme for OpenCart/ocStore 3.x with a responsive catalog, product cards, navigation, promotional blocks and store-specific presentation settings.&lt;/p&gt;&lt;p&gt;A theme affects almost every storefront page, so compatibility with extensions, SEO output, mobile layout and performance matters more than simply changing colors. The theme is intended as the visual layer while store business logic remains in OpenCart and independent extensions.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Protects category pages from duplicate technical URLs with sort, order, limit, filter and page parameters. By default it adds noindex,follow only to technical URL variants. Enable clean canonical only if no other SEO module already outputs canonical links.&lt;/li&gt;&lt;li&gt;Extends Product schema: brand, sku/mpn/gtin, images, priceValidUntil, aggregateRating, reviews, shippingDetails and return policy when data is available.&lt;/li&gt;&lt;li&gt;CodeCart PRO Theme v8.6.7 Bootstrap 3.4.1 is an open commercial theme for ocStore/OpenCart 3.x with merchant-level SEO schema, digital module commerce UX, AJAX category navigation, blog, product blocks, quick requests, reviews, mega menu and mobile storefront logic.&lt;/li&gt;&lt;li&gt;Hides prices, quantity controls, Buy/quick-order buttons, cart links and checkout access while preserving product descriptions, stock, benefits, wishlist, compare, sharing and product carousels. Enable it when the website must work as a catalogue without sales.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that need a modern responsive storefront while preserving the OpenCart 3.x extension ecosystem.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=92 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;OpenCart Theme PRO — коммерческая витринная тема для OpenCart/ocStore 3.x с адаптивным каталогом, карточками товаров, навигацией, промо-блоками и настройками оформления.&lt;/p&gt;&lt;p&gt;Тема влияет почти на всю витрину, поэтому важны совместимость с модулями, SEO-выводом, мобильной версткой и производительностью, а не только цвета. Бизнес-логика остаётся в OpenCart и независимых расширениях.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Расширяет Product schema: brand, sku/mpn/gtin, images, priceValidUntil, aggregateRating, reviews, shippingDetails и return policy при наличии данных.&lt;/li&gt;&lt;li&gt;Защищает категории от дублей с параметрами sort, order, limit, filter и page. По умолчанию добавляет noindex,follow только для технических вариантов URL. Canonical на чистую категорию включайте только если уверены, что на сайте нет другого canonical от SEO-модуля.&lt;/li&gt;&lt;li&gt;Выберите изображение через менеджер изображений. Сохраняется относительный путь из каталога image, например catalog/backgrounds/site-bg.jpg. Внешние URL не принимаются.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которым нужна современная адаптивная витрина при сохранении экосистемы OpenCart 3.x.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=92 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;VAT Price Input PRO&lt;/strong&gt; дозволяє для товарів VAT-компанії вводити в адмінці кінцеву ціну для покупця з ПДВ, а модуль розраховує й зберігає правильну net price для стандартного механізму Tax Classes OpenCart.&lt;/p&gt;&lt;p&gt;Для товарів ФОП/sole proprietor можна зберігати кінцеву ціну без ПДВ. Сам відсоток ПДВ не «зашивається» в модуль — він залишається у стандартних Tax Classes/Tax Rates OpenCart.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Окремий seller/tax mode для товарів без ПДВ та VAT-компанії.&lt;/li&gt;&lt;li&gt;Введення gross/final customer price для VAT-товару з розрахунком стандартної net product.price.&lt;/li&gt;&lt;li&gt;Підтримка основної ціни, discounts, specials та option price adjustments.&lt;/li&gt;&lt;li&gt;Інформаційний показ «ПДВ включено» або «ціна без ПДВ».&lt;/li&gt;&lt;li&gt;Використання процентних стандартних Tax Rates і tax context магазину.&lt;/li&gt;&lt;li&gt;Захист від неоднозначних fixed/address-dependent tax сценаріїв, де неможливо надійно відновити одну gross price.&lt;/li&gt;&lt;li&gt;Масовий перерахунок після зміни ставок — вручну, без окремого cron.&lt;/li&gt;&lt;li&gt;Опціональна інтеграція Product Currency Input PRO для валютних товарів.&lt;/li&gt;&lt;li&gt;Безпечний uninstall не змінює ціни автоматично; окрема контрольована дія Prepare products for removal конвертує керовані VAT-товари у фінальні ціни No Tax.&lt;/li&gt;&lt;li&gt;Не розділяє одне замовлення між різними юридичними особами й не виконує fiscalization.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Менеджер може працювати з тією сумою, яку реально бачить покупець, не обчислюючи net price вручну для кожного товару.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, де частина товарів продається без ПДВ, а частина — від VAT-компанії, або адміністратору зручніше вводити саме кінцеву ціну з податком.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=93 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;VAT Price Input PRO lets administrators enter a VAT-inclusive or business-facing price while preserving the native OpenCart tax and price model used on the storefront.&lt;/p&gt;&lt;p&gt;The module is designed for stores where managers think in VAT-inclusive sales prices but OpenCart still needs a predictable standard price/tax-class workflow. It does not create a parallel storefront pricing engine.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Normal OpenCart cache clearing does not delete module data because important state is stored in the database. If modification cache/storage/modification is cleared, refresh Modifications. Verify FOP, VAT-company, Standard OpenCart, specials, discounts, options and Product Currency Input integration on a test product.&lt;/li&gt;&lt;li&gt;For dynamic product-price changes, the module detects the active currency precision (0–6 decimal places) and whether the installed currency formatter hides an all-zero fractional part. If zero decimals are hidden globally, the VAT/net line also hides them; a non-zero fractional amount remains visible at the active currency precision. Currency changes do not alter stored product prices or VAT calculations.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;B2C/B2B stores and accounting workflows where price entry with VAT is more convenient than manual reverse calculation.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=93 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;VAT Price Input PRO позволяет администратору вводить цену с НДС в удобном бизнес-формате, сохраняя штатную налоговую и ценовую модель OpenCart на витрине.&lt;/p&gt;&lt;p&gt;Модуль нужен там, где менеджер оперирует конечной ценой с НДС, но OpenCart должен продолжать использовать стандартный price/tax class сценарий. Отдельный движок цен для витрины не создаётся.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Отдельный cron для VAT Price Input не требуется. Массовый пересчет после изменения налоговых ставок запускается вручную из админки модуля; валютные товары дополнительно обслуживаются cron Product Currency Input, если он установлен и включен.&lt;/li&gt;&lt;li&gt;Обычная очистка кеша OpenCart не удаляет данные модуля: важные данные находятся в БД. После очистки storage/modification или кеша модификаторов обязательно обновите Модификаторы. Проверьте тестовый товар в режимах ФОП, ТОВ/ООО и Standard, а также акции, скидки, опции и связку с Product Currency Input.&lt;/li&gt;&lt;li&gt;Если нужно полностью отвязать каталог от модуля, нажмите «Подготовить товары к удалению модуля». Для ТОВ/ООО модуль преобразует основную цену, скидки, акции и ценовые надбавки опций обратно в конечные суммы с НДС с выбранным округлением и установит Tax Class «Без налога». Цены ФОП останутся без изменений. После успешной подготовки модуль автоматически выключится.&lt;/li&gt;&lt;li&gt;Подготовить управляемые товары к полному удалению VAT Price Input? Для ТОВ / ООО цены OpenCart будут преобразованы из базы без НДС в конечные цены с НДС, Tax Class будет отключён; ФОП останется без изменений. После завершения модуль будет выключен. Перед действием рекомендуется полный backup файлов и базы данных.&lt;/li&gt;&lt;li&gt;Модуль управляет налоговым режимом и ценой товара. Он не разделяет один заказ между разными юридическими лицами, не маршрутизирует оплату между ФОП и ТОВ/ООО и не выполняет фискализацию. Если разные продавцы должны принимать деньги и оформлять документы раздельно, для этого нужна отдельная логика заказа/оплаты.&lt;/li&gt;&lt;li&gt;В OpenCart выключено штатное «Показывать цены с налогом». Для товаров ТОВ / ООО модуль хранит product.price без НДС, поэтому при этой настройке витрина покажет цену без НДС. Включите отображение цен с налогом в настройках магазина, чтобы покупатель видел введенную конечную цену с НДС.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;B2C/B2B магазинам и бухгалтерским сценариям, где удобнее вводить конечную цену с НДС без ручного обратного пересчёта.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=93 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Supplier Sync Parser PRO&lt;/strong&gt; призначений для постачальників, які не надають XML, CSV або API. Модуль читає HTML сторінок за XPath-правилами, збирає ціни, залишки й товарні дані та показує результат у preview перед застосуванням.&lt;/p&gt;&lt;p&gt;Робочий сценарій побудований навколо одного реального товару: адміністратор сканує сторінку, перевіряє знайдені name/price/stock/SKU/image/description, зберігає правила, формує чергу й лише потім застосовує зміни.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Окремі профілі постачальників із base URL, валютою, мовою та правилами.&lt;/li&gt;&lt;li&gt;XPath-парсинг товарної сторінки й category pages.&lt;/li&gt;&lt;li&gt;Domain guard: за замовчуванням crawler не переходить на сторонні домени/субдомени без дозволу.&lt;/li&gt;&lt;li&gt;Зовнішній CDN можна використовувати як джерело зображення, але сторонній HTML не потрапляє в чергу без дозволеного host.&lt;/li&gt;&lt;li&gt;Зіставлення існуючих товарів за SKU, EAN, UPC, MPN, supplier URL і title.&lt;/li&gt;&lt;li&gt;Preview із per-row діями: update, skip, exclude, force або create.&lt;/li&gt;&lt;li&gt;New Products із ручним вибором категорії перед створенням.&lt;/li&gt;&lt;li&gt;Підтримка валют OpenCart і нормалізації ціни постачальника.&lt;/li&gt;&lt;li&gt;Черга пакетної обробки й рекомендована затримка між запитами.&lt;/li&gt;&lt;li&gt;Окремий linked-products режим для регулярного оновлення вже зіставлених позицій.&lt;/li&gt;&lt;li&gt;Cron із захищеним ключем; X-CCP-Cron-Key рекомендований, URL token залишений як compatibility fallback.&lt;/li&gt;&lt;li&gt;Зображення спочатку перевіряються у тимчасовому файлі й перейменовуються атомарно.&lt;/li&gt;&lt;li&gt;History, logs, run summaries, filters, sorting і pagination.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль дозволяє працювати навіть із постачальником без нормального фіда, але залишає масові зміни під контролем адміністратора.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які залежать від сайтів постачальників без API/XML/CSV і хочуть автоматизувати моніторинг цін, залишків та появу нових товарів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=94 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Supplier Sync Parser PRO parses supplier websites or structured sources and synchronizes linked catalog data through its own supplier profiles, mappings, queue and run history.&lt;/p&gt;&lt;p&gt;Supplier pages change independently from the store, so the module keeps source links, preview/runtime state and history rather than treating every scrape as an uncontrolled direct overwrite.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The module creates its own InnoDB utf8mb4 tables for suppliers, product links, queue, preview, new products, logs, history, images, exclusions, run reports, category map and runtime locks.&lt;/li&gt;&lt;li&gt;Recommended Google feed mapping: //item, g:title, g:description, g:link, g:image_link, g:additional_image_link, g:mpn, g:brand, g:product_type, g:availability, g:price.&lt;/li&gt;&lt;li&gt;Supplier Sync Parser PRO is designed for OpenCart/ocStore stores that receive products and prices from supplier websites without XML, CSV or API. The module does not change the catalog immediately: it collects data through HTML parsing, normalizes prices and stock, matches supplier items with local products and shows the result in a safe preview. This reduces manual work, speeds up updates for thousands of products and lowers the risk of damaging prices or product cards.&lt;/li&gt;&lt;li&gt;By default the module crawls only the supplier base domain and does not jump to unrelated sites. External CDN images may be downloaded as images, but are not queued as product pages. Add extra domains only deliberately, one host per line.&lt;/li&gt;&lt;li&gt;The module reads a sample XML/YML/CSV item and suggests fields for product name, model, SKU, price, stock, description, manufacturer and image. Review selected values and choose another candidate when needed.&lt;/li&gt;&lt;li&gt;First run the queue. The module saves found products into review preview: supplier product, matched local product, current price, new price and stock. Then select rows and apply only the needed action.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that receive product data from supplier websites and need repeatable monitored synchronization rather than manual copying.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=94 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Supplier Sync Parser PRO получает данные с сайтов/источников поставщиков и синхронизирует связанные товары через профили, mapping, очередь и историю запусков.&lt;/p&gt;&lt;p&gt;Страницы поставщиков меняются независимо от магазина, поэтому модуль хранит связи, preview/runtime состояние и историю вместо неконтролируемой прямой перезаписи каталога.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;По умолчанию модуль сканирует только базовый домен поставщика и не переходит на чужие сайты. Внешние CDN-картинки могут скачиваться как изображения, но не ставятся в очередь как товары. Дополнительные домены указывайте только осознанно, по одному хосту в строке.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которые получают данные с сайтов поставщиков и хотят повторяемую контролируемую синхронизацию вместо ручного копирования.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=94 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Source Copy Protection PRO&lt;/strong&gt; допомагає зменшити побутове копіювання контенту й зберегти посилання на джерело: може додавати source URL у clipboard або блокувати вибрані дії браузера.&lt;/p&gt;&lt;p&gt;Це клієнтський JavaScript-захист, а не DRM. Технічно досвідчений користувач усе одно може отримати публічний HTML, тому модуль призначений для стримування звичайного copy/paste і збереження атрибуції, а не для обіцянки абсолютного захисту.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Режим None — жодної витринної логіки.&lt;/li&gt;&lt;li&gt;Append source — копіювання дозволене, у clipboard додається налаштований текст/посилання на джерело.&lt;/li&gt;&lt;li&gt;Maximum blocking — блокуються вибрані copy-protection дії.&lt;/li&gt;&lt;li&gt;Append source + technical blocking — одночасна атрибуція й обмеження.&lt;/li&gt;&lt;li&gt;Блокування context menu з окремою опцією для input/editor зон.&lt;/li&gt;&lt;li&gt;Опціональне блокування selection, drag, copy/cut і поширених hotkeys.&lt;/li&gt;&lt;li&gt;Налаштування для різних груп сторінок і custom routes.&lt;/li&gt;&lt;li&gt;Де можливо, модуль записує text/plain і text/html, зберігаючи форматування вибраного фрагмента.&lt;/li&gt;&lt;li&gt;Strict OFF: немає frontend Event, JS/CSS, фонових процесів або додаткових storefront requests.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Append Source часто є практичнішим за повне блокування: користувач може цитувати текст, але разом із ним переноситься джерело.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Контентним магазинам, блогам і сайтам, де важливо зменшити просте копіювання текстів або додавати джерело до скопійованого фрагмента.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=95 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Source Copy Protection PRO adds basic storefront copy deterrence and source attribution when visitors copy text from the store.&lt;/p&gt;&lt;p&gt;It is a deterrence and attribution tool, not DRM: browser users can never be fully prevented from reading or reproducing content that is delivered to them. The useful goal is to discourage casual copying and preserve a source link where supported.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The module protects online store text content from basic copying and automatically appends a source link when visitors copy text fragments. This helps preserve attribution, return part of the traffic to the site and reduce casual copying of product descriptions, category texts, articles and information pages.&lt;/li&gt;&lt;li&gt;The module does not run background jobs and does not process queues. It only works while a storefront page is loaded, so Mirohost cron is not required.&lt;/li&gt;&lt;li&gt;The module can append a source link to copied text, block the browser context menu, restrict common copy/developer hotkeys, block text selection, block dragging, and block copy/cut events. Page groups and custom routes can be configured separately.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Content-heavy stores and publishers that want lightweight protection against casual copy/paste without pretending it is absolute content security.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=95 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Source Copy Protection PRO добавляет базовую защиту от простого копирования на витрине и может автоматически добавлять ссылку на источник к скопированному фрагменту.&lt;/p&gt;&lt;p&gt;Это средство сдерживания и атрибуции, а не DRM: контент, который уже передан браузеру, невозможно сделать абсолютно некопируемым. Реальная задача — усложнить простое копирование и сохранить ссылку на источник.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Модуль защищает текстовый контент интернет-магазина от простого копирования и автоматически добавляет ссылку на источник при копировании фрагментов текста. Это помогает сохранить авторство, вернуть часть переходов на сайт и уменьшить бытовое копирование описаний товаров, категорий, статей и информационных страниц.&lt;/li&gt;&lt;li&gt;JavaScript-защита не может полностью запретить копирование технически подготовленному пользователю. Коммерчески правильная задача модуля — уменьшить массовое бытовое копирование и сохранить ссылку на источник при нормальном копировании.&lt;/li&gt;&lt;li&gt;Модуль можно включать отдельно для главной страницы, товаров, категорий, производителей, информационных страниц, поиска, акций, блога, новостей UniShop2 и дополнительных route с поддержкой маски через звездочку.&lt;/li&gt;&lt;li&gt;Модуль не выполняет фоновые задачи и не обрабатывает очереди. Он работает только при загрузке страницы витрины, поэтому cron для Mirohost не требуется.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Контентным магазинам и сайтам, которым нужна лёгкая защита от обычного copy/paste без ложного обещания абсолютной защиты.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=95 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Social Login PRO&lt;/strong&gt; додає вхід, реєстрацію та прив’язку облікових записів покупця через Google, Apple, Facebook, Microsoft, PayPal, LinkedIn, Яндекс, Telegram і VK ID.&lt;/p&gt;&lt;p&gt;Модуль інтегрується у стандартні login/register/checkout сторінки й UniShop2. Існуючий customer може бути безпечно зв’язаний за email тільки там, де провайдер дійсно підтверджує цей email; якщо обов’язкових даних бракує, новий клієнт проходить додатковий крок їх введення.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;9 OAuth/OIDC-провайдерів.&lt;/li&gt;&lt;li&gt;Окреме ввімкнення Login, Register, стандартного Checkout, UniShop2 Checkout та UniShop2 Login.&lt;/li&gt;&lt;li&gt;Сторінка керування прив’язаними соціальними акаунтами в кабінеті покупця.&lt;/li&gt;&lt;li&gt;Google/Microsoft/Яндекс та інші сучасні flows із PKCE/OIDC там, де провайдер це підтримує.&lt;/li&gt;&lt;li&gt;Apple private key, Client Secret/App Secret зберігаються зашифровано через config_encryption.&lt;/li&gt;&lt;li&gt;Secret fields type=password; повне збережене значення не знаходиться у HTML і відкривається лише захищеним POST AJAX з правами.&lt;/li&gt;&lt;li&gt;Налаштовуваний збір імені, прізвища, email і телефону.&lt;/li&gt;&lt;li&gt;Мультимовні підписи кнопок, Brand/Neutral/Outline, Rounded/Pill/Square, різні розміри та layouts.&lt;/li&gt;&lt;li&gt;Live preview в адмінці.&lt;/li&gt;&lt;li&gt;Агрегована статистика без зберігання персональних OAuth-даних.&lt;/li&gt;&lt;li&gt;Events реєструються тільки для реально ввімкнених місць виводу; CSS не підключається глобально.&lt;/li&gt;&lt;li&gt;Без cron і фонових задач; OFF прибирає storefront Events та OAuth/API роботу.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Соціальний вхід скорочує форму реєстрації й кількість паролів, які клієнту потрібно пам’ятати.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із особистим кабінетом, повторними покупцями й мобільною аудиторією, для якої швидкий OAuth/OIDC-вхід зручніший за класичну реєстрацію.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;Стандартна тема / UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=96 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Social Login PRO lets customers authenticate through supported social identity providers and safely link a social identity to an OpenCart customer account.&lt;/p&gt;&lt;p&gt;A first social login must decide whether to create a new customer or link an existing one. Controlled email matching and stored provider identity reduce duplicate accounts while avoiding blind merging.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Recommended to enable. The module first looks for an existing linked social identity; if no link exists yet, it checks the customer\'s email. Automatic first-time linking is allowed only for verified Google/Apple email. After linking, login uses social ID → customer_id, so email or telephone changes made on the store remain authoritative in OpenCart and are not overwritten by provider data.&lt;/li&gt;&lt;li&gt;Social Login Pro adds secure Google, Apple, Facebook, Microsoft, PayPal, LinkedIn, Yandex, Telegram and VK sign-in to OpenCart accounts and checkout, including UniShop2. New customers can complete missing email/name/telephone/custom fields before account creation, while existing customer data remains authoritative.&lt;/li&gt;&lt;li&gt;Providers return different profile fields. Email is mandatory for a new account; Social Login Pro asks for any missing required fields before creating the customer. Delivery address is never imported from a social profile and remains the responsibility of checkout.&lt;/li&gt;&lt;li&gt;Yandex: email, first name, last name and phone depend on the permissions granted to the app. Social Login Pro does not treat the returned email as sufficient proof for automatic linking to an existing customer.&lt;/li&gt;&lt;li&gt;Preserve OpenCart profile. After the social identity is linked, future social logins use customer_id and never overwrite the customer email, telephone, name or address.&lt;/li&gt;&lt;li&gt;This setting only affects a phone obtained or collected by Social Login Pro while CREATING a new customer. The module never rewrites the phone of an existing customer.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that want a faster login/registration path through social providers while keeping normal OpenCart customer accounts.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=96 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Social Login PRO позволяет клиентам входить через поддерживаемых социальных провайдеров и безопасно связывать внешнюю identity с обычным аккаунтом OpenCart.&lt;/p&gt;&lt;p&gt;При первом входе нужно корректно решить, создать нового клиента или связать существующего. Контролируемое сопоставление email и сохранённая provider identity уменьшают дубли аккаунтов без слепого объединения.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Не применяется: модуль не работает с ценами, валютами, налогами, скидками, доставкой или расчётами заказа.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которым нужен более быстрый вход/регистрация через соцсети при сохранении стандартных аккаунтов OpenCart.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=96 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;SMSfly Order PRO&lt;/strong&gt; надсилає SMS/Viber повідомлення по замовленнях OpenCart/ocStore, дозволяє вручну відправити повідомлення зі сторінки замовлення та має окремі сценарії для UniShop2 Quick Order.&lt;/p&gt;&lt;p&gt;Модуль корисний там, де клієнту або менеджеру потрібне коротке оперативне повідомлення незалежно від email. Інтеграція з Nova Poshta дозволяє використовувати дані доставки в комунікації, якщо відповідний сценарій налаштований.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;SMS/Viber сповіщення про замовлення.&lt;/li&gt;&lt;li&gt;Ручне надсилання зі сторінки замовлення.&lt;/li&gt;&lt;li&gt;Окремі повідомлення UniShop2 Quick Order.&lt;/li&gt;&lt;li&gt;Інтеграція з Nova Poshta для пов’язаних сценаріїв.&lt;/li&gt;&lt;li&gt;Налаштовувані API-дані та шаблони.&lt;/li&gt;&lt;li&gt;Після встановлення модуль OFF; спочатку налаштовуються API й тексти, потім він вмикається вручну.&lt;/li&gt;&lt;li&gt;При OFF немає робочих API/AJAX-запитів і quick SMS UI в шапці адмінки.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Коротке SMS/Viber-повідомлення може швидше донести статус або важливу інформацію, коли клієнт не читає email одразу.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із SMS/Viber-комунікацією, UniShop2 Quick Order і доставкою Новою поштою.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=97 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SMSfly Order PRO sends order and quick-order notifications through SMS/Viber using configurable templates and order variables.&lt;/p&gt;&lt;p&gt;The module is useful when email is too slow for operational events and the store needs a short transactional message to the customer or manager after order-related actions.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Order and status notifications through SMS/Viber.&lt;/li&gt;&lt;li&gt;Separate templates with order variables for customer/manager communication.&lt;/li&gt;&lt;li&gt;Support for standard OpenCart orders and UniShop2 quick-order scenarios where configured.&lt;/li&gt;&lt;li&gt;Configurable event/status selection so messages are sent only for intended order transitions.&lt;/li&gt;&lt;li&gt;Delivery/provider errors can be logged for diagnostics instead of silently losing notifications.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores using SMS/Viber communication for order confirmation, status information or UniShop2 quick-order workflows.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=97 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SMSfly Order PRO отправляет уведомления о заказах и быстрых заявках через SMS/Viber по настраиваемым шаблонам и данным заказа.&lt;/p&gt;&lt;p&gt;Модуль полезен там, где email недостаточно оперативен и магазину нужно короткое транзакционное сообщение клиенту или менеджеру после события заказа.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;SMS/Viber уведомления о заказах и изменении статуса.&lt;/li&gt;&lt;li&gt;Отдельные шаблоны с переменными заказа для клиента/менеджера.&lt;/li&gt;&lt;li&gt;Поддержка стандартных заказов OpenCart и сценариев UniShop2 Quick Order при соответствующей настройке.&lt;/li&gt;&lt;li&gt;Выбор событий/статусов, при которых сообщение действительно должно отправляться.&lt;/li&gt;&lt;li&gt;Ошибки провайдера могут фиксироваться в диагностике вместо молчаливой потери уведомления.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, использующим SMS/Viber для подтверждения заказов, статусов и быстрых заявок UniShop2.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=97 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;SEO URL Generator FREE&lt;/strong&gt; — безкоштовний генератор чистих slug для OpenCart/ocStore 3.x. Актуальні адреси залишаються у стандартній таблиці seo_url, а старі slug можуть зберігатися для 301-редиректів у постійній таблиці історії.&lt;/p&gt;&lt;p&gt;FREE-версія підходить для базової автоматизації ЧПУ без ручної транслітерації кожної назви. Українська транслітерація враховує г/ґ/и/і та контекстне є/ї/й/ю/я.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Генерація SEO keyword для стандартних сутностей підтримуваної версії.&lt;/li&gt;&lt;li&gt;Українська транслітерація з коректною обробкою специфічних літер.&lt;/li&gt;&lt;li&gt;Статті, новини й інформаційні сторінки можуть отримувати коротші URL до восьми змістовних слів.&lt;/li&gt;&lt;li&gt;Назви товарів, категорій і виробників не скорочуються, щоб не втратити модель, артикул або важливе комерційне слово.&lt;/li&gt;&lt;li&gt;Актуальні SEO URL зберігаються у штатній seo_url.&lt;/li&gt;&lt;li&gt;Старі slug — у seo_url_generator_redirects для 301-історії.&lt;/li&gt;&lt;li&gt;При OFF UniShop2 News Events повністю відсутні.&lt;/li&gt;&lt;li&gt;Admin AJAX додатково перевіряє user_token; динамічні SQL identifiers проходять whitelist.&lt;/li&gt;&lt;li&gt;Сумісне оновлення зі старим OCMOD code без дублювання modification.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Безкоштовний модуль закриває основну рутину створення читабельних URL і може бути достатнім невеликому магазину.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Новим і невеликим магазинам, яким потрібні базові чисті SEO URL та українська транслітерація без покупки PRO-рішення.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=98 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SEO URL Generator FREE provides a free basic workflow for generating clean SEO URLs and maintaining selected redirects in OpenCart/ocStore.&lt;/p&gt;&lt;p&gt;It is intended for stores that need a lightweight CHPU/slug generator without the broader automation and diagnostics of the paid SEO URL PRO edition.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Unlike many similar solutions, SEO URL Generator Free allows you to input redirects for products, categories, manufacturers. After all, it happens that a product or category needs to be assigned a different link. There is such functionality nn many other CMS. Using this module, this is possible in OpenCart too.&lt;/li&gt;&lt;li&gt;Only real content entities are processed: products, categories, manufacturers, information pages, ocStore Blog and UniShop2 News. System route aliases such as common/home, product/search and feed URLs are shown only in diagnostics and are ignored by repair tools.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Small stores and new installations that need basic SEO URL generation before deciding whether advanced history, preview and mass tools are required.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=98 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SEO URL Generator FREE — бесплатный базовый инструмент генерации понятных SEO URL и отдельных редиректов в OpenCart/ocStore.&lt;/p&gt;&lt;p&gt;Он предназначен для магазинов, которым нужен лёгкий генератор ЧПУ без полного набора автоматизации и диагностики платной версии SEO URL PRO.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Платная версия модуля SEO URL Generator PRO позволяет генерировать SEO URL не только для отдельно взятого товара, а массово сгенерировать ЧПУ для сотен или тысяч товаров, которые уже есть в магазине. Или которые &quot;прилетят&quot; завтра при импорте от поставщика. Массовая генерация также может пригодиться в случае, если в Вашем магазине уже есть ЧПУ, но они морально устарели (используется нижнее подчеркивание) или в принципе нужно заменить их на более короткий вариант (к примеру, по product_id).&lt;/li&gt;&lt;li&gt;В отличие от многих похожих решений, SEO URL Generator Free позволяет Вам вписывать редиректы для товаров, категорий, производителей. Ведь такое бывает, что товару или категории необходимо присвоить другую ссылку. Во многих других CMS подобный функционал есть из коробки. С помощью данного модуля такое возможно и в OpenCart.&lt;/li&gt;&lt;li&gt;При редактировании товара (и др сущностей) их названия могут меняться. В таком случае старый SEO URL будет слегка не соответствовать. Если включить эту опцию, то при каждом редактировании сущности ее SEO URL будет актуализироваться, а старый SEO URL запишется в список редиректов со статусом 301.&lt;/li&gt;&lt;li&gt;Обрабатываются только реальные сущности контента: товары, категории, производители, информационные страницы, ocStore Blog и UniShop2 News. Системные route-алиасы common/home, product/search, feed URL показываются только в диагностике и не попадают в исправление.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Небольшим магазинам и новым установкам, которым достаточно базовой генерации SEO URL.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=98 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;SEO Meta Character Counter PRO&lt;/strong&gt; показує живі лічильники символів біля назви/H1, Meta Title, Meta Description, Meta Keywords і повних описів у формах OpenCart/ocStore.&lt;/p&gt;&lt;p&gt;Модуль нічого не генерує й не блокує збереження. Його задача — дати редактору візуальний контроль довжини тексту під час набору, включно з Summernote.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Налаштовувані ліміти для Name, H1, Meta Title, Meta Description, Meta Keywords та Description.&lt;/li&gt;&lt;li&gt;Стандартні орієнтири: 100 / 80 / 60 / 160 / 255 / 5000 символів.&lt;/li&gt;&lt;li&gt;Попередження починається з 90% налаштованого ліміту.&lt;/li&gt;&lt;li&gt;Перевищення підсвічується, але не блокує стандартне збереження.&lt;/li&gt;&lt;li&gt;Для HTML-описів рахується видимий текст без тегів.&lt;/li&gt;&lt;li&gt;Live tracking змін у Summernote.&lt;/li&gt;&lt;li&gt;Підтримка товарів, категорій, виробників, інформаційних сторінок, блогу й UniShop2 News у підтримуваних формах.&lt;/li&gt;&lt;li&gt;Жодних storefront assets, SQL-запитів, cron, queue, AJAX або catalog runtime.&lt;/li&gt;&lt;li&gt;Модуль OFF після встановлення.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Редактор одразу бачить занадто коротке або довге поле й може виправити його до збереження.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;SEO-фахівцям, контент-менеджерам і магазинам із великою кількістю мультимовних метаданих.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=99 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SEO Meta Character Counter PRO adds live character counters and length hints next to SEO fields in supported OpenCart admin forms.&lt;/p&gt;&lt;p&gt;The module does not generate text and does not change SEO values by itself. It simply makes field length visible while an administrator edits names, H1, Meta Title and Meta Description.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Live character counters next to supported SEO fields in OpenCart admin forms.&lt;/li&gt;&lt;li&gt;Separate guidance for product/category/information/manufacturer and supported blog/news edit pages.&lt;/li&gt;&lt;li&gt;Works while typing and does not alter the saved value.&lt;/li&gt;&lt;li&gt;No database tables, cron or background jobs are required for the counter itself.&lt;/li&gt;&lt;li&gt;Useful for Meta Title, Meta Description, H1/name and other supported text fields.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Content managers and SEO specialists who want immediate length feedback inside normal OpenCart edit forms.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=99 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;SEO Meta Character Counter PRO добавляет живые счётчики символов и подсказки длины рядом с SEO-полями в поддерживаемых формах OpenCart.&lt;/p&gt;&lt;p&gt;Модуль не генерирует текст и сам не меняет SEO-значения. Он только показывает длину при редактировании названия, H1, Meta Title и Meta Description.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Живые счётчики символов рядом с поддерживаемыми SEO-полями в формах OpenCart.&lt;/li&gt;&lt;li&gt;Поддержка товаров, категорий, информации, производителей и совместимых страниц блога/новостей.&lt;/li&gt;&lt;li&gt;Счётчик работает при вводе и не изменяет сохраняемое значение.&lt;/li&gt;&lt;li&gt;Для самого счётчика не нужны отдельные таблицы, cron или фоновые задачи.&lt;/li&gt;&lt;li&gt;Полезен для Meta Title, Meta Description, H1/name и других поддерживаемых текстовых полей.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Контент-менеджерам и SEO-специалистам, которым нужен мгновенный контроль длины прямо в стандартных формах OpenCart.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=99 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;reCAPTCHA Security PRO&lt;/strong&gt; захищає форми OpenCart/ocStore не лише JavaScript-віджетом, а серверною перевіркою token для Google reCAPTCHA, reCAPTCHA Enterprise або hCaptcha.&lt;/p&gt;&lt;p&gt;Модуль орієнтований на контактні форми, login/register, password recovery, reviews і вибрані checkout-сценарії. Пряма POST/AJAX-відправка без валідної перевірки не повинна обходити захист лише тому, що бот не запускав фронтенд JS.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Google reCAPTCHA v2 Checkbox, v2 Invisible, v3 Score і reCAPTCHA Enterprise.&lt;/li&gt;&lt;li&gt;hCaptcha Checkbox та Invisible як незалежна альтернатива.&lt;/li&gt;&lt;li&gt;Окремі пороги/режими для реєстрації, відгуків, login і checkout.&lt;/li&gt;&lt;li&gt;Режим завантаження Google JS при submit, щоб не підключати його завчасно на всіх сторінках.&lt;/li&gt;&lt;li&gt;Тестовий режим для перевірки нестандартної форми без блокування покупця.&lt;/li&gt;&lt;li&gt;Журнал перевірок із фільтрами, сортуванням, пагінацією й зрозумілими причинами.&lt;/li&gt;&lt;li&gt;Secret Key та Enterprise API Key не повертаються у HTML адмінки; порожнє поле зберігає поточний secret, видалення — окрема підтверджувана дія.&lt;/li&gt;&lt;li&gt;Жива діагностика пари ключів, hostname, action, score і HTTP-відповіді.&lt;/li&gt;&lt;li&gt;Cron не потрібен; журнал обслуговується контрольованими пакетами не частіше заданого інтервалу.&lt;/li&gt;&lt;li&gt;OFF прибирає catalog Events і runtime-навантаження.&lt;/li&gt;&lt;li&gt;Не є WAF/Anti-DDoS і не замінює Bot Security PRO або серверний firewall.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Серверна валідація закриває типову помилку, коли CAPTCHA є на сторінці, але backend усе одно приймає прямий POST.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із формами контактів, відгуками, реєстрацією та спамом, де потрібна перевірка саме на сервері.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=100 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;reCAPTCHA Security PRO performs server-side reCAPTCHA validation for selected OpenCart forms and protects direct POST/AJAX submissions, not only the visible browser widget.&lt;/p&gt;&lt;p&gt;A CAPTCHA is useful only if the server verifies the token before accepting the action. The module is aimed at spam registration, login abuse, fake reviews and automated form submissions.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;reCAPTCHA Security protects ocStore/OpenCart forms from automated spam, mass registration, login abuse, fake reviews and direct POST/AJAX submissions. It performs server-side Google reCAPTCHA, reCAPTCHA Enterprise or hCaptcha verification and is not a global WAF, Anti-DDoS product or Cloudflare replacement.&lt;/li&gt;&lt;li&gt;The storefront CAPTCHA integration supports normal form submit controls and AJAX action buttons (including product review/question buttons using type=&quot;button&quot;). In v3/invisible modes the token is obtained before the original AJAX action continues. In v2 checkbox mode an unchecked challenge blocks the AJAX action until completed.&lt;/li&gt;&lt;li&gt;The commercial package includes en-gb, ru-ru and uk-ua. If the active OpenCart/ocStore language has no module translation, the module safely falls back to en-gb. Custom valid translations are used automatically when present. A missing or malformed translation must never disable CAPTCHA or break the storefront/admin area.&lt;/li&gt;&lt;li&gt;Standard UniShop2/OpenCart forms that already render the CAPTCHA block should not be added to custom-form protection again. For a custom quick-order, callback or other AJAX handler, identify the exact route, start in test-only mode, then enable blocking.&lt;/li&gt;&lt;li&gt;No cron task is required. Log maintenance requires no cron, runs at most once every 5 minutes and is protected by a file lock. Old rows are deleted in safe batches by both retention age and maximum row count; whichever limit is reached first applies.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores suffering from form spam or automated account/review submissions that need centralized server-side CAPTCHA checks.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=100 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;reCAPTCHA Security PRO выполняет серверную проверку reCAPTCHA для выбранных форм OpenCart и защищает прямые POST/AJAX запросы, а не только показывает виджет в браузере.&lt;/p&gt;&lt;p&gt;CAPTCHA имеет смысл только когда токен проверяется сервером до принятия действия. Модуль рассчитан на спам-регистрации, злоупотребление входом, фальшивые отзывы и автоматические формы.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;reCAPTCHA Security защищает формы ocStore/OpenCart от автоматического спама, массовых регистраций, перебора входа, ложных отзывов и прямой отправки POST/AJAX-запросов. Модуль выполняет серверную проверку Google reCAPTCHA, reCAPTCHA Enterprise или hCaptcha и не является глобальным WAF, Anti-DDoS или заменой Cloudflare.&lt;/li&gt;&lt;li&gt;Рекомендуемая настройка: установить модуль и оставить выключенным; создать отдельные ключи Google для нужного режима; выбрать режим; проверить ключи; сохранить; выбрать модуль как CAPTCHA магазина для штатных форм; проверить формы. Дополнительную защиту нестандартных форм включать только для конкретных пользовательских POST/AJAX-маршрутов и сначала в тестовом режиме.&lt;/li&gt;&lt;li&gt;Штатные формы UniShop2/OpenCart, в которых уже выводится блок CAPTCHA, не нужно повторно добавлять в дополнительную защиту нестандартных форм. Для собственного быстрого заказа, обратного звонка или другого AJAX-обработчика сначала определите точный route, включите тестовый режим и только затем блокирование.&lt;/li&gt;&lt;li&gt;Cron модулю не требуется. Обслуживание журнала выполняется без cron не чаще одного раза в 5 минут и защищено файловой блокировкой. Старые записи удаляются безопасными пакетами по двум ограничениям: срок хранения и максимальное число строк; применяется то ограничение, которое наступило первым.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам со спамом и автоматизированными регистрациями/отзывами, которым нужна централизованная серверная CAPTCHA-проверка.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=100 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Product Video Gallery PRO&lt;/strong&gt; додає відео поруч із фотографіями товару: відео показується як мініатюра Play, відкривається у popup і не завантажує важкий iframe до кліку.&lt;/p&gt;&lt;p&gt;Модуль зберігає відео в БД, використовує стандартну кнопку «Зберегти» товару та є єдиним власником VideoObject JSON-LD для відео галереї і YouTube iframe з HTML-опису.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;YouTube, Vimeo, TikTok, Facebook, Rutube, VK і OK відео.&lt;/li&gt;&lt;li&gt;Позиція відео на початку або в кінці додаткової галереї; стандартно в кінці, щоб головне фото залишалося LCP-елементом.&lt;/li&gt;&lt;li&gt;Popup відкриває відео після кліку; iframe не завантажується заздалегідь.&lt;/li&gt;&lt;li&gt;Нормалізація YouTube iframe у description: embed URL, title, allow, allowfullscreen.&lt;/li&gt;&lt;li&gt;Єдиний VideoObject JSON-LD без дублювання однакових YouTube ID між галереєю та описом.&lt;/li&gt;&lt;li&gt;Remote thumbnails кешуються локально в image/catalog/product_video_gallery_pro/video/ і віддаються через image/cache.&lt;/li&gt;&lt;li&gt;YouTube thumbnail визначається автоматично; для інших платформ можна вказати thumbnail або fallback на фото товару.&lt;/li&gt;&lt;li&gt;UniShop2 bridge: міні-галерея може створитися навіть якщо у товару немає додаткових фото.&lt;/li&gt;&lt;li&gt;Адаптер для Sitemap PRO.&lt;/li&gt;&lt;li&gt;Remote thumbnail loader захищений HTTPS whitelist/public-IP перевірками та redirect validation.&lt;/li&gt;&lt;li&gt;CSS/JS підключаються тільки для товару з активним відео й увімкненою галереєю.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Відео допомагає показати роботу техніки, комплектацію або інструкцію, не перетворюючи опис на набір важких iframe.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам техніки, інструменту, обладнання та іншим товарам, де демонстрація відео суттєво допомагає покупцю.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=101 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Video Gallery PRO adds product videos to the normal product media gallery so photos and video can be presented in one storefront experience.&lt;/p&gt;&lt;p&gt;Video can explain operation, scale or installation better than static photos, but it should remain lightweight. The module therefore works with video sources and cached thumbnails rather than turning every product page into a heavy embedded-media wall.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Remote thumbnails are cached into image/catalog/product_video_gallery_pro/video/ and then served from image/cache on the storefront.&lt;/li&gt;&lt;li&gt;The module adds product videos next to images: play thumbnail, popup viewer, VideoObject, and Sitemap Pro adapter.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores selling equipment, tools, electronics or other products where demonstrations improve the product page.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=101 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Video Gallery PRO добавляет видео в обычную медиагалерею товара, чтобы фотографии и видеодемонстрации работали в одном интерфейсе карточки.&lt;/p&gt;&lt;p&gt;Видео лучше фото показывает работу, масштаб или монтаж, но страница не должна становиться тяжёлой. Поэтому модуль работает с источниками видео и кешируемыми thumbnail.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Product Video Gallery PRO добавляет видео товара рядом с изображениями в карточке товара OpenCart/ocStore. Видео выводится в галерее дополнительных изображений товара как миниатюра с кнопкой Play, открывается в popup без загрузки iframe до клика, нормализует YouTube iframe в HTML-описании товара, является единым владельцем VideoObject JSON-LD и предоставляет adapter-метод для CodeCart Sitemap PRO.&lt;/li&gt;&lt;li&gt;Нет thumbnail для Google-разметки: для YouTube thumbnail определяется автоматически и при сохранении кешируется в image/catalog/product_video_gallery_pro/video/. Для других платформ укажите thumbnail вручную или включите fallback на фото товара.&lt;/li&gt;&lt;li&gt;Управление видео товара в галерее изображений, безопасными embed-ссылками провайдеров, VideoObject-разметкой и будущей интеграцией с Sitemap Pro.&lt;/li&gt;&lt;li&gt;Модуль добавляет видео товара рядом с изображениями: миниатюра с play, popup-просмотр, VideoObject и адаптер для Sitemap Pro.&lt;/li&gt;&lt;li&gt;Модуль является единственным владельцем VideoObject для видео галереи и YouTube iframe из описания товара, с удалением дублей.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам техники, инструментов, электроники и других товаров, где видеодемонстрация усиливает карточку.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=101 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Product Stats PRO&lt;/strong&gt; показує в адмінці компактні показники стану каталогу й відкриває стандартний список товарів уже з відповідним серверним фільтром.&lt;/p&gt;&lt;p&gt;Модуль не змінює товари, ціни, залишки або SEO URL. Його задача — швидко показати проблемні групи й дати адміністратору перейти до виправлення штатними інструментами.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Увімкнені/вимкнені товари, нульовий залишок, неправильна ціна, shipping flag.&lt;/li&gt;&lt;li&gt;Відсутній SEO URL, виробник або коректний category relation.&lt;/li&gt;&lt;li&gt;Головна категорія: main_category → main_category_id → безпечний fallback; окремо виявляється конфлікт кількох головних категорій.&lt;/li&gt;&lt;li&gt;Контроль SKU, UPC, EAN, JAN, ISBN, MPN, location, tax class, dimensions і weight.&lt;/li&gt;&lt;li&gt;Проблемне або відсутнє головне зображення.&lt;/li&gt;&lt;li&gt;Окремий ручний Image Audit розмірів — не запускається на кожному відкритті Каталогу.&lt;/li&gt;&lt;li&gt;Аудит фото працює захищеними AJAX-пакетами по 40 товарів і зберігає прогрес у БД.&lt;/li&gt;&lt;li&gt;Окремі лічильники маленьких main/additional images і файлів, розмір яких не читається.&lt;/li&gt;&lt;li&gt;Мінімальна ширина/висота налаштовуються окремо; стандартно 500×500.&lt;/li&gt;&lt;li&gt;Результати аудиту використовуються тими самими серверними фільтрами.&lt;/li&gt;&lt;li&gt;Кешування статистики; refresh запускається вручну.&lt;/li&gt;&lt;li&gt;Cron свідомо не потрібен.&lt;/li&gt;&lt;li&gt;Візуальні індикатори фото в списку товарів залишаються функцією Image Manager PRO, щоб модулі не дублювали один одного.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Власник бачить стан каталогу як набір конкретних задач: які товари без SEO URL, без бренду, без фото або з помилкою категорії.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Адміністраторам, SEO-фахівцям і контент-менеджерам, які хочуть контролювати повноту великого каталогу без експорту в Excel.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=102 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Stats PRO provides compact clickable catalog-health statistics and dedicated image auditing without modifying product data.&lt;/p&gt;&lt;p&gt;Its purpose is fast diagnostics: missing SEO URLs, incorrect prices, missing images/manufacturers/categories, negative stock and other integrity signals can be opened through the standard product list filters.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Image dimensions are checked only by the dedicated audit in the left admin sidebar. The Image Audit block has its own Start, Stop and Refresh controls, progress bar, and stores results in the database. Product Stats PRO does not add image-quality badges, counters, or markers to the product list; that remains the responsibility of Image Manager PRO.&lt;/li&gt;&lt;li&gt;Important for v3.4.8: Product Stats PRO does not render red/yellow/green/gray image indicators or duplicate photo counters in the product list. Image dimension audit is shown only in the dedicated left admin sidebar block. Product-list image counts and visual image-state markers belong to Image Manager PRO.&lt;/li&gt;&lt;li&gt;Clickable sidebar counters now filter through the native Catalog &gt; Products model path. This keeps Product Stats independent from Image Manager PRO while preserving third-party product-list integrations. The image-audit counter and the filtered product list use the same saved Product Stats audit condition.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Store administrators and catalog managers who want a quick health dashboard without mixing it with image-management functionality.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=102 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Stats PRO показывает компактную кликабельную статистику состояния каталога и отдельный аудит изображений, не изменяя сами товары.&lt;/p&gt;&lt;p&gt;Задача модуля — быстро найти отсутствующие SEO URL, неправильные цены, фото, производителей, категории, отрицательные остатки и другие признаки проблем через стандартные фильтры списка товаров.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Важно для v3.4.8: Product Stats PRO не выводит в списке товаров красные/жёлтые/зелёные/серые индикаторы изображений и не дублирует счётчик фотографий. Аудит размеров изображений отображается только в отдельном блоке левой колонки админки. Отображение количества и состояния фото непосредственно в списке товаров относится к Image Manager PRO.&lt;/li&gt;&lt;li&gt;Product Stats PRO показывает компактную кликабельную статистику целостности каталога и открывает стандартный список товаров с соответствующим серверным фильтром. Данные товаров модуль не изменяет.&lt;/li&gt;&lt;li&gt;Размеры изображений проверяются только отдельным аудитом из левой колонки админки. Блок «Аудит фото» имеет собственные кнопки запуска, остановки и обновления состояния, полосу прогресса и сохраняет результат в БД. В списке товаров Product Stats PRO не добавляет значки, счётчики или маркеры качества изображений — это остаётся задачей Image Manager PRO.&lt;/li&gt;&lt;li&gt;Кликабельные счётчики в боковой панели теперь фильтруют через штатный путь модели Каталог &gt; Товары. Product Stats остаётся независимым от Image Manager PRO и сохраняет совместимость со сторонними расширениями списка товаров. Счётчик аудита фото и отфильтрованный список используют одно и то же сохранённое условие аудита Product Stats.&lt;/li&gt;&lt;li&gt;Быстрое выявление отсутствующих SEO URL, некорректных цен, отсутствующих или удалённых главных изображений, производителей, повреждённых категорий, отсутствующих и конфликтующих главных категорий, отрицательных остатков и признака доставки.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Администраторам и контент-менеджерам, которым нужен быстрый контроль целостности каталога без смешивания с Image Manager.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=102 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Product Unit PRO&lt;/strong&gt; додає одиницю продажу поруч із ціною й, за окремого ввімкнення, дозволяє реальні дробові кількості: 0.5 кг, 1.2 м, 2.75 л, 3.5 пог. м тощо.&lt;/p&gt;&lt;p&gt;Звичайні товари залишаються цілими, доки fractional sale не ввімкнений глобально й для конкретного товару. Для дробового товару OpenCart продовжує рахувати ціну, податок, валюту, знижки, вагу й totals через стандартні механізми, але quantity стає decimal.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Вбудовані одиниці: шт., м, пог. м, л, мл, кг, г, м², м³, pack, package, roll, set, kit, pair, bag, canister.&lt;/li&gt;&lt;li&gt;Власна мультимовна назва одиниці та додаткова примітка біля ціни.&lt;/li&gt;&lt;li&gt;Per-product перемикач Show unit next to price.&lt;/li&gt;&lt;li&gt;Per-product Fractional sale, step, стандартний minimum і опціональний maximum.&lt;/li&gt;&lt;li&gt;Приклад: 85/пог. м, step 0.1, minimum 0.5, quantity 2.7 → 229.50.&lt;/li&gt;&lt;li&gt;Дробовий flow охоплює product/list, standard cart, UniShop2, mini-cart, UniCheckout, Quick Order, order_product, stock subtraction/restock і returns.&lt;/li&gt;&lt;li&gt;Recurring/subscription продукти свідомо блокуються в fractional mode.&lt;/li&gt;&lt;li&gt;При явному ввімкненні fractional sale потрібні quantity-колонки мігрують у DECIMAL(15,4).&lt;/li&gt;&lt;li&gt;При вимкненні operational quantities контрольовано повертаються до INT із CEIL; історичні order_product/return з реальними дробами не переписуються, щоб не псувати історію.&lt;/li&gt;&lt;li&gt;Поля Product Unit у товарі зберігаються тільки стандартною кнопкою OpenCart, окремого AJAX-save немає.&lt;/li&gt;&lt;li&gt;VAT Price Input PRO та Product Currency Input PRO — опціональні інтеграції, а не залежності.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль дозволяє продавати кабель, тканину, рідину, ваговий товар або матеріал у реальній дробовій кількості, а не імітувати кожен метр окремою опцією.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам матеріалів, кабелю, агротоварів, рідин, сипучих товарів і будь-якому каталогу, де одиниця продажу не завжди «1 штука».&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=103 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Unit PRO adds a sales unit to the product price and optionally enables fractional quantity with per-product step, minimum, maximum and stock handling.&lt;/p&gt;&lt;p&gt;Fractional sales affect cart, checkout, stock deduction, options, orders and returns, so the module treats them as a catalog-wide data model change rather than a cosmetic quantity input.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Disabling Product Unit or global fractional sale will convert the live catalog back to whole quantities. Fractional product stock, minimum, option stock, discount thresholds and active cart quantities are rounded UP (for example 5.7 becomes 6), then operational columns are restored to INT. Historical fractional order and return quantities are preserved. Create a full database backup before continuing. Continue?&lt;/li&gt;&lt;li&gt;Compatibility: CodeCart 3.0.5.2, OpenCart 3.x, ocStore 3.0.x, PHP 7.4–8.5, standard theme; UniShop2 v3.6.4.0 source compatibility bridge included. Other themes are supported automatically when they use standard OpenCart Cart/Order APIs; a custom checkout/quick order may require an additional bridge. VAT Price Input PRO and Product Currency Input PRO are optional integrations, not dependencies.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores selling by meter, kilogram, liter, square meter or other units where customers may buy fractional quantities.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=103 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Unit PRO показывает единицу продажи рядом с ценой и при необходимости включает дробное количество с индивидуальными шагом, минимумом, максимумом и остатком.&lt;/p&gt;&lt;p&gt;Дробная продажа затрагивает корзину, checkout, списание остатков, опции, заказы и возвраты, поэтому это изменение модели количества, а не просто другое поле ввода.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Перед удалением обязательно сделайте полный backup. Удаление сначала переводит рабочий каталог обратно в целый режим: дробные остатки товара/опций, минимум, пороги скидок и активные корзины округляются вверх, а рабочие колонки возвращаются в INT. Исторические дробные количества уже созданных заказов и возвратов не переписываются и сохраняются точно. После этого Events и настройки модуля удаляются. Собственные таблицы Product Unit удаляются только если включена соответствующая настройка.&lt;/li&gt;&lt;li&gt;Product Unit показывает единицу продажи возле цены и поддерживает опциональную дробную продажу для каждого товара отдельно: индивидуальный шаг, минимум, максимум, дробный остаток, корзину, checkout, Quick Order, заказы, списание/возврат остатков и возвраты. Шаг количества задаётся отдельно в карточке каждого товара. При отключении дробного режима или удалении модуля рабочие дробные значения округляются вверх до целых единиц.&lt;/li&gt;&lt;li&gt;Отключение Product Unit или глобальной дробной продажи вернёт рабочий каталог к целым количествам. Дробные остатки товара, минимум, остатки опций, пороги скидок и количества в активных корзинах будут округлены ВВЕРХ (например 5,7 станет 6), после чего рабочие колонки вернутся в INT. Исторические дробные количества в уже созданных заказах и возвратах не изменяются. Перед продолжением сделайте полный backup базы данных. Продолжить?&lt;/li&gt;&lt;li&gt;UniShop2 v3.6.4.0 проверен непосредственно по исходникам темы. В его Quick Order найдено штатное приведение `(int)quantity`, которое округляло бы 2,7 до 2. Product Unit v1.1.6 содержит optional OCMOD bridge именно для `catalog/controller/extension/module/uni_quick_order.php`: дробное количество нормализуется по шагу/минимуму/максимуму без integer-округления, а recurring для дробных товаров блокируется. Если UniShop2 отсутствует, эта операция просто пропускается и не создаёт зависимости.&lt;/li&gt;&lt;li&gt;Дробный режим работает через карточку товара, товарные списки, стандартную корзину OpenCart, UniShop2, mini-cart, UniCheckout, Quick Order, создание заказа, order_product, списание/возврат товарного и опционного остатка и возвраты товара.&lt;/li&gt;&lt;li&gt;При последующем отключении глобальной дробной продажи, самого модуля или при удалении рабочие количества автоматически возвращаются к целому режиму. Дробные остатки товара, минимум, остатки опций, пороги скидок и активные корзины округляются вверх (5,7 → 6), затем рабочие колонки возвращаются в INT. Исторические дробные количества уже созданных заказов и возвратов не округляются и не переписываются; их DECIMAL-колонки сохраняются только при наличии реальных дробных значений.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которые продают метрами, килограммами, литрами, квадратными метрами и другими дробными единицами.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=103 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Product Manager PRO&lt;/strong&gt; поєднує швидку таблицю керування товарами з Product Completeness Audit: адміністратор може редагувати безпечні поля inline, виконувати масові дії й одночасно контролювати SEO, зображення, маржу та повноту каталогу.&lt;/p&gt;&lt;p&gt;Важкі перевірки не запускаються при кожному відкритті сторінки: image/file audit працює вручну, AJAX-пакетами або через захищену cron-чергу. Модуль після встановлення OFF.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Швидка таблиця товарів з inline editing.&lt;/li&gt;&lt;li&gt;Product completeness і SEO audit.&lt;/li&gt;&lt;li&gt;Аудит main/additional images, broken і duplicate additional image records.&lt;/li&gt;&lt;li&gt;Важкі size/dimension checks та опціональні WebP/AVIF cache checks.&lt;/li&gt;&lt;li&gt;Безпечне очищення broken/duplicate product_image записів без фізичного видалення файлів.&lt;/li&gt;&lt;li&gt;Перший валідний additional image можна підняти в main, якщо main відсутній/битий.&lt;/li&gt;&lt;li&gt;Окрема cost price table, minimum margin і target margin.&lt;/li&gt;&lt;li&gt;Перерахунок вибраних цін за цільовою маржею.&lt;/li&gt;&lt;li&gt;Масове add/update/delete атрибутів для вибраних товарів у поточній мові адмінки.&lt;/li&gt;&lt;li&gt;Quick language mismatch check.&lt;/li&gt;&lt;li&gt;Protected catalog cron route з secret key для audit queue.&lt;/li&gt;&lt;li&gt;CSV export результатів і історія inline/mass змін.&lt;/li&gt;&lt;li&gt;Undo відновлює збережені DB snapshots для багатьох mass actions; фізичні файли зображень не відтворюються/не видаляються.&lt;/li&gt;&lt;li&gt;Сумісність із ocStore meta_h1/noindex визначається через schema detection; складні tabs options/discounts/recurring/layout/downloads/related залишаються штатній картці OpenCart.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль економить час у великих каталогах, але не намагається перенести всі складні поля товару в одну небезпечну spreadsheet-таблицю.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Контент-менеджерам і адміністраторам великих магазинів, де стандартна картка товару занадто повільна для щоденних масових операцій.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=104 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Manager PRO combines bulk product management with catalog-completeness, SEO and image diagnostics from one administrative workspace.&lt;/p&gt;&lt;p&gt;It is meant to reduce repetitive editing while keeping complex OpenCart structures such as options, recurring profiles, layouts and related products in the native product card when unsafe bulk editing would create risk.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Undo now restores more mass actions: category snapshots, deleted product_image rows when possible, attribute changes, margin rule changes, prices, statuses, quantities, manufacturer, special price, main category, meta fields and SEO URL.&lt;/li&gt;&lt;li&gt;Audit, quick edit, mass actions, undo, cron, image/SEO checks and Product Currency Input integration are unchanged.&lt;/li&gt;&lt;li&gt;Compatibility update v1.2.0: added support for ocStore product fields meta_h1, meta_keyword, noindex, UPC/EAN/JAN/ISBN/MPN/location, shipping, points, tax class, weight and dimensions in product list/AJAX layer where applicable. Complex product tabs such as options, discounts, recurring payments, layouts, downloads and related products remain managed by the native OpenCart product card to avoid unsafe bulk changes.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Catalog managers maintaining many products, categories, attributes, prices and SEO fields who need controlled mass actions and undo support.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=104 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Product Manager PRO объединяет массовое управление товарами с аудитом заполнения, SEO и изображений в одном административном интерфейсе.&lt;/p&gt;&lt;p&gt;Он сокращает рутинное редактирование, но сложные структуры OpenCart — опции, recurring, layouts, related products — оставляет штатной карточке, если безопасное массовое изменение невозможно.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Модуль объединяет быстрый менеджер товаров, аудит полноты карточек, SEO-аудит и диагностику изображений. После установки он выключен и не выполняет аудит, cron или изменения товаров до ручного включения статуса и нужных функций с сохранением.&lt;/li&gt;&lt;li&gt;Если на сайте есть таблица product_currency_input_pro, при изменении стандартной цены модуль обновит calculated_store_price. Включайте только если используете этот валютный модуль.&lt;/li&gt;&lt;li&gt;Проверяются главное фото, дополнительные фото из product_image, битые ссылки, дубли, тяжелые изображения, zero-byte файлы, подозрительные пути, WebP/AVIF-кеш.&lt;/li&gt;&lt;li&gt;Модуль ускоряет управление товарами, находит слабые карточки, контролирует изображения, SEO, маржу, категории и атрибуты без тяжелых операций на витрине.&lt;/li&gt;&lt;li&gt;Для стандартного OpenCart используется проверка наличия имени товара или H1 как источника alt. Если есть кастомная таблица product_image_description, модуль попробует читать alt, title или name.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Контент-менеджерам больших каталогов, которым нужны контролируемые массовые действия и возможность отката.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=104 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Popup Banner PRO&lt;/strong&gt; створює незалежні рекламні popup-кампанії для конкретних сторінок, категорій, товарів, пристроїв і часових сценаріїв. Модуль не залежить від Bootstrap Modal теми й не змінює Twig-файли.&lt;/p&gt;&lt;p&gt;Одна кампанія може працювати як банер, image+text, promo code, countdown, exit-intent пропозиція або fullscreen повідомлення. Контент суворо мультимовний: витрина використовує тільки поточний language_id без підстановки тексту іншою мовою.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Таргетинг: головна, категорії, товари, виробники, пошук, акції, інформаційні сторінки, cart і checkout.&lt;/li&gt;&lt;li&gt;Include/exclude категорій із дочірніми й конкретних товарів через autocomplete.&lt;/li&gt;&lt;li&gt;Desktop/Tablet/Mobile з окремими зображеннями та шириною.&lt;/li&gt;&lt;li&gt;7 позицій і 8 design presets.&lt;/li&gt;&lt;li&gt;9 layouts: image only, image+text, image top, background, text only, promo code, countdown, fullscreen.&lt;/li&gt;&lt;li&gt;18 готових рекламних сценаріїв і змінні {STORE_NAME}, {PRODUCT_NAME}, {PRICE}, {SPECIAL_PRICE}, {CATEGORY_NAME}, {DATE}, {YEAR}, {PROMO_CODE}.&lt;/li&gt;&lt;li&gt;Розклад по датах, локальному часу й днях тижня, включно з інтервалом через північ.&lt;/li&gt;&lt;li&gt;Тригери delay, scroll %, scroll px, Desktop Exit Intent, page views і ALL/ANY.&lt;/li&gt;&lt;li&gt;Frequency caps, cooldown після close/click, priority і single/sequential conflict mode.&lt;/li&gt;&lt;li&gt;Countdown до завершення кампанії або окремої дати.&lt;/li&gt;&lt;li&gt;Агреговані impressions, unique session impressions, clicks і closes.&lt;/li&gt;&lt;li&gt;16 вбудованих універсальних візуалів без тексту; текст накладається окремо за мовами.&lt;/li&gt;&lt;li&gt;Promo code вибирається з існуючих OpenCart coupons; модуль не створює й не змінює купон сам.&lt;/li&gt;&lt;li&gt;На mobile немає фіктивної обіцянки «ловити закриття вкладки»: надійного pre-close event браузер не дає, тому використовуються delay/scroll/page-view.&lt;/li&gt;&lt;li&gt;CSS/JS підключаються лише якщо на поточній сторінці є відповідна кампанія; cron не потрібен.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль дозволяє запускати промо без редагування шаблону й показувати різні повідомлення конкретним сегментам каталогу.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам для акцій, безкоштовної доставки, промокодів, подарунків, оголошень, графіка роботи, технічних повідомлень і exit-intent кампаній.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;Стандартна тема / UniShop2 / OpenCart Theme PRO&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=105 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Popup Banner PRO is a multilingual campaign manager for scheduled storefront popups targeted by page, category, product, language, device and customer behavior.&lt;/p&gt;&lt;p&gt;The module separates visual artwork from editable localized text so the same campaign can remain readable in several languages and screen sizes instead of baking copy into a single image.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;18 ready campaign templates: Sale, Free delivery, New arrival, Promo code, Last chance, Announcement, Exit offer, Category promotion, Gift with order, Bundle offer, Price reduced, Help choosing, Weekend offer, Welcome, Store temporarily unavailable, Maintenance, Holiday opening hours and Back in stock.&lt;/li&gt;&lt;li&gt;Added server-side sorting, 30/50/100/250 pagination, name search and status filter to the campaign table; statistics now has server-side sorting and 30/50/100/250 pagination while preserving the date filter.&lt;/li&gt;&lt;li&gt;Reworked the ready-image bank into an even card grid with 8:5 thumbnails, 240x150 preview generation, consistent gaps and a clear selected state.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores running promotions, coupons, exit offers, announcements, maintenance notices and targeted category/product campaigns.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=105 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Popup Banner PRO — менеджер мультиязычных popup-кампаний с таргетингом по страницам, категориям, товарам, языкам, устройствам и поведению посетителя.&lt;/p&gt;&lt;p&gt;Визуал отделён от редактируемого локализованного текста, поэтому одна кампания может корректно работать на нескольких языках и экранах без текста, запечённого в картинку.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;PRODUCT_NAME/PRICE/SPECIAL_PRICE вычисляются только на странице товара и только если такая переменная реально используется; CATEGORY_NAME — только на странице категории. Это не создаёт лишних запросов для обычных статичных popup.&lt;/li&gt;&lt;li&gt;0 отключает соответствующее ограничение. Сравнение идёт по подытогу корзины OpenCart в базовой валюте магазина (%s), без доставки и расширений итогов заказа.&lt;/li&gt;&lt;li&gt;Добавлен встроенный банк из 8 оптимизированных универсальных изображений в image/catalog/popup_banner_pro/bank.&lt;/li&gt;&lt;li&gt;Встроенный банк из 16 ярких универсальных визуалов без встроенного текста: по две цветовые гаммы для скидки, доставки, новинки, подарка, консультации, выходных/графика, технических работ и временно закрытого магазина. Текст подставляется отдельно по языкам и остаётся полностью редактируемым; изображения можно назначить сразу всем устройствам или отдельно ПК/планшету/мобильному.&lt;/li&gt;&lt;li&gt;Popup Banner PRO — лёгкий менеджер всплывающих рекламных кампаний для OpenCart 3.x / ocStore 3.0.x. Модуль показывает разные popup-баннеры по страницам, категориям, конкретным товарам, языкам и устройствам, поддерживает расписание, частоту, задержку, прокрутку, Desktop Exit Intent, Countdown, готовые промокоды OpenCart, приоритеты, статистику и адаптивный дизайн.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с акциями, купонами, exit offer, объявлениями, техническими уведомлениями и точечными промо-кампаниями.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=105 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;PHP 8 Compatibility PRO&lt;/strong&gt; виконує один повний діагностичний прохід по магазину й показує, які проблеми реально впливають на вибрану версію PHP: ядро, модулі, активні та вимкнені OCMOD, storage/modification, бібліотеки, Composer dependencies, PHP extensions і runtime-помилки.&lt;/p&gt;&lt;p&gt;Модуль відокремлює статичну знахідку від реальної несумісності й показує версію PHP, починаючи з якої проблема стає блокером. Закодований ionCube/SourceGuardian модуль не оголошується сумісним лише тому, що на сервері є Loader.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;PHP 7.4 baseline + readiness для PHP 8.1, 8.2, 8.3, 8.4 і 8.5 за один scan.&lt;/li&gt;&lt;li&gt;Окрема оцінка версії ядра від конкретних виправлень локальної збірки.&lt;/li&gt;&lt;li&gt;Аналіз core, extensions, PHP-коду тем, OCMOD, storage/modification, system/library, Composer/vendor і вкладених dependencies.&lt;/li&gt;&lt;li&gt;Перевірка необхідних PHP extensions.&lt;/li&gt;&lt;li&gt;Runtime logs окремо від статичних правил.&lt;/li&gt;&lt;li&gt;Знахідки класифікуються за цільовою версією: blocker/review/advisory.&lt;/li&gt;&lt;li&gt;Режим зміни файлів окремий і OFF за замовчуванням.&lt;/li&gt;&lt;li&gt;Безпечні fixes застосовуються тільки вручну з перевіркою SHA-256 вихідного файла.&lt;/li&gt;&lt;li&gt;PHP syntax перевіряється перед записом; при помилці виконується rollback.&lt;/li&gt;&lt;li&gt;Vendor, config.php і generated storage/modification не переписуються напряму.&lt;/li&gt;&lt;li&gt;Після зміни модуль вимагає повторну діагностику, а не приховує знахідку автоматично.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає розділити «цей рядок схожий на deprecated» і «цей файл реально зламає вибрану PHP».&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Розробникам і власникам OpenCart/ocStore 3.x перед зміною PHP або аудитом старого набору модулів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=106 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;PHP 8 Compatibility PRO audits real source-code compatibility against PHP 7.4–8.5 profiles and separates confirmed blockers from items that only require review.&lt;/p&gt;&lt;p&gt;Static scanning is only one layer. The module also treats Composer constraints, encoded ionCube/SourceGuardian components, OCMOD integrity and staging runtime tests as separate evidence so a text match is not automatically called a fatal incompatibility.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;7. Test admin, storefront, authentication, catalogue, search, cart, checkout, AJAX/API, cron, email, images, import/export, feeds, payments, shipping and key extensions.&lt;/li&gt;&lt;li&gt;When the static report has no blockers, switch staging to the target PHP. If needed, restart PHP-FPM/clear OPcache through the hosting panel and test admin, storefront, checkout, AJAX/API, cron, email, images, import/export, payments, shipping and key extensions.&lt;/li&gt;&lt;li&gt;When a third-party module is protected with ionCube or SourceGuardian, its PHP source is not available to static analysis. A compatible Loader only means the protection format can be loaded; it does NOT prove that the encoded module itself supports PHP 7.4 baseline + PHP 8.1–8.5. Before migration, obtain vendor confirmation or a build for the target PHP version and perform a runtime test on staging. Until confirmed, the compatibility matrix remains in Review state.&lt;/li&gt;&lt;li&gt;This is a separate modification-integrity check, not PHP compatibility. A skipped operation means the OCMOD did not find its search fragment during the latest modification refresh. Some OCMODs intentionally contain optional searches, so a skip is a review signal rather than automatic proof that the modification is broken.&lt;/li&gt;&lt;li&gt;Static matches in Composer vendor packages whose runtime activity is unknown are classified as Review rather than confirmed blockers. Vendor tests, examples, documentation, fixtures and benchmarks are excluded from production source scanning; Composer PHP constraints are evaluated separately.&lt;/li&gt;&lt;li&gt;Static source analysis is not possible. A compatible ionCube Loader does not by itself prove module compatibility. Review the encoded-components table, obtain a build for the target PHP version and run a staging runtime test.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Developers and store owners preparing a PHP upgrade who need a structured compatibility matrix before changing production PHP.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=106 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;PHP 8 Compatibility PRO проверяет реальную совместимость исходного кода по профилям PHP 7.4–8.5 и отделяет подтверждённые блокеры от пунктов, которые требуют проверки.&lt;/p&gt;&lt;p&gt;Статический поиск — только один слой. Composer constraints, закрытые ionCube/SourceGuardian компоненты, целостность OCMOD и runtime-тест staging рассматриваются отдельно, чтобы обычное совпадение текста не считалось фатальной ошибкой.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;7. Проверьте админку, витрину, авторизацию, каталог, поиск, корзину, checkout, AJAX/API, cron, email, изображения, импорт/экспорт, feeds, оплату, доставку и ключевые расширения.&lt;/li&gt;&lt;li&gt;Когда статический отчёт не содержит блокеров, переключите staging на целевую PHP. При необходимости перезапустите PHP-FPM/сбросьте OPcache средствами хостинга и протестируйте админку, витрину, checkout, AJAX/API, cron, email, изображения, импорт/экспорт, оплату, доставку и ключевые расширения.&lt;/li&gt;&lt;li&gt;Если сторонний модуль закодирован ionCube или SourceGuardian, его исходный PHP-код недоступен статическому анализу. Наличие совместимого загрузчика означает только возможность загрузить формат защиты и НЕ подтверждает совместимость самого модуля с PHP 7.4 baseline + PHP 8.1–8.5. Перед переходом получите у разработчика модуля подтверждение или сборку для целевой PHP и обязательно выполните тест на тестовой копии с целевой PHP. Пока это не подтверждено, матрица показывает статус «Нужна проверка».&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Разработчикам и владельцам магазинов перед обновлением PHP, которым нужна понятная матрица совместимости до переключения production.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=106 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Option Price Equal Prefix PRO&lt;/strong&gt; додає до значень опцій третю логіку ціни: крім стандартних + і − з’являється префікс &lt;strong&gt;=&lt;/strong&gt;, який замінює базову ціну товару конкретною ціною варіанта.&lt;/p&gt;&lt;p&gt;Наприклад, товар коштує 80, розмір XL має =100, додаткова упаковка +10 — підсумкова ціна буде 110. Після абсолютної ціни інші вибрані +/− опції продовжують застосовуватися вже до нової бази.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Новий price prefix = у стандартній формі значення опції.&lt;/li&gt;&lt;li&gt;+ додає, − віднімає, = замінює базову ціну.&lt;/li&gt;&lt;li&gt;Після = інші +/− застосовуються до нової базової суми.&lt;/li&gt;&lt;li&gt;Якщо одночасно вибрано кілька =, остання оброблена абсолютна ціна стає базою.&lt;/li&gt;&lt;li&gt;Для взаємовиключних варіантів рекомендується використовувати = в одному select/radio/image наборі.&lt;/li&gt;&lt;li&gt;Працює через стандартний system/library/cart/cart.php і форму товару.&lt;/li&gt;&lt;li&gt;Не створює власних таблиць, cron, Events або фонових задач.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Зручно для розміру або комплектації, де кожний варіант має власну повну ціну, а не лише націнку від базового товару.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із варіантами товару, де реальна ціна кожного розміру/комплектації відома як кінцева сума.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=107 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Option Price Equal Prefix PRO adds an \'=\' price prefix for OpenCart option values, allowing a selected option value to replace the product\'s base price instead of only adding or subtracting from it.&lt;/p&gt;&lt;p&gt;After the absolute \'=\' price becomes the new base, normal \'+\' and \'-\' option adjustments can still be applied. This is useful for mutually exclusive variants whose final prices are known in advance.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Adds \'=\' as an additional option price prefix alongside standard \'+\' and \'-\'.&lt;/li&gt;&lt;li&gt;The selected \'=\' option value replaces the product base price.&lt;/li&gt;&lt;li&gt;After replacement, other selected \'+\'/\'-\' option adjustments continue to work normally.&lt;/li&gt;&lt;li&gt;If several \'=\' values are selected, the last processed absolute value becomes the base; use \'=\' in one mutually exclusive option group for predictable behavior.&lt;/li&gt;&lt;li&gt;Stored option data remains in OpenCart and is not deleted if the modifier is removed.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores with sizes, kits or variants where each selectable option represents a complete final base price.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=107 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Option Price Equal Prefix PRO добавляет префикс цены \'=\' для значений опций OpenCart, позволяя выбранной опции заменить базовую цену товара вместо обычного прибавления или вычитания.&lt;/p&gt;&lt;p&gt;После выбора абсолютной \'=\' цены она становится новой базой, а стандартные \'+\' и \'-\' корректировки других опций продолжают применяться. Это удобно для взаимоисключающих вариантов с известной конечной ценой.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Добавляет \'=\' как дополнительный префикс цены опции рядом со стандартными \'+\' и \'-\'.&lt;/li&gt;&lt;li&gt;Выбранное значение с \'=\' заменяет базовую цену товара.&lt;/li&gt;&lt;li&gt;После замены остальные выбранные \'+\'/\'-\' опции продолжают работать относительно новой базы.&lt;/li&gt;&lt;li&gt;Если выбрано несколько \'=\' значений, базой становится последнее обработанное; для предсказуемости используйте \'=\' в одной взаимоисключающей группе.&lt;/li&gt;&lt;li&gt;Данные опций остаются в OpenCart и не удаляются при снятии модификатора.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с размерами, комплектациями и вариантами, где значение опции задаёт полноценную базовую цену.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=107 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Option Manager PRO&lt;/strong&gt; керує саме опціями OpenCart — кольором, розміром, довжиною, комплектацією, напругою або іншим вибором покупця, який може впливати на ціну, залишок, вагу й кошик.&lt;/p&gt;&lt;p&gt;Модуль не плутає опції з атрибутами. Він дає повноцінний редактор, шаблони та контрольоване масове застосування, але вставка шаблону в картку товару не підміняє стандартну кнопку збереження OpenCart.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Редактор опцій і значень.&lt;/li&gt;&lt;li&gt;Drag &amp; drop порядку опцій/значень.&lt;/li&gt;&lt;li&gt;Шаблони з required, quantity, subtract, price, points, weight і sort order.&lt;/li&gt;&lt;li&gt;Масове застосування шаблону до вибраних товарів із preview.&lt;/li&gt;&lt;li&gt;Режими: додати відсутні, замінити всі опції або оновити збіги.&lt;/li&gt;&lt;li&gt;Пошук точних і схожих дублів опцій.&lt;/li&gt;&lt;li&gt;Пошук дублів значень усередині батьківської опції.&lt;/li&gt;&lt;li&gt;Безпечне merge опцій і значень із preview.&lt;/li&gt;&lt;li&gt;Масові дії по вибраних опціях.&lt;/li&gt;&lt;li&gt;CSV export/import значень разом із зображеннями.&lt;/li&gt;&lt;li&gt;Стандартний OpenCart Image Manager для image-значень.&lt;/li&gt;&lt;li&gt;Вставка шаблону в форму товару без окремого AJAX-save.&lt;/li&gt;&lt;li&gt;Діагностика й довідка; модуль після установки OFF.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Шаблон економить час, коли однакові розміри/кольори/комплектації повторюються у десятках товарів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із великою кількістю варіантів товарів і повторюваних наборів опцій.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=108 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Option Manager PRO centralizes OpenCart option templates, names, values, ordering, duplicate control, bulk actions and CSV exchange.&lt;/p&gt;&lt;p&gt;Options are customer-selectable variants and are not the same as informational attributes. The module is designed for repeated colors, sizes, lengths, voltages, connector types and similar choices that may affect price, stock or weight.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Option Manager PRO is a separate module for managing OpenCart product options: templates, option names, values, duplicates, sorting, mass actions, CSV export/import and a safe product-card helper. It is useful when products have repeated selectable variants such as color, size, length, voltage, package or connector type.&lt;/li&gt;&lt;li&gt;Module benefits: less manual product editing, unified value order, reusable option templates, duplicate control, mass application and fewer manager errors.&lt;/li&gt;&lt;li&gt;Unlike simple bulk option update tools, this module combines templates, values, duplicates, mass-action preview and safe application to products.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Catalogs with many reusable product-option sets where manual option editing creates duplication and manager errors.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=108 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Option Manager PRO централизует шаблоны опций OpenCart, названия, значения, сортировку, контроль дублей, массовые действия и CSV-обмен.&lt;/p&gt;&lt;p&gt;Опции — это выбираемые покупателем варианты, а не информационные атрибуты. Модуль рассчитан на повторяющиеся цвета, размеры, длины, напряжения, разъёмы и комплектации, которые могут влиять на цену, остаток или вес.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Option Manager PRO это отдельный модуль для управления опциями товаров OpenCart: шаблоны, названия опций, значения, дубли, сортировка, массовые действия, CSV экспорт/импорт и безопасный помощник в карточке товара. Он полезен, когда у товаров повторяются выбираемые варианты: цвет, размер, длина, напряжение, комплектация или тип разъема.&lt;/li&gt;&lt;li&gt;Option Manager PRO управляет именно опциями OpenCart/ocStore, а не атрибутами. Опции используются там, где покупатель выбирает вариант товара: цвет, размер, длина, комплектация, напряжение, тип разъема и другие варианты, которые могут влиять на цену, остаток, вес и корзину.&lt;/li&gt;&lt;li&gt;Поле изображения значения опции переведено на стандартный OpenCart Image Manager с предпросмотром и очисткой.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Каталогам с большим количеством повторяющихся наборов опций, где ручное редактирование создаёт дубли и ошибки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=108 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;New Year Decor PRO&lt;/strong&gt; додає святкове оформлення без зміни ядра: інтерактивну гірлянду, класичну світлову гірлянду, п’ять графічних варіантів і окремий Canvas Snow.&lt;/p&gt;&lt;p&gt;Гірлянда й сніг працюють незалежно. Можна задати щорічний період показу без прив’язки до конкретного року, показувати ефекти лише на головній або на всьому сайті й окремо керувати desktop/mobile.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Інтерактивна гірлянда з іграшками.&lt;/li&gt;&lt;li&gt;Класична світлова та 5 графічних WebP-гірлянд.&lt;/li&gt;&lt;li&gt;Графічні tiles використовують repeat-x без штучного mirror.&lt;/li&gt;&lt;li&gt;Canvas Snow: круглий сніг, класичні сніжинки, зірочки або власний прозорий WebP.&lt;/li&gt;&lt;li&gt;Налаштування particles, size, speed, opacity, wind, color, twinkle, fade і області падіння.&lt;/li&gt;&lt;li&gt;Щорічний date range, all pages/home only, окремі desktop/mobile flags.&lt;/li&gt;&lt;li&gt;Height, top offset, z-index і automatic/manual content spacer.&lt;/li&gt;&lt;li&gt;Звуки вимкнені за замовчуванням; доступні окремі sound zones/keyboard сценарії.&lt;/li&gt;&lt;li&gt;Не змінює товари, категорії, cart, checkout або SEO.&lt;/li&gt;&lt;li&gt;Немає cron; при OFF assets і ефекти не завантажуються.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Дозволяє оформити магазин на сезон без правок шаблону й після свят просто вимкнути модуль або дочекатися завершення періоду.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які хочуть сезонне новорічне оформлення без заміни теми та ручного редагування Twig/CSS.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=109 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;New Year Decor PRO adds lightweight seasonal storefront effects such as garlands and Canvas snow without changing products, checkout, prices or SEO data.&lt;/p&gt;&lt;p&gt;Effects can be enabled independently, and the module stays inactive on the storefront while its status is OFF. Local WebP assets and Canvas rendering keep decorative elements separate from business logic.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;New Year Decor adds seasonal garland effects and lightweight Canvas Snow to the storefront. The effects can run independently or together. The module does not change products, cart, checkout, images, image cache, SEO data, prices, currencies or orders.&lt;/li&gt;&lt;li&gt;Interactive ornaments and the classic light garland are retained. Graphical variants use one local seamless WebP ping-pong tile, so joins stay clean on wide screens without creating multiple image elements. The two Party presets contain no fir tree and can be used for birthdays, promotions and other celebrations year-round.&lt;/li&gt;&lt;li&gt;Used only for Custom WebP snowflake. For new settings select a transparent WebP through the standard OpenCart image manager. Legacy PNG paths remain supported only for compatibility with previously saved settings. The relative image path is stored; external URLs are rejected.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that want seasonal New Year or general celebration decoration without replacing the theme or modifying catalog data.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=109 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;New Year Decor PRO добавляет лёгкие сезонные эффекты витрины — гирлянды и Canvas Snow — не меняя товары, checkout, цены и SEO-данные.&lt;/p&gt;&lt;p&gt;Эффекты можно включать отдельно, а при OFF модуль не подключает витринные CSS/JS/HTML. Локальные WebP и Canvas отделяют декор от бизнес-логики магазина.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;New Year Decor добавляет сезонную гирлянду и легкий Canvas Snow на витрину сайта. Эффекты могут работать отдельно или вместе. Модуль не меняет товары, корзину, оформление заказа, изображения, кеш изображений, SEO-данные, цены, валюты или заказы.&lt;/li&gt;&lt;li&gt;Пока статус выключен, модуль не подключает CSS, JS и HTML на витрине. Без активной лицензии статус принудительно остается выключенным.&lt;/li&gt;&lt;li&gt;Интерактивные игрушки и классическая световая гирлянда сохранены. Графические варианты используют один локальный бесшовный WebP ping-pong тайл, поэтому стык остаётся аккуратным на широких экранах без создания множества изображений в DOM. Два варианта «Праздник» не содержат ёлки и подходят для дней рождения, акций и других праздников в течение всего года.&lt;/li&gt;&lt;li&gt;Используется только для режима «Своя WebP-снежинка». Для новых настроек выбирайте прозрачный WebP через стандартный менеджер изображений OpenCart. Старый PNG-путь сохраняет поддержку только для совместимости с ранее сохранёнными настройками. Хранится относительный путь; внешние URL запрещены.&lt;/li&gt;&lt;li&gt;Круглый снег, классические снежинки и звёздочки рисуются непосредственно Canvas и не используют отдельные файлы изображений. Режим своего изображения также использует Canvas и загружает только один локальный WebP-файл.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которым нужно сезонное новогоднее или праздничное оформление без замены темы и изменения каталога.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=109 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Module Preflight PRO&lt;/strong&gt; — portable-програма для Windows, яка перевіряє ZIP/.ocmod.zip модуль OpenCart/ocStore &lt;strong&gt;до&lt;/strong&gt; його встановлення на сайт і не змінює вихідний архів.&lt;/p&gt;&lt;p&gt;Програма працює окремо від магазину: її можна розпакувати на диск або флешку, запустити START_Module_Preflight_PRO.cmd, перетягнути модуль у вікно й отримати структурований звіт із шляхом файла, рядком, критерієм і поясненням.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Повністю portable: нічого не встановлює в Program Files або AppData.&lt;/li&gt;&lt;li&gt;Drag-and-drop ZIP/.ocmod.zip.&lt;/li&gt;&lt;li&gt;SHA-256 перевірюваного архіву.&lt;/li&gt;&lt;li&gt;Профілі CodeCart PRO Strict, OpenCartForum, Standard, PHP Compatibility, Security Audit, Quick і Custom.&lt;/li&gt;&lt;li&gt;Перевірка ZIP path traversal, лімітів розміру/кількості файлів і аномального compression ratio.&lt;/li&gt;&lt;li&gt;OCMOD structure, install.xml, кодування UTF-8/BOM та базова структура пакета.&lt;/li&gt;&lt;li&gt;PHP compatibility для 7.4, 8.1, 8.2, 8.3, 8.4 і 8.5.&lt;/li&gt;&lt;li&gt;Static rules + реальний php -l через portable PHP engines.&lt;/li&gt;&lt;li&gt;Офіційні portable PHP можна завантажити з GUI; після цього папку engines/php переноситься разом із програмою.&lt;/li&gt;&lt;li&gt;Security Audit: malware/backdoor, obfuscation, network code, admin/auth, spam/persistence, destructive actions, binaries, SQL та Microsoft Defender за наявності.&lt;/li&gt;&lt;li&gt;Таблиця Errors / Warnings / Info з фільтрами й прогресом.&lt;/li&gt;&lt;li&gt;Вихідний модуль не встановлюється в OpenCart і не модифікується під час перевірки.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Preflight дозволяє відсіяти битий install.xml, небезпечну конструкцію або очевидну PHP-несумісність ще до контакту архіву з робочим сайтом.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Розробникам, marketplace-продавцям і адміністраторам Windows, які регулярно перевіряють сторонні або власні модулі OpenCart/ocStore перед установкою.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;Windows 10 / 11&lt;/li&gt;&lt;li&gt;Перевіряє модулі OpenCart/ocStore 3.x&lt;/li&gt;&lt;li&gt;Цільові PHP 7.4 / 8.1 / 8.2 / 8.3 / 8.4 / 8.5&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=110 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Module Preflight PRO is a portable Windows utility for static security and compatibility auditing of OpenCart/ocStore extension ZIP archives before installation.&lt;/p&gt;&lt;p&gt;The audited extension is not executed: the ZIP is opened read-only, SHA-256 is checked before/after, static rules inspect risky code patterns, and portable PHP binaries can confirm syntax compatibility with selected PHP targets.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Read-only audit of an extension ZIP; the module code is not executed.&lt;/li&gt;&lt;li&gt;SHA-256 of the original archive is checked before and after inspection.&lt;/li&gt;&lt;li&gt;Static security rules look for direct/indirect dangerous execution, web-shell patterns, tainted input flows, remote include and persistence/destructive operations.&lt;/li&gt;&lt;li&gt;Dynamic SQL identifiers are classified by taint/whitelist evidence rather than flagged only because they are dynamic.&lt;/li&gt;&lt;li&gt;Portable PHP lint can test syntax against PHP 7.4 and PHP 8.1–8.5 targets.&lt;/li&gt;&lt;li&gt;Third-party antivirus registered in Windows Security Center is reported informationally; the utility does not try to manage it.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Developers and store owners who want to inspect a module archive before uploading it to a live OpenCart/ocStore installation.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;Windows portable utility&lt;/li&gt;&lt;li&gt;Audits OpenCart/ocStore 3.x extension archives&lt;/li&gt;&lt;li&gt;PHP code targets 7.4 and 8.1–8.5&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=110 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Module Preflight PRO — portable Windows-утилита для статического security/compatibility аудита ZIP-архивов OpenCart/ocStore до установки.&lt;/p&gt;&lt;p&gt;Проверяемое расширение не выполняется: ZIP открывается read-only, SHA-256 сравнивается до/после, статические правила ищут опасные конструкции, а portable PHP подтверждает синтаксис для выбранных версий PHP.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Read-only проверка ZIP: код модуля не выполняется.&lt;/li&gt;&lt;li&gt;SHA-256 исходного архива сравнивается до и после проверки.&lt;/li&gt;&lt;li&gt;Статический security-аудит ищет опасные вызовы, web-shell patterns, tainted input flows, remote include и persistence/destructive operations.&lt;/li&gt;&lt;li&gt;Dynamic SQL identifier оценивается по taint/whitelist, а не считается ошибкой только из-за динамичности.&lt;/li&gt;&lt;li&gt;Portable PHP lint проверяет синтаксис по целям PHP 7.4 и PHP 8.1–8.5.&lt;/li&gt;&lt;li&gt;Сторонний антивирус Windows Security Center показывается информационно; утилита не пытается им управлять.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Разработчикам и владельцам магазинов, которые хотят проверить архив модуля до загрузки на рабочий OpenCart/ocStore.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;Windows portable utility&lt;/li&gt;&lt;li&gt;Audits OpenCart/ocStore 3.x extension archives&lt;/li&gt;&lt;li&gt;PHP code targets 7.4 and 8.1–8.5&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=110 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Merchant Feed Simple XML PRO&lt;/strong&gt; формує готовий XML-фід товарів OpenCart/ocStore для Google Merchant Center через окремий feed-маршрут. Модуль орієнтований на коректні комерційні дані: ціну, акцію, наявність, бренд, ідентифікатори, категорії та зображення.&lt;/p&gt;&lt;p&gt;Головна задача — не просто віддати XML, а не передавати Google вигадані або технічно неправильні значення. Тому GTIN перевіряється за форматом і контрольною цифрою, MPN та бренд не створюються штучно, а Google Product Category і product_type формуються з реальних даних каталогу.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;XML-фід Google Merchant за стандартним маршрутом OpenCart.&lt;/li&gt;&lt;li&gt;Опис товару очищається від script/style/form/iframe та інших небезпечних або службових фрагментів і обмежується вимогою Google до 5000 символів.&lt;/li&gt;&lt;li&gt;Акційна ціна береться з активної product_special, валюта фіда синхронізується з основною валютою магазину.&lt;/li&gt;&lt;li&gt;GTIN передається тільки при допустимій довжині та правильній контрольній цифрі.&lt;/li&gt;&lt;li&gt;MPN, GTIN, UPC/JAN/ISBN не підставляються штучно, якщо магазин не має реальних ідентифікаторів виробника.&lt;/li&gt;&lt;li&gt;Строгий автоматичний identifier_exists=no використовується тільки коли немає GTIN, MPN і бренду.&lt;/li&gt;&lt;li&gt;Google Product Category ID береться з категорії з підтримкою успадкування від батьківської категорії.&lt;/li&gt;&lt;li&gt;product_type формується з внутрішнього шляху категорій магазину.&lt;/li&gt;&lt;li&gt;Основне зображення можна віддавати в оригінальному форматі або WebP; AVIF не передається в Merchant image_link/additional_image_link.&lt;/li&gt;&lt;li&gt;Діагностика показує товари без фото, бренду, Google Category, product_type, з надто довгим описом, HTML/JS-фрагментами або проблемами головної категорії.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль скорочує ручну підготовку фіда та зменшує кількість типових відхилень, які виникають через некоректні ідентифікатори, описи й категорії.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які продають через Google Shopping / Merchant Center і хочуть мати керований XML-фід без ручного експорту.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=111 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Merchant Feed Simple XML PRO generates a controlled Google Merchant Center XML feed from real OpenCart catalog data: prices, availability, categories, identifiers and images.&lt;/p&gt;&lt;p&gt;The goal is not merely to output XML, but to avoid invented identifiers and technically invalid product data that can cause Merchant diagnostics or rejections.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The module generates a Google Merchant XML feed for OpenCart/ocStore 3.x, supports Google Product Category ID from categories, product_type from the category path, and isolated Merchant image logic without changing storefront image behavior.&lt;/li&gt;&lt;li&gt;Google currently accepts JPEG, WebP, PNG, GIF, BMP and TIFF. AVIF isn\'t accepted for Merchant image links. Source images should be at least 500×500 px for the requirement taking effect on 31 January 2027; the module never upscales smaller originals.&lt;/li&gt;&lt;li&gt;Click a diagnostic card to open a modal with the product list. The modal shows feed ID, product code, name, brand, quantity, categories, Google Product Category ID and quick links.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores using Google Merchant Center / Shopping that need a predictable feed and catalog diagnostics.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=111 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Merchant Feed Simple XML PRO формирует управляемый XML-фид Google Merchant Center из реальных данных OpenCart: цен, наличия, категорий, идентификаторов и изображений.&lt;/p&gt;&lt;p&gt;Задача модуля — не просто выгрузить XML, а не передавать Google выдуманные идентификаторы и технически некорректные данные, которые приводят к ошибкам Merchant Center.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Модуль формирует XML-фид Google Merchant для OpenCart/ocStore 3.x, поддерживает ID категории Google из категории магазина, тип товара product_type из пути категории и отдельную безопасную логику изображений для Google Merchant без влияния на витрину.&lt;/li&gt;&lt;li&gt;AVIF исключён из Merchant-фида: Google его не принимает для image_link/additional_image_link. Старое значение avif мигрирует в безопасный режим оригинального изображения.&lt;/li&gt;&lt;li&gt;Google сейчас принимает JPEG, WebP, PNG, GIF, BMP и TIFF. AVIF для изображений Merchant не принимается. Исходные фото желательно иметь не менее 500×500 px с учётом требования, которое вступает в силу 31 января 2027 года; модуль не увеличивает маленькие оригиналы искусственно.&lt;/li&gt;&lt;li&gt;в окне диагностики показываются ID фида, код товара/model, SKU, название, бренд, количество, категории, Google Product Category ID и быстрые ссылки для открытия товара в админке и на витрине;&lt;/li&gt;&lt;li&gt;Самый безопасный режим по умолчанию — оригинальные изображения каталога: URL и встроенные метаданные остаются стабильными. WebP доступен отдельно. AVIF в Google Merchant не передаётся.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которые используют Google Merchant Center / Shopping и хотят контролируемый фид с диагностикой каталога.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=111 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Merchant Schema PRO&lt;/strong&gt; керує комерційною JSON-LD розміткою магазину: Product, Offer, OnlineStore, поверненнями, доставкою, рейтингами, варіантами товарів і Google Product Category.&lt;/p&gt;&lt;p&gt;Модуль створений для ситуацій, коли тема вже частково генерує Schema і важливо не отримати два конфліктні Product-блоки. Адміністратор може повністю замінити Product підтримуваної теми, залишити його темі та додати тільки глобальні Merchant-полі або вимкнути JSON-LD модуля й використовувати лише інструменти даних.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;П’ять профілів виводу: повна заміна Product, повна Schema без вимкнення Product теми, доповнення без другого Product, тільки дані без JSON-LD та ручний профіль.&lt;/li&gt;&lt;li&gt;Product / Offer із ціною, акцією, availability, condition, SKU, MPN, Brand і перевіреним GTIN.&lt;/li&gt;&lt;li&gt;OnlineStore / Organization: legalName, контакти, VAT/tax ID, адреса, ContactPoint, sameAs і зображення.&lt;/li&gt;&lt;li&gt;MerchantReturnPolicy із підтримуваними сценаріями плати за повернення.&lt;/li&gt;&lt;li&gt;Google ShippingService / ShippingConditions: кілька країн, строки, cutoff, вартість, вага, кількість товарів і сезонні винятки.&lt;/li&gt;&lt;li&gt;ProductGroup для реальних варіантів на окремих URL з productGroupID і variesBy.&lt;/li&gt;&lt;li&gt;Product.hasCertification для підтримуваних EPREL/CO2 сценаріїв.&lt;/li&gt;&lt;li&gt;Google Product Category ID у категоріях з успадкуванням від батьківської категорії.&lt;/li&gt;&lt;li&gt;AggregateRating і останні схвалені відгуки.&lt;/li&gt;&lt;li&gt;Опціональна інтеграція Product Unit PRO через UnitPriceSpecification.&lt;/li&gt;&lt;li&gt;Безпечне масове заповнення тільки порожніх SKU, MPN і виробника з preview, batch і журналом змін.&lt;/li&gt;&lt;li&gt;Діагностика показує фактичний Product JSON-LD теми, OCMOD-міст, активний профіль і можливі дублікати.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль дає контроль над Merchant structured data без грубого переписування фінального HTML сторінки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;SEO-фахівцям, розробникам та магазинам, які використовують Google rich results / Merchant data і хочуть керувати структурованою розміткою централізовано.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=112 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Merchant Schema PRO manages commerce-focused JSON-LD for OpenCart: Product/Offer, store identity, returns, shipping, ratings, product variants and Google Product Category data.&lt;/p&gt;&lt;p&gt;It is designed for stores where a theme or SEO extension may already output Schema. The module provides profiles that help avoid a second conflicting Product block and add only the merchant data that is actually missing.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Depending on profile: complete Product, Offer or UnitPriceSpecification, OnlineStore, price/currency, availability, SKU, MPN, eligible GTIN, Brand/Manufacturer, images, categories, reviews/rating, returns and shipping; or only safe global merchant policies; or no storefront JSON-LD while Google Product Category data tools remain available.&lt;/li&gt;&lt;li&gt;The module emits a complete Product/Offer but does not suppress the theme Product. Use this for a clean/standalone store that has no native Product JSON-LD. If needed, enable page-level schema and only the missing Compatibility / Fallback options (BreadcrumbList or social meta). If a native Product exists, this profile creates a duplicate.&lt;/li&gt;&lt;li&gt;Open Graph is a set of meta tags used for rich link previews in Facebook, LinkedIn, messengers and other services. It is not Product JSON-LD. Enable the fallback only when the theme/SEO module does not already output og:title, og:description, og:url, og:image and og:site_name.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;SEO specialists, developers and stores that rely on Google structured data and Merchant rich results.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=112 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Merchant Schema PRO управляет коммерческой JSON-LD разметкой OpenCart: Product/Offer, данными магазина, возвратами, доставкой, рейтингами, вариантами товара и Google Product Category.&lt;/p&gt;&lt;p&gt;Модуль рассчитан на магазины, где тема или SEO-расширение уже может выводить Schema. Профили позволяют не создавать второй конфликтующий Product и добавлять только недостающие Merchant-данные.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;В зависимости от выбранного профиля: полный Product, Offer или UnitPriceSpecification, OnlineStore, цена и активная валюта, наличие, SKU, MPN, допустимый GTIN, Brand/Manufacturer, изображения, категории, отзывы/рейтинг, возвраты и доставка; либо только безопасные глобальные Merchant-политики; либо вообще без JSON-LD с сохранением поля Google Product Category и инструментов данных.&lt;/li&gt;&lt;li&gt;5. Ручной профиль. Можно отдельно включать Product, Offer, OnlineStore, description, изображения, model, SKU, MPN и Brand. Отдельные существующие настройки управляют GTIN, Google Category, отзывами, возвратами, доставкой и UnitPriceSpecification. Отключение штатного Product также настраивается отдельно. Диагностика показывает потенциальный дубль, если одновременно активны два Product-источника.&lt;/li&gt;&lt;li&gt;Интеграция опциональная и по умолчанию OFF. Когда Product Unit PRO включён для товара и единица поддерживается Google, Merchant Schema PRO формирует UnitPriceSpecification с referenceQuantity. Поддерживаются: шт.=ct, м/пог.м=m, л=l, мл=ml, кг=kg, г=g, м²=sqm, м³=cbm. Упаковочные и собственные единицы пропускаются, а не угадываются. Product Unit PRO остаётся самостоятельным модулем; порядок установки не имеет значения.&lt;/li&gt;&lt;li&gt;BreadcrumbList — структурированный путь страницы «Главная → Категория → Товар». Open Graph — meta-теги для превью ссылки в Facebook, LinkedIn и мессенджерах. X/Twitter Card — аналогичные meta-теги для X (Twitter). Это не Product JSON-LD; fallback включайте только если тема или другой SEO-модуль этого не формирует.&lt;/li&gt;&lt;li&gt;В Product Unit PRO цена — это цена одной выбранной единицы. Поэтому schema передаёт referenceQuantity = 1 единица и базовую меру = 1 единица. Шаг количества, например 0,1 кг, является только шагом заказа и не подставляется ошибочно как физический размер товара.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;SEO-специалистам, разработчикам и магазинам, использующим Google structured data и Merchant rich results.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=112 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Link Attributes PRO&lt;/strong&gt; додає керування семантикою посилань безпосередньо в Summernote та допомагає привести внутрішні, зовнішні, рекламні, партнерські й користувацькі посилання до єдиної політики.&lt;/p&gt;&lt;p&gt;Модуль не вигадує неіснуючий rel=dofollow. Звичайний Follow залишається посиланням без nofollow/sponsored/ugc, партнерський тип редактора за замовчуванням перетворюється на rel=sponsored, а target=_blank окремо може отримувати noopener/noreferrer.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Типи Auto, Follow, Nofollow, Sponsored, UGC та Affiliate.&lt;/li&gt;&lt;li&gt;Окремі правила для внутрішніх і зовнішніх URL.&lt;/li&gt;&lt;li&gt;Доменні винятки з пріоритетом зверху вниз.&lt;/li&gt;&lt;li&gt;Опціональний глобальний nofollow для зовнішніх посилань із можливістю доменних винятків.&lt;/li&gt;&lt;li&gt;noopener/noreferrer для target=_blank керуються окремо.&lt;/li&gt;&lt;li&gt;Тип посилання доступний у діалозі Insert Link і швидкому popover Summernote.&lt;/li&gt;&lt;li&gt;Normalize on Save застосовує правила перед стандартним збереженням OpenCart, не замінюючи форму AJAX-записом.&lt;/li&gt;&lt;li&gt;Аудит збережених описів показує сторінку, мову, URL, anchor, тип, фактичний rel, очікуваний rel і статус відповідності.&lt;/li&gt;&lt;li&gt;Фільтри за rel, семантичним типом, internal/external, розділом, мовою та відповідністю.&lt;/li&gt;&lt;li&gt;Прямі дії для відкриття сторінки в адмінці й перевірки зовнішнього URL.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає уникати хаотичних rel-атрибутів у контенті, особливо коли різні менеджери редагують статті й товари.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Контент-менеджерам, SEO-фахівцям і магазинам із великою кількістю редакційних, партнерських або UGC-посилань.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=113 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Link Attributes PRO manages link semantics in Summernote and helps keep internal, external, sponsored, affiliate and user-generated links under one consistent policy.&lt;/p&gt;&lt;p&gt;The module does not invent a non-standard rel=dofollow value. A normal followed link stays without nofollow/sponsored/ugc, while sponsored, UGC and security-related attributes are applied only when the selected rule requires them.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Filters are available for actual rel (Follow, Nofollow, Sponsored, Sponsored+Nofollow, UGC, UGC+Nofollow), editor semantic type (Auto/Follow/Nofollow/Sponsored/UGC/Affiliate), internal/external scope, content section, language prefix, compliance status and free-text search by URL, host, page name, rel or anchor text. Audit table headers are sortable, page size can be 25/50/100/250, and pagination includes first/previous/next/last navigation.&lt;/li&gt;&lt;li&gt;Scans saved HTML descriptions of supported entities and shows which pages contain each link. Filters cover actual rel, editor link type, internal/external scope, section, language prefix and rule compliance; table headers are sortable and results are paginated. Theme/header/footer links and arbitrary HTML from third-party modules are not included.&lt;/li&gt;&lt;li&gt;The content audit covers supported editable description fields. It does not claim to scan theme templates, header/footer markup or arbitrary HTML generated by unrelated third-party modules. Link Checker PRO remains the separate tool for site-wide HTTP status/broken-link crawling.&lt;/li&gt;&lt;li&gt;Uninstall removes module settings and its audit table. It does not remove rel attributes already saved in product/category/article content. Removing saved link attributes automatically during uninstall would alter business content, so the module deliberately leaves content unchanged.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Content teams and SEO specialists working with many editorial, affiliate or user-generated links.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=113 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Link Attributes PRO управляет семантикой ссылок в Summernote и помогает привести внутренние, внешние, рекламные, партнёрские и пользовательские ссылки к единой политике.&lt;/p&gt;&lt;p&gt;Модуль не создаёт несуществующий rel=dofollow: обычная Follow-ссылка остаётся без nofollow/sponsored/ugc, а нужные rel-атрибуты добавляются только по выбранному правилу.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Link Attributes PRO централизованно управляет SEO-атрибутами ссылок в редактируемом контенте без постоянного перехвата HTML на витрине.&lt;/li&gt;&lt;li&gt;Сканирует сохранённые HTML-описания поддерживаемых сущностей и показывает, на каких страницах находятся ссылки. Есть фильтры по фактическому rel, типу ссылки, внутренним/внешним URL, разделу, языковому префиксу и соответствию правилам, сортировка по заголовкам таблицы и постраничный вывод. Тема, шапка, подвал и произвольный HTML сторонних модулей в этот аудит не входят.&lt;/li&gt;&lt;li&gt;Управляет ссылками в Summernote-полях товаров, категорий, производителей при наличии описания, информационных страниц, статей и категорий блога, а также UniShop2 News и его категорий.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Контент-менеджерам и SEO-специалистам с большим количеством редакционных, партнёрских или UGC-ссылок.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=113 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;ImportXML Clean PRO&lt;/strong&gt; імпортує каталоги постачальників у OpenCart/ocStore з обов’язковим preview перед записом. Основний сценарій — ручний контрольований імпорт; cron використовується додатково для регулярного оновлення вже перевірених даних.&lt;/p&gt;&lt;p&gt;Це важливо для прайсів постачальників, де файл може містити неповні дані. Модуль показує старі й нові значення до застосування, а при оновленні існуючого товару не видаляє зображення, атрибути, опції, зв’язки, rewards, layouts, downloads і filters, якщо відповідні секції не надійшли в імпорті.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;XML/YML, CSV/TXT та XLSX.&lt;/li&gt;&lt;li&gt;Безпечний preview без запису в БД із новими товарами, оновленнями, не знайденими й відсутніми у постачальника позиціями.&lt;/li&gt;&lt;li&gt;Порівняння old/new для price, quantity, status, закупівельної та акційної ціни.&lt;/li&gt;&lt;li&gt;Імпорт/оновлення категорій, виробників, зображень і атрибутів, якщо дані є у файлі.&lt;/li&gt;&lt;li&gt;Підтримка model, SKU, UPC, EAN, JAN, ISBN, MPN, location, stock status, ваги, розмірів, сортування, SEO та інших стандартних полів.&lt;/li&gt;&lt;li&gt;Кілька мов.&lt;/li&gt;&lt;li&gt;Перерахунок ціни через стандартну систему валют OpenCart, якщо джерело містить валюту.&lt;/li&gt;&lt;li&gt;Безпечне визначення головної категорії через product_to_category.main_category, product.main_category_id і fallback.&lt;/li&gt;&lt;li&gt;Підтримка Google Product Category ID у сумісному полі категорії.&lt;/li&gt;&lt;li&gt;Нормалізація UTF-8 і Windows-1251 для типових файлів постачальників.&lt;/li&gt;&lt;li&gt;Додатковий cron-режим; рекомендований сценарій — ціна, наявність, залишок і статус уже імпортованих товарів.&lt;/li&gt;&lt;li&gt;Діагностика, сервісні інструменти, export/import налаштувань і очищення логів.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Preview дає можливість перевірити результат до масового запису, що значно безпечніше за «сліпий» автоматичний імпорт.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які отримують XML/YML/CSV/XLSX від постачальників і потребують контрольованого імпорту без втрати вже налаштованих даних.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=114 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;ImportXML Clean PRO imports supplier catalogs from XML/YML, CSV/TXT and XLSX with a preview-first workflow before database changes.&lt;/p&gt;&lt;p&gt;Supplier files are often incomplete. The module therefore compares old and new values and preserves existing images, options, attributes and relations when the incoming source does not provide those sections.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The recommended cron mode updates prices, available attribute, quantity/stock, stock_status_id and product status for existing products. It does not create new products and does not overwrite descriptions, images, categories or SEO. Use full cron import only deliberately, preferably at night.&lt;/li&gt;&lt;li&gt;Warning: cron can be a heavy operation. The default safe mode updates prices, availability, quantity/stock, stock status and product status for existing products. Full cron import can download XML, create categories, update images, descriptions and SEO, so do not run it during peak hours.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores that receive supplier files and need controlled recurring catalog imports without wiping already configured data.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=114 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;ImportXML Clean PRO импортирует каталоги поставщиков из XML/YML, CSV/TXT и XLSX с обязательным preview перед записью в базу.&lt;/p&gt;&lt;p&gt;Файлы поставщиков часто неполные, поэтому модуль сравнивает старые и новые значения и не удаляет существующие изображения, опции, атрибуты и связи, если соответствующих данных нет во входном файле.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Польза модуля: первичный импорт каталога, безопасное сравнение old/new перед применением, обновление цен, остатков, статуса, закупочной цены поставщика и акционных цен. Cron можно использовать как дополнительную функцию для обновления только существующих товаров без перезаписи описаний, изображений, категорий и SEO.&lt;/li&gt;&lt;li&gt;Рекомендуемый режим для cron обновляет цены, наличие по available, количество/остатки, stock_status_id и статус существующих товаров. Он не создает новые товары, не перезаписывает описания, изображения, категории и SEO. Полный cron-импорт используйте только осознанно и лучше ночью.&lt;/li&gt;&lt;li&gt;Внимание: cron может быть тяжелой операцией. Безопасный режим по умолчанию обновляет цены, наличие, остатки, статус наличия и статус существующих товаров. Полный cron-импорт может скачивать XML, создавать категории, обновлять изображения, описания и SEO, поэтому не запускайте его в часы пик.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с файлами поставщиков, которым нужен контролируемый регулярный импорт без потери уже настроенных данных.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=114 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Google Maps Reviews PRO&lt;/strong&gt; допомагає запросити реального покупця залишити відгук у Google Maps / Google Business Profile після завершеного замовлення.&lt;/p&gt;&lt;p&gt;Модуль не створює відгуки сам і не підміняє користувача. Він показує коректний заклик на сайті та надсилає відкладені email-нагадування, а сам відгук клієнт залишає безпосередньо в Google.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Блок запрошення на сторінці успішного замовлення.&lt;/li&gt;&lt;li&gt;Окремий блок на сторінці контактів.&lt;/li&gt;&lt;li&gt;Опціональна плаваюча кнопка Google Reviews на витрині.&lt;/li&gt;&lt;li&gt;Автоматичний перехід із success page до форми Google після заданої затримки — за окремим налаштуванням.&lt;/li&gt;&lt;li&gt;Відкладені email-запити через cron для вибраних статусів замовлень.&lt;/li&gt;&lt;li&gt;Ручне надсилання запиту зі сторінки замовлення в адмінці.&lt;/li&gt;&lt;li&gt;Список виключених email для тестових, технічних або placeholder-адрес.&lt;/li&gt;&lt;li&gt;Кілька дизайнів storefront-блоків і email-шаблонів.&lt;/li&gt;&lt;li&gt;Відстеження кліків на review link / Google Maps, відправлених, пропущених листів і помилок.&lt;/li&gt;&lt;li&gt;Безпечний стартовий період: нова установка може надсилати тільки для замовлень від заданої дати, щоб не розіслати тисячі старих листів.&lt;/li&gt;&lt;li&gt;Вкладка «Код вставки» для тем, які не виводять стандартний content_bottom.&lt;/li&gt;&lt;li&gt;Діагностика, оновлення схеми, export/import налаштувань і очищення журналу.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає системно просити відгук у клієнтів після реальної покупки, а не покладатися на випадкову активність.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам і сервісним компаніям із Google Business Profile, які хочуть збільшувати кількість реальних відгуків після замовлень.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=115 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Google Maps Reviews PRO helps invite real customers to leave a review in Google Maps / Google Business Profile after a completed purchase.&lt;/p&gt;&lt;p&gt;The module does not create reviews and does not impersonate the customer. It displays a controlled invitation and can send delayed email reminders; the review itself is always submitted by the buyer directly to Google.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Added &quot;Send orders from date&quot; for cron emails. By default the module uses the safe &quot;Only orders from date&quot; mode with the current date, so a fresh install/update does not send review requests to thousands of old orders.&lt;/li&gt;&lt;li&gt;Export is useful for moving settings between sites. After import, check links, email and cron key.&lt;/li&gt;&lt;li&gt;Email addresses that cron and manual order sending must not send review requests to. Use one address per line or separate addresses with commas/semicolons. mail@localhost.com is added by default for placeholder checkout emails.&lt;/li&gt;&lt;li&gt;Statistics cards are clickable quick filters for the table below. Sent/test/error cards filter log events; pending/waiting/candidate/not-sent cards show related orders. Clicking the active filter returns to all events.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores and service businesses with a Google Business Profile that want a systematic post-purchase review request workflow.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=115 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Google Maps Reviews PRO помогает приглашать реальных покупателей оставить отзыв в Google Maps / Google Business Profile после завершённой покупки.&lt;/p&gt;&lt;p&gt;Модуль не создаёт отзывы сам и не действует от имени клиента. Он показывает приглашение и может отправлять отложенные email-напоминания, а сам отзыв покупатель оставляет непосредственно в Google.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Письма отправляются через cron только по выбранным статусам заказов, с задержкой после покупки, лимитом за запуск, повторами при ошибке и защитой от повторной отправки одному email.&lt;/li&gt;&lt;li&gt;Email-адреса, на которые cron и ручная отправка из заказа не будут отправлять просьбу оставить отзыв. Можно указывать по одному адресу в строке или через запятую/точку с запятой. По умолчанию добавлен mail@localhost.com для заказов с заглушкой.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам и сервисным компаниям с Google Business Profile, которым нужен системный сценарий запроса отзывов после покупки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=115 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Free Shipping Progress PRO&lt;/strong&gt; показує покупцю, скільки ще потрібно додати в кошик до порога стандартної безкоштовної доставки OpenCart.&lt;/p&gt;&lt;p&gt;Модуль принципово не створює власний метод доставки і не обнуляє ціну Нової пошти, кур’єра або міжнародної доставки. Єдине джерело істини — штатний метод free.free з його порогом і геозоною.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Читає shipping_free_status, shipping_free_total і shipping_free_geo_zone_id.&lt;/li&gt;&lt;li&gt;Суму кошика визначає через стандартний cart-&gt;getSubTotal().&lt;/li&gt;&lt;li&gt;Коректно враховує геозону: поріг може бути виконаний, але адреса ще не підтверджена.&lt;/li&gt;&lt;li&gt;Окреме розміщення в кошику та checkout.&lt;/li&gt;&lt;li&gt;Підтримка стандартної теми OpenCart і UniShop2.&lt;/li&gt;&lt;li&gt;П’ять стилів: Accent, Clean, Minimal, Compact, Banner.&lt;/li&gt;&lt;li&gt;Progress bar, відсоток, іконка, тінь, темний режим і адаптивність.&lt;/li&gt;&lt;li&gt;Мультимовні тексти зі змінними {threshold}, {remaining}, {amount}, {percent}.&lt;/li&gt;&lt;li&gt;Живий preview в адмінці.&lt;/li&gt;&lt;li&gt;AJAX-оновлення після зміни кошика або checkout.&lt;/li&gt;&lt;li&gt;Діагностика наявності Free Shipping, порога, геозони та storefront Event.&lt;/li&gt;&lt;li&gt;Без cron, робочих таблиць і накопичуваних логів; при OFF Event і frontend assets не працюють.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Віджет стимулює покупця збільшити кошик до вже існуючого порога без створення другої логіки доставки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам, які вже використовують стандартну «Безкоштовну доставку» OpenCart і хочуть зробити її поріг видимим для покупця.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=116 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Free Shipping Progress PRO shows how much more a customer needs to add to the cart to reach the store\'s native OpenCart free-shipping threshold.&lt;/p&gt;&lt;p&gt;It does not create a second shipping method and does not zero the price of Nova Poshta, courier or international delivery. The source of truth is the standard free.free method, including its threshold and geo zone.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The module does not create its own free-shipping method and never changes paid shipping prices. OpenCart standard Free Shipping (free.free) is the single source of truth. The widget reads shipping_free_status, shipping_free_total and shipping_free_geo_zone_id and calculates the cart amount with cart-&gt;getSubTotal(), matching the OpenCart 3.x Free Shipping model.&lt;/li&gt;&lt;li&gt;The module creates no operational database tables, queues, cron jobs, or growing logs.&lt;/li&gt;&lt;li&gt;This module does not create or modify shipping prices. It mirrors OpenCart Free Shipping exactly: status, threshold and geo zone.&lt;/li&gt;&lt;li&gt;Security token is invalid or the admin session has expired. Reload the module page and try again.&lt;/li&gt;&lt;li&gt;The module never makes paid shipping methods free. OpenCart itself exposes the separate free.free method only when its own threshold and geo-zone rules are satisfied.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores already using OpenCart Free Shipping that want to make the existing threshold visible and actionable for customers.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=116 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Free Shipping Progress PRO показывает покупателю, сколько осталось добавить в корзину до штатного порога бесплатной доставки OpenCart.&lt;/p&gt;&lt;p&gt;Модуль не создаёт второй способ доставки и не обнуляет стоимость Новой почты, курьера или международной доставки. Единственный источник истины — стандартный free.free с его порогом и геозоной.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Модуль не создаёт собственный способ бесплатной доставки и не делает платные способы доставки бесплатными. Единственный источник истины — штатное расширение OpenCart «Бесплатная доставка» (free.free). Модуль читает его статус, порог shipping_free_total и геозону shipping_free_geo_zone_id, а сумму рассчитывает через cart-&gt;getSubTotal(), как штатная модель OpenCart 3.x.&lt;/li&gt;&lt;li&gt;Модуль не создаёт и не изменяет стоимость доставки. Он точно повторяет штатные настройки OpenCart: статус, порог и геозону.&lt;/li&gt;&lt;li&gt;Модуль никогда не превращает платные способы доставки в бесплатные. Отдельный метод free.free появляется только тогда, когда сама штатная Free Shipping OpenCart разрешает его по порогу и геозоне.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам, которые уже используют стандартную бесплатную доставку OpenCart и хотят наглядно показывать её порог покупателю.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=116 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;GeoIP City PRO&lt;/strong&gt; визначає приблизне місцезнаходження відвідувача за IP через локальну MMDB-базу DB-IP або MaxMind і може використати результат для підказки міста, checkout та правил доступу.&lt;/p&gt;&lt;p&gt;Головна перевага — відсутність зовнішнього GeoIP API на кожній сторінці. Визначення виконується локально, тому не створює мережевий запит до стороннього сервісу для кожного відвідувача.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Локальна MMDB-база DB-IP або MaxMind.&lt;/li&gt;&lt;li&gt;Приблизне визначення країни та міста за IP.&lt;/li&gt;&lt;li&gt;М’яка підказка міста без примусового сценарію для покупця.&lt;/li&gt;&lt;li&gt;Допомога з автозаповненням міста у checkout.&lt;/li&gt;&lt;li&gt;Правила доступу за країною та IP там, де вони ввімкнені.&lt;/li&gt;&lt;li&gt;Робоча витринна логіка активується тільки після ручного ввімкнення й збереження.&lt;/li&gt;&lt;li&gt;Не використовує зовнішній GeoIP API на звичайному відкритті сторінки.&lt;/li&gt;&lt;li&gt;Діагностика наявності й доступності локальної бази.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Автопідказка може скоротити ручне введення адреси, а локальна база зменшує залежність від зовнішнього API.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із регіональним checkout, локальними пропозиціями або правилами доступу за країною.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=117 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;GeoIP City PRO performs approximate country and city detection from an IP address using a local DB-IP or MaxMind MMDB database.&lt;/p&gt;&lt;p&gt;Because lookups are local, normal storefront requests do not need an external GeoIP API call. The result can assist checkout and geo rules, but it is approximate and should never be treated as a verified postal address.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The module detects an approximate customer city by IP using a local MMDB database. It does not replace the delivery address and does not automatically select a Nova Poshta branch. Its purpose is to speed up city selection and show a soft prompt to the customer.&lt;/li&gt;&lt;li&gt;The module uses a local streaming MMDB reader, session/cookie/cache and route-limited loading. CSV is not imported into MySQL.&lt;/li&gt;&lt;li&gt;The module detects an approximate city, region and country by IP using a local MMDB database and can show a storefront city prompt, safely autofill checkout fields and restrict storefront access by country, IP/CIDR/mask and bot User-Agent.&lt;/li&gt;&lt;li&gt;Without MMDB, the module can reliably block by IP and conditionally by country only when the country is provided by Cloudflare/server headers. City lookup is not possible without a database.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores using regional checkout hints, country rules or local personalization without per-request external GeoIP calls.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=117 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;GeoIP City PRO определяет примерную страну и город по IP через локальную MMDB-базу DB-IP или MaxMind.&lt;/p&gt;&lt;p&gt;Проверка выполняется локально, поэтому обычное открытие страницы не требует внешнего GeoIP API. Результат можно использовать как подсказку, но не как подтверждённый почтовый адрес без согласия пользователя.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Модуль определяет примерный город клиента по IP через локальную MMDB-базу. Он не заменяет адрес доставки и не выбирает отделение Новой Почты автоматически. Назначение функции — ускорить выбор города и показать клиенту мягкую подсказку.&lt;/li&gt;&lt;li&gt;Отдельная настройка для оформления заказа. Модуль может подставлять выбранные данные только в указанные поля, не выбирая отделение и не меняя логику доставки.&lt;/li&gt;&lt;li&gt;Сначала загрузите MMDB-базу, проверьте IP в диагностике, затем включите модуль. После этого настройте место показа подсказки и при необходимости включите автоподстановку в checkout.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с региональным checkout, правилами по странам или локальными подсказками без внешнего GeoIP-запроса на каждой странице.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=117 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Extension Cleanup PRO&lt;/strong&gt; допомагає зрозуміти, які файли й записи належать розширенню OpenCart/ocStore, виконати штатний uninstall і лише після перевірки — фізично видалити підтверджені залишки.&lt;/p&gt;&lt;p&gt;Модуль створений для обережного обслуговування магазину. Він не видаляє каталоги рекурсивно і не вважає файл «своїм» лише через схоже ім’я. Перед повним видаленням аналізуються Installer-метадані, OCMOD, Events, settings, module instances, залежності та спільні файли.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Інвентаризація встановлених і не встановлених розширень, файли яких залишилися на сервері.&lt;/li&gt;&lt;li&gt;Підтримка module, payment, shipping, total, feed, analytics, captcha, fraud, dashboard, report, theme, currency, advertise та menu.&lt;/li&gt;&lt;li&gt;Окремий аналіз ризику перед uninstall або повним видаленням.&lt;/li&gt;&lt;li&gt;Перевірка Installer ownership, OCMOD, Events, settings, instances і залежностей.&lt;/li&gt;&lt;li&gt;Блокування небезпечного видалення при спільних файлах, багатокомпонентному пакеті, невідомому типі або неоднозначній приналежності.&lt;/li&gt;&lt;li&gt;Перед фізичним видаленням створюється ZIP підтверджених файлів із manifest.&lt;/li&gt;&lt;li&gt;Фільтри, сортування, пагінація та масові дії тільки для дозволених низькоризикових випадків.&lt;/li&gt;&lt;li&gt;OFF рекомендований у звичайній роботі; модуль вмикається лише на час обслуговування.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Це безпечніша альтернатива ручному видаленню файлів «на око», яке часто залишає записи БД або, навпаки, видаляє спільні компоненти.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Розробникам і адміністраторам магазинів із великою кількістю встановлених, тестових або вже видалених розширень.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=118 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Extension Cleanup PRO audits what belongs to an OpenCart/ocStore extension, performs the native uninstall workflow and only then allows confirmed leftovers to be removed.&lt;/p&gt;&lt;p&gt;It is deliberately conservative: it does not recursively delete folders just because a name looks familiar. Installer ownership, OCMOD, Events, settings, module instances, dependencies and shared files are checked before destructive actions.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;module, payment, shipping, total, feed, analytics, captcha, fraud, dashboard, report, theme, currency, advertise and menu. Unknown types are shown in Diagnostics and are not removed automatically.&lt;/li&gt;&lt;li&gt;The module combines database records with extension files actually present on the server, so it can show both installed extensions and uninstalled standard extensions whose files remain. Before physical deletion it checks Installer metadata, file ownership, OCMOD, Events, settings, module instances and dependencies. A verified ZIP copy is created before confirmed files are removed.&lt;/li&gt;&lt;li&gt;The module does not restore the database and does not perform automatic rollback. Automatic file restoration is intentionally excluded because restoring files without restoring matching database state can produce an inconsistent store.&lt;/li&gt;&lt;li&gt;While OFF there is no working extension scan, deletion, modifying AJAX, cron, queues, Events or storefront code. Settings, About and basic diagnostics remain available when explicitly opened.&lt;/li&gt;&lt;li&gt;The ZIP created by Extension Cleanup PRO contains only confirmed files of the selected extension and manifest.json. It does not replace a database backup or a full site backup.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Developers and administrators maintaining stores with many installed, tested or partially removed extensions.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=118 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Extension Cleanup PRO определяет, какие файлы и записи действительно принадлежат расширению OpenCart/ocStore, выполняет штатный uninstall и только после проверки позволяет удалить подтверждённые остатки.&lt;/p&gt;&lt;p&gt;Модуль специально сделан консервативным: он не удаляет каталоги рекурсивно только из-за похожего имени. Перед удалением проверяются Installer ownership, OCMOD, Events, settings, instances, зависимости и общие файлы.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;В OFF нет рабочего сканирования расширений, удаления, AJAX-операций, cron, очередей, Events или кода витрины. Доступны настройки, раздел «О модуле» и базовая диагностика по явному открытию соответствующей вкладки.&lt;/li&gt;&lt;li&gt;Extension Cleanup PRO помогает увидеть реальные расширения и файловые остатки, проверить зависимости и аккуратно удалить ненужный код без ручного поиска по каталогам.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Разработчикам и администраторам магазинов с большим количеством установленных, тестовых или частично удалённых расширений.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=118 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Feed Export PRO&lt;/strong&gt; створює окремі профілі товарних фідів для різних мов, валют, країн і рекламних систем та дозволяє точно контролювати, які товари й дані потрапляють у кожен канал.&lt;/p&gt;&lt;p&gt;Модуль підходить для магазинів, де одного універсального XML недостатньо: Google Merchant, Meta, партнерські майданчики або власні інтеграції можуть потребувати різних наборів товарів, валют, зображень і категорій.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Профілі для різних мов, валют, країн і рекламних систем.&lt;/li&gt;&lt;li&gt;Фільтри за статусом, наявністю, ціною, категоріями та виробниками.&lt;/li&gt;&lt;li&gt;Стандартний розрахунок податків, валюти, звичайної й акційної ціни.&lt;/li&gt;&lt;li&gt;Головне зображення та до 10 унікальних додаткових зображень.&lt;/li&gt;&lt;li&gt;Режими зображень: original, власний cache, готові файли, стандартний resize, інтеграція AVIF WebP Image PRO та auto.&lt;/li&gt;&lt;li&gt;Для Google Merchant AVIF автоматично замінюється на WebP.&lt;/li&gt;&lt;li&gt;Головна категорія визначається через main_category з безпечним fallback.&lt;/li&gt;&lt;li&gt;Строга перевірка GTIN; недійсний ідентифікатор не передається.&lt;/li&gt;&lt;li&gt;identifier_exists=no формується лише за відсутності валідного GTIN і повної пари brand + MPN.&lt;/li&gt;&lt;li&gt;Очищення style/script/template/noscript з описів.&lt;/li&gt;&lt;li&gt;Діагностика зображень, brand, ідентифікаторів, product_type і Google Product Category.&lt;/li&gt;&lt;li&gt;Пакетна генерація, cache, cron та атомарний запис готових фідів/звітів.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Окремі профілі дозволяють не змішувати вимоги різних рекламних каналів в одному файлі.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із декількома рекламними каналами, валютами або країнами, де потрібні різні товарні фіди.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=119 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Feed Export PRO creates separate catalog-feed profiles for different languages, currencies, countries and advertising systems.&lt;/p&gt;&lt;p&gt;A single universal XML file is often not enough. Google, Meta, YML partners or custom integrations may require different products, image rules, currencies and category mappings, so the module keeps each channel independently configurable.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;It supports separate feed profiles, languages, currencies, URL prefixes, secret links, cron, cache, preview, diagnostics, category mapping, attribute mapping, sale prices, additional images and safe data cleanup.&lt;/li&gt;&lt;li&gt;The module creates product feeds for Google Merchant, Meta/Facebook, YML, CSV and Simple XML. It is used to send products to ad platforms, marketplaces, price aggregators and external integrations without manual export.&lt;/li&gt;&lt;li&gt;One rule per line: gtin = EAN, Barcode. Supported: gtin, mpn, brand, color, size, material, gender, age_group, custom_label_0-4, shipping_label, return_policy_label, video_link. The normal product model is no longer used as MPN automatically; MPN is exported only from the MPN field or a mapped attribute.&lt;/li&gt;&lt;li&gt;Defines where image URLs in the feed come from. For AVIF WebP Image Pro, choose compatibility mode or Auto: Feed Export Pro calls the standard OpenCart resize method, lets the external module generate WebP/AVIF at the requested size, and then uses that URL in the feed.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Multilingual or multi-market stores that need several controlled product feeds instead of one generic export.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=119 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Feed Export PRO создаёт отдельные профили товарных фидов для разных языков, валют, стран и рекламных систем.&lt;/p&gt;&lt;p&gt;Одного универсального XML часто недостаточно: Google, Meta, YML-партнёры и собственные интеграции могут требовать разные товары, изображения, валюты и категории. Модуль позволяет управлять каждым каналом отдельно.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Feed Export Pro создает товарные фиды для OpenCart/ocStore 3.x в форматах Google Merchant RSS 2.0, Meta/Facebook, YML, CSV и XML. Для каждого профиля можно выбрать язык, валюту, страну, формат, фильтры, защищенную ссылку и cron-ссылку.&lt;/li&gt;&lt;li&gt;Поддерживает отдельные профили фидов, языки, валюты, URL-префиксы, секретные ссылки, cron, кеш, предпросмотр, диагностику, маппинг категорий, маппинг атрибутов, акционные цены, дополнительные фото и безопасную очистку данных.&lt;/li&gt;&lt;li&gt;Модуль AVIF WebP Image Pro включён. Feed Export Pro может использовать его resize-кеш и не дублировать генерацию без необходимости.&lt;/li&gt;&lt;li&gt;Папка кеша изображений фида недоступна для записи. Проверьте права на image/cache/feed_export_pro/.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Мультиязычным и многорынковым магазинам, которым нужно несколько управляемых товарных фидов вместо одной общей выгрузки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=119 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Duplicate Cleaner PRO&lt;/strong&gt; знаходить підозрілі дублікати й структурні помилки в каталозі OpenCart/ocStore, щоб адміністратор міг перевірити їх до видалення або об’єднання.&lt;/p&gt;&lt;p&gt;Дублі виникають після імпорту, повторного завантаження прайсів, міграцій і ручного редагування. Вони можуть створювати однакові URL, метадані, моделі або дубльовані зв’язки категорій.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Потенційні повні дублікати товарів за назвою, model, SKU, виробником і ціною.&lt;/li&gt;&lt;li&gt;Окремий пошук дублів назв товарів.&lt;/li&gt;&lt;li&gt;Дублікати SEO URL у seo_url і legacy url_alias.&lt;/li&gt;&lt;li&gt;Дублікати Meta Title, Meta Description і Meta H1 у товарах, категоріях, інформаційних сторінках, виробниках, блогах і UniShop News.&lt;/li&gt;&lt;li&gt;Дублікати model та SKU.&lt;/li&gt;&lt;li&gt;Дублікати налаштувань і категорій.&lt;/li&gt;&lt;li&gt;Порожні, биті та повторювані product_to_category.&lt;/li&gt;&lt;li&gt;Товари без валідної головної категорії.&lt;/li&gt;&lt;li&gt;Результати призначені для контрольованої перевірки, а не для сліпого масового видалення даних.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає виявити проблеми, які складно побачити в стандартних списках OpenCart.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам після імпорту/міграції та каталогам, які регулярно синхронізуються з кількома джерелами.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=120 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Duplicate Cleaner PRO finds suspicious duplicate products and structural catalog problems so an administrator can review them before any cleanup.&lt;/p&gt;&lt;p&gt;Duplicates typically appear after imports, migrations and repeated supplier uploads. The module separates different problem types instead of treating every similar value as a product that should be deleted.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Duplicate Cleaner Pro finds duplicates and technical damage in the OpenCart/ocStore catalog: possible full duplicate product cards, duplicate names, SEO URL in seo_url and url_alias, meta title, meta description in products/categories/information/manufacturers, models, SKU, settings, categories, product_to_category relations and main categories. The module does not run on the storefront and does not change site behavior.&lt;/li&gt;&lt;li&gt;Duplicate meta title/meta description values in products, categories, information articles and manufacturers are shown for manual review only. SEO fields are not overwritten automatically.&lt;/li&gt;&lt;li&gt;url_alias is used by older builds and some SEO modules. Exact duplicates for one query can be deleted after preview; conflicts between different queries must be fixed manually.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores after migration or recurring supplier imports, and catalogs that need periodic duplicate and relationship audits.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=120 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Duplicate Cleaner PRO находит подозрительные дубли товаров и структурные проблемы каталога, чтобы администратор проверил их до очистки.&lt;/p&gt;&lt;p&gt;Дубли часто появляются после импорта, миграции и повторной загрузки прайсов. Модуль разделяет разные типы проблем и не считает каждое похожее значение товаром, который надо автоматически удалить.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Duplicate Cleaner Pro ищет дубли и технические повреждения в каталоге OpenCart/ocStore: возможные полные дубли карточек товаров, дубли названий, SEO URL в seo_url и url_alias, meta title, meta description и meta H1 по товарам, категориям, информационным страницам, производителям, статьям блога и новостям UniShop, модели, SKU, настройки, категории, связи product_to_category и главные категории. Модуль не работает на витрине и не меняет поведение сайта.&lt;/li&gt;&lt;li&gt;Duplicate Cleaner Pro — безопасный технический модуль аудита для ocStore 3.0.x и OpenCart 3.x. Он помогает администратору найти дубли и повреждённые связи каталога до того, как они начнут портить SEO, навигацию, фильтры, фиды, карту сайта или обслуживание магазина.&lt;/li&gt;&lt;li&gt;Модуль уменьшает технический долг каталога, помогает находить SEO-конфликты, опасные дубли настроек и повреждённые связи категорий. Он полезен перед SEO-работами, генерацией фидов, созданием sitemap, миграциями, импортом от поставщиков и ручной чисткой каталога.&lt;/li&gt;&lt;li&gt;Дубли meta title/meta description по товарам, категориям, статьям и производителям показываются только для ручного анализа. Автоперезапись SEO-полей не выполняется.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам после миграции или регулярных импортов, которым нужен периодический аудит дублей и связей каталога.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=120 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Denmark Delivery PRO&lt;/strong&gt; — менеджер доставки для OpenCart/ocStore з реальними перевізниками, pickup points, тарифами, підготовкою відправлень, labels і tracking.&lt;/p&gt;&lt;p&gt;Модуль не показує Shipmondo як назву перевізника на витрині: покупець бачить реальний carrier/product. Для pickup/locker завантажуються точки видачі, а домашня доставка не вимагає service point.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Live API price для Bring Shipping Guide і DHL Express MyDHL.&lt;/li&gt;&lt;li&gt;Точний carrier product/service code для кожного методу.&lt;/li&gt;&lt;li&gt;Фіксована націнка або %, округлення вгору та поріг безкоштовної доставки.&lt;/li&gt;&lt;li&gt;Fallback на Fixed, Weight tiers або Country + weight, якщо live API недоступний.&lt;/li&gt;&lt;li&gt;PostNord, GLS і dao використовують перевірені fallback-тарифи замість непідтверджених price endpoints.&lt;/li&gt;&lt;li&gt;Fixed price, вагові сходинки, country+weight правила та free delivery.&lt;/li&gt;&lt;li&gt;Shipmondo dynamic carriers/products із незалежним налаштуванням від direct API методів.&lt;/li&gt;&lt;li&gt;Pickup/locker, home delivery і returns; return-only продукти не показуються у checkout.&lt;/li&gt;&lt;li&gt;Модальне вікно підготовки відправлення без перезапису оригінального замовлення.&lt;/li&gt;&lt;li&gt;Вага, parcels, dimensions, services, service point, customs, scheduled pickup, labels, tracking, returns і cancellation.&lt;/li&gt;&lt;li&gt;Масові labels і CSV-експорт за датою/фільтрами.&lt;/li&gt;&lt;li&gt;PDF labels зберігаються у захищеному DIR_STORAGE.&lt;/li&gt;&lt;li&gt;Мови da-dk, de-de, en-gb, ru-ru, uk-ua.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Один модуль може об’єднати кілька реальних перевізників і різні моделі ціноутворення без показу технічного агрегатора покупцю.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам у Данії та ЄС, які працюють із Bring, DHL, PostNord, GLS, dao, Shipmondo та потребують checkout + післязамовну логістику.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;da-dk / de-de / en-gb / ru-ru / uk-ua&lt;/li&gt;&lt;li&gt;Стандартний checkout та UniShop2&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=121 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Denmark Delivery PRO manages checkout shipping and post-order shipment preparation for Denmark and international destinations with real carriers and pickup-point workflows.&lt;/p&gt;&lt;p&gt;Customers see the actual carrier/product rather than a technical aggregator name. Pickup and locker services use service points, while home delivery remains a separate workflow without forcing a pickup location.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Shipmondo synchronizes available countries, services and confirmed weight limits when the API provides them. Checkout selling prices are not imported from Shipmondo because they depend on your contract. Bring Shipping Guide and DHL MyDHL can return live account rates when the required credentials, exact product code and account permissions are configured.&lt;/li&gt;&lt;li&gt;Shipmondo-required customs products can send currency, export reason, Incoterm, freight/insurance and goods lines with HS code, ISO-2 origin country, quantity, unit value and unit weight. CN22/CN23/customs documents are produced by Shipmondo/carrier according to the selected product; the module does not invent customs documents itself.&lt;/li&gt;&lt;li&gt;Optional. The method is hidden when the estimated parcel dimensions exceed these limits. For multi-item carts the module preserves combined product volume instead of checking only the largest item; if product dimensions are unavailable, the configured default parcel dimensions are used.&lt;/li&gt;&lt;li&gt;Multi-provider delivery and shipping manager for Denmark. Shipmondo is optional: PostNord, Bring, DHL, GLS and dao pickup-point adapters can work independently. Shipmondo remains a universal aggregator/fallback and can also receive Sales Orders, create shipments and print labels.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Danish and EU stores working with Bring, DHL, PostNord, GLS, dao, Shipmondo and related shipping workflows.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;da-dk / de-de / en-gb / ru-ru / uk-ua&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=121 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Denmark Delivery PRO управляет доставкой в checkout и подготовкой отправлений после заказа для Дании и международных направлений с реальными перевозчиками и pickup points.&lt;/p&gt;&lt;p&gt;Покупатель видит реального carrier/product, а не техническое имя агрегатора. Pickup/locker использует точки выдачи, а домашняя доставка работает отдельно и не требует service point.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Очистить технический журнал Denmark Delivery? История доставки заказов удалена не будет.&lt;/li&gt;&lt;li&gt;Мультипровайдерный модуль доставки и Shipping Manager для Дании. Shipmondo необязателен: адаптеры пунктов PostNord, Bring, DHL, GLS и dao способны работать независимо. Shipmondo остаётся универсальным агрегатором/fallback и может принимать Sales Orders, создавать отправления и печатать labels.&lt;/li&gt;&lt;li&gt;Создание отправления — отдельное действие администратора. Недоступность API перевозчика не блокирует оформление заказа клиентом. Sales Order передаёт заказ в Shipmondo без покупки отправления; «Создать отправление» создаёт shipment и label через источник, выбранный для способа доставки.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам Дании и ЕС, работающим с Bring, DHL, PostNord, GLS, dao, Shipmondo и связанными логистическими сценариями.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;da-dk / de-de / en-gb / ru-ru / uk-ua&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=121 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Bot Security PRO&lt;/strong&gt; поєднує кілька рівнів захисту OpenCart: політики ботів, WAF-перевірки, rate limit, репутацію, блокування IP/країн, журнал подій і окрему аналітику відвідувачів.&lt;/p&gt;&lt;p&gt;Завдання модуля — зменшити автоматизоване сміття й небажані запити, не перетворюючи кожен перегляд сторінки на зовнішній API-виклик. GeoIP і країна можуть визначатися локально через GeoLite2/MaxMind, а запис ботів у visitor analytics вмикається окремо.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Bot Policy і Bot Guard для класифікації та контролю автоматизованих запитів.&lt;/li&gt;&lt;li&gt;WAF-рівень для типових підозрілих запитів.&lt;/li&gt;&lt;li&gt;Rate Limit із журналом причин і можливістю блокування.&lt;/li&gt;&lt;li&gt;IP bans і контроль репутації.&lt;/li&gt;&lt;li&gt;Geo Access за країною з окремими винятками для технічних маршрутів.&lt;/li&gt;&lt;li&gt;Підтримка локального GeoLite2/MaxMind Country без зовнішнього GeoIP API на кожній сторінці.&lt;/li&gt;&lt;li&gt;Перевірені пошукові боти можуть обходити country restrictions після DNS-перевірки.&lt;/li&gt;&lt;li&gt;Security Journal із країною/прапором для нових подій.&lt;/li&gt;&lt;li&gt;Visitor analytics із окремим перемикачем запису ботів; за замовчуванням бот-візити можна не накопичувати.&lt;/li&gt;&lt;li&gt;Сторінки payment callbacks, API, cron, feeds, queues і webhooks можуть бути виключені з Geo-обмежень.&lt;/li&gt;&lt;li&gt;Оптимізація повторних GeoIP lookup у межах одного HTTP-запиту.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає відокремити безпеку від аналітики: бот може бути перевірений і заблокований, але не зобов’язаний заповнювати таблицю відвідувачів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із бот-навантаженням, спамом, сканерами, підозрілими запитами або потребою контролювати доступ за IP/країною.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=122 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Bot Security PRO combines several security layers for OpenCart: bot policy, WAF checks, rate limiting, reputation, IP/country rules, a security journal and optional visitor analytics.&lt;/p&gt;&lt;p&gt;Security and analytics are kept separate: a bot can be detected or blocked without automatically filling the visitor table. Local GeoLite2/MaxMind data can be used to avoid an external GeoIP lookup on every request.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Browser Challenge is OFF by default. It only evaluates suspicious storefront GET navigations and never intercepts POST, AJAX or JSON traffic. A successful JavaScript check creates a short-lived, HMAC-signed HttpOnly clearance cookie bound to the current IP and User-Agent. No external CAPTCHA, per-IP files or database challenge rows are created. Verified supported search crawlers are bypassed after DNS verification. Keep checkout, payment callbacks, API, cron, queue and webhook routes excluded.&lt;/li&gt;&lt;li&gt;Fast-growing security tables now have two independent cleanup boundaries: retention age and maximum row count. Diagnostics also show current database storage usage, maintenance status and Fail2ban log size. Data is removed when either boundary is reached first. Maintenance runs autonomously, uses bounded batches and retries sooner when overflow remains. Fail2ban output is rotated by maximum file size and generation count.&lt;/li&gt;&lt;li&gt;1.1.5: adds the visitor/admin usability audit pass: recent bot activity, unified Journal quick views, readable 404 paths, DD.MM.YYYY dates, device type, selectable/permanent IP bans, local colored country flags, clearer WAF/Geo runtime states, fixed bot/filter layouts, and legacy import moved to Diagnostics. Visitor tracking remains OFF by default and performs no work while the main module is OFF.&lt;/li&gt;&lt;li&gt;One OpenCart route or wildcard per line. Payment callbacks, API, cron, workers, queues, feeds and webhooks must be excluded. Global exclusions bypass WAF, Geo, rate/reputation and temporary/manual DB bans; the explicit IP blacklist remains absolute.&lt;/li&gt;&lt;li&gt;Country filtering is an access-control layer, not a substitute for CDN/WAF protection. VPNs and proxies can bypass country rules. Start with Log only and verify payment callbacks, API, cron, feeds and search-bot access before switching to Block.&lt;/li&gt;&lt;li&gt;Blocking a bot family applies across its changing IP addresses. This can stop search indexing, social link previews or AI discovery if the wrong crawler is blocked. Only trusted search bots should be allowed after verification.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores facing bot traffic, spam, scanners, abusive automation or a need for controlled IP/country access rules.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=122 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Bot Security PRO объединяет несколько уровней защиты OpenCart: политики ботов, WAF, rate limit, репутацию, IP/страны, журнал безопасности и отдельную аналитику посетителей.&lt;/p&gt;&lt;p&gt;Безопасность отделена от аналитики: бот может быть распознан или заблокирован без обязательной записи каждого визита. Для страны можно использовать локальную GeoLite2/MaxMind, не вызывая внешний GeoIP API на каждой странице.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Это оценка PHP/OpenCart-нагрузки, а не точный сетевой трафик. Изображения, CSS, JS, AVIF/WebP и другие статические файлы, которые Nginx/Apache/CDN отдаёт напрямую, модуль не видит.&lt;/li&gt;&lt;li&gt;Один route или wildcard OpenCart на строку. Обязательно исключите оплату, API, cron, workers, queues, feeds и webhooks. Глобальные исключения обходят WAF, Geo, ограничения/репутацию и временные/ручные блокировки из таблицы IP-блокировок; явный чёрный список IP остаётся абсолютным.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с бот-нагрузкой, спамом, сканерами, автоматизированными атаками или правилами доступа по IP/стране.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=122 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Catalog Import PRO&lt;/strong&gt; — інструмент для контрольованого масового імпорту каталогу з чітким ключем зіставлення, dry-run, построковим review і транзакційною чергою.&lt;/p&gt;&lt;p&gt;Модуль створений для ситуацій, де помилка в mapping або ключі може змінити тисячі товарів. Тому strict selected-key є обов’язковим: прихованого fallback-пошуку за іншими полями немає.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Швидкі сценарії: тільки ціни, тільки залишки, тільки нові товари та повний імпорт.&lt;/li&gt;&lt;li&gt;Профілі prices, stock, prices+stock, new only, existing only та full upsert.&lt;/li&gt;&lt;li&gt;Mapping колонок постачальника з нечутливим до регістру зіставленням RU/UA заголовків.&lt;/li&gt;&lt;li&gt;Політика для кожного поля: preserve, overwrite, fill_empty, merge, replace або clear.&lt;/li&gt;&lt;li&gt;Небезпечне очищення обов’язкових полів і вибраного ключа блокується.&lt;/li&gt;&lt;li&gt;Dry-run із review та вибором конкретних рядків перед реальним застосуванням.&lt;/li&gt;&lt;li&gt;Статуси, пошук, серверна пагінація, CSV-звіти та повтор помилок.&lt;/li&gt;&lt;li&gt;Ідемпотентна підготовка черги з unique batch/CSV-row protection.&lt;/li&gt;&lt;li&gt;Worker leases, продовження токена перед рядком і recovery завислих processing-задач.&lt;/li&gt;&lt;li&gt;Зміна каталогу й завершення queue item виконуються в одній транзакції.&lt;/li&gt;&lt;li&gt;Безпечне створення категорій і виробників ocStore.&lt;/li&gt;&lt;li&gt;Імпорт/експорт discounts, specials, rewards і recurring profiles.&lt;/li&gt;&lt;li&gt;Supplier-scoped missing sync: disable, zero-stock або delete лише після baseline, dry-run і ручного підтвердження.&lt;/li&gt;&lt;li&gt;Streaming export із захистом від CSV Formula Injection.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль дає детальний контроль над тим, що саме може змінити файл постачальника, і зменшує ризик випадкового перезапису важливих полів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із регулярними CSV-імпортами, кількома постачальниками й вимогами до контрольованої синхронізації каталогу.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=123 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Catalog Import PRO provides controlled bulk catalog import with an explicit matching key, dry-run, per-row review and a persistent transactional queue.&lt;/p&gt;&lt;p&gt;The strict selected key is intentional: there is no hidden fallback search by other fields that could update the wrong product. Field policies define exactly what a supplier file is allowed to overwrite, preserve, merge or clear.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;`_ID_`, `_NAME_`, `_DESCRIPTION_`, `_META_TITLE_`, `_META_DESCRIPTION_`, `_META_KEYWORD_`, `_META_H1_`, `_PARENT_ID_`, `_PARENT_CATEGORY_`, `_TOP_`, `_COLUMN_`, `_SORT_ORDER_`, `_STATUS_`, `_NOINDEX_`, `_IMAGE_`, `_STORE_IDS_`, `_FILTER_IDS_`, `_RELATED_PRODUCT_IDS_`, `_RELATED_ARTICLE_IDS_`, `_LAYOUTS_`, `_SEO_KEYWORD_`.&lt;/li&gt;&lt;li&gt;`_PRODUCT_ID_`, `_PRODUCT_MODEL_`, `_PRODUCT_SKU_`, `_PRODUCT_NAME_`, `_OPTION_ID_`, `_OPTION_`, `_OPTION_TYPE_`, `_OPTION_SORT_ORDER_`, `_OPTION_VALUE_ID_`, `_OPTION_VALUE_`, `_REQUIRED_`, `_QUANTITY_`, `_SUBTRACT_`, `_PRICE_`, `_PRICE_PREFIX_`, `_POINTS_`, `_POINTS_PREFIX_`, `_WEIGHT_`, `_WEIGHT_PREFIX_`, `_IMAGE_`, `_SORT_ORDER_`.&lt;/li&gt;&lt;li&gt;The module remains OFF after installation and schema migration. Import, queue preparation, processing, recovery, export and remote-image downloading are blocked until it is enabled manually.&lt;/li&gt;&lt;li&gt;Safe batch import and streaming export of the OpenCart catalogue through a persistent AJAX queue.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores with recurring supplier CSV imports, multiple sources and strict requirements for safe catalog synchronization.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=123 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Catalog Import PRO выполняет контролируемый массовый импорт каталога с явным ключом сопоставления, dry-run, построчным review и постоянной транзакционной очередью.&lt;/p&gt;&lt;p&gt;Выбранный ключ применяется строго: скрытого fallback-поиска по другим полям нет, чтобы не обновить чужой товар. Для каждого поля задаётся политика overwrite/preserve/fill/merge/clear.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Catalog Import PRO — административный модуль безопасного пакетного импорта и потокового экспорта товаров, категорий, производителей и опций через постоянную AJAX-очередь.&lt;/li&gt;&lt;li&gt;Тестовый режим выполняет поиск записи, полную валидацию, проверку связей, изображений, SEO URL и планируемого действия без изменения каталога.&lt;/li&gt;&lt;li&gt;Цены, остатки, описания, категории, изображения, SEO URL, атрибуты, скидки, акции и связи.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с регулярными CSV-импортами, несколькими поставщиками и требованиями к безопасной синхронизации каталога.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=123 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;AI Article Writer PRO&lt;/strong&gt; автоматизує повний цикл контенту: аналіз тематики магазину, SEO-ключі, ідеї статей, написання, зображення, чернетки, внутрішні посилання та публікацію в підтримувані розділи.&lt;/p&gt;&lt;p&gt;Модуль будує теми на основі реального каталогу, активних категорій і товарів, а не на абстрактній «галузі». Для масової роботи використовується черга/Cron, а автопублікація після генерації зображення за замовчуванням вимкнена, щоб адміністратор міг перевірити чернетку.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;SEO-ядро ключових слів із джерелом, інтентом, оцінкою, показниками попиту та статусом використання.&lt;/li&gt;&lt;li&gt;Пакетний аналіз активних категорій і товарів як джерела тематики.&lt;/li&gt;&lt;li&gt;Генерація тем із ключів і окрема дія «написати статтю за цією темою».&lt;/li&gt;&lt;li&gt;Основний і додаткові ключі розподіляються між розділами та FAQ без механічного повторення.&lt;/li&gt;&lt;li&gt;Внутрішня перелінковка підбирає релевантну категорію або товар і вставляє посилання в текст.&lt;/li&gt;&lt;li&gt;Генерація професійних SEO-статей із чернетками, preview, пошуком, сортуванням і масовими діями.&lt;/li&gt;&lt;li&gt;Генерація зображень окремим графічним провайдером/моделлю.&lt;/li&gt;&lt;li&gt;Черга для масового написання; після тексту можна автоматично поставити генерацію фото.&lt;/li&gt;&lt;li&gt;Помилка однієї статті не зупиняє інші завдання черги.&lt;/li&gt;&lt;li&gt;Переклад і публікація налаштовуються окремо; вихідну статтю можна публікувати без обов’язкового перекладу.&lt;/li&gt;&lt;li&gt;Адаптери для ocStore Blog, UniShop-подібних articles/news, OpenCart Information та сумісних користувацьких таблиць.&lt;/li&gt;&lt;li&gt;Списки моделей OpenAI/Gemini/Cloudflare отримуються з офіційних API, а не зашиваються назавжди в код.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль скорочує шлях від SEO-ідеї до готової чернетки й дозволяє системно наповнювати блог без ручного перенесення тексту між зовнішнім AI та OpenCart.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із блогом, інформаційним розділом або контент-маркетингом, де потрібно регулярно створювати тематичні матеріали.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=124 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Article Writer PRO automates the content workflow from catalog-based topic research to SEO keywords, article drafts, images, internal links and publication into supported OpenCart content sections.&lt;/p&gt;&lt;p&gt;Topics are derived from real active categories and products rather than a generic industry label. Bulk writing uses a queue/Cron workflow, and automatic publication after image generation stays disabled by default so drafts can be reviewed first.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The module analyses categories and products, uses all placed orders with status above 0, sold quantity and product views, and can optionally validate wording through the connected AI web search.&lt;/li&gt;&lt;li&gt;AI Article Writer PRO builds an SEO plan from the actual catalogue, internal store demand, imported keywords and optional web validation, then creates topics, articles, images and publications.&lt;/li&gt;&lt;li&gt;The score combines catalogue relevance, orders, sold quantity, product views, Search Console metrics and optional AI web-search validation.&lt;/li&gt;&lt;li&gt;Autonomous mode uses catalogue data, orders, views and AI clustering. Web validation and Search Console import are optional.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores running a blog or content-marketing program that need a repeatable article-production workflow tied to the actual catalog.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=124 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Article Writer PRO автоматизирует цикл контента: анализ тематики каталога, SEO-ключи, идеи статей, написание, изображения, внутренние ссылки и публикацию в поддерживаемые разделы OpenCart.&lt;/p&gt;&lt;p&gt;Темы строятся по реальным активным категориям и товарам, а не по абстрактной отрасли. Массовая работа идёт через очередь/Cron, а автопубликация после генерации изображения по умолчанию выключена, чтобы сначала проверить черновик.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Модуль анализирует категории и товары, учитывает все оформленные заказы со статусом больше 0, проданное количество и просмотры. При необходимости проверяет формулировки через веб-поиск подключённого AI-провайдера.&lt;/li&gt;&lt;li&gt;AI Article Writer PRO строит SEO-план по фактическому каталогу, внутреннему спросу магазина, собственным ключам и необязательной веб-проверке, затем создаёт темы, статьи, изображения и публикации.&lt;/li&gt;&lt;li&gt;Оценка формируется из соответствия каталогу, заказов, проданного количества, просмотров, данных Search Console и необязательного подтверждения формулировок через веб-поиск AI.&lt;/li&gt;&lt;li&gt;Исправлен интерфейс очереди. Кнопка запуска больше не становится визуально недоступной во время AI-запроса: она показывает состояние «Очередь работает», а повторное нажатие сообщает, что уже обрабатывается один запрос. Таблица очереди обновляется каждые 3 секунды и показывает фактического провайдера и модель текущей статьи или изображения.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с блогом или контент-маркетингом, которым нужен регулярный выпуск материалов на основе реального каталога.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=124 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Auto SEO Title PRO&lt;/strong&gt; формує H1, Meta Title, Meta Description і Meta Keywords за керованими шаблонами. Назву товару, категорії або статті модуль не змінює — вона використовується як вихідна змінна.&lt;/p&gt;&lt;p&gt;Є два різні сценарії: динамічний режим формує порожні SEO-поля під час відкриття сторінки без запису в БД, а ручне заповнення бази після preview записує тільки реально порожні значення.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;HTML H1, Meta Title, Meta Description і Meta Keywords.&lt;/li&gt;&lt;li&gt;Товари, категорії, виробники, інформаційні сторінки, ocStore Blog, сумісні UniShop Articles/News, головна та extension/module сторінки.&lt;/li&gt;&lt;li&gt;Динамічний режим не записує результат у базу й зникає після вимкнення модуля.&lt;/li&gt;&lt;li&gt;Ручне заповнення: scan → preview → batch → запис тільки NULL/порожніх значень.&lt;/li&gt;&lt;li&gt;Заповнені значення не перезаписуються без окремого дозволу.&lt;/li&gt;&lt;li&gt;Шаблонні змінні [name], [store_name], [model], [sku], [price], [manufacturer_name], [category_name], [attr=ID] та інші.&lt;/li&gt;&lt;li&gt;Умовні блоки [if:...] і детермінований спинтакс {Купить|Заказать|Выбрать}.&lt;/li&gt;&lt;li&gt;Коректне визначення головної категорії через main_category, main_category_id і fallback.&lt;/li&gt;&lt;li&gt;Опція приховування довгого SEO-тексту на технічних сторінках списку.&lt;/li&gt;&lt;li&gt;Окремий noindex,follow для limit/order/sort/filter — тільки за явного ввімкнення; page не блокується.&lt;/li&gt;&lt;li&gt;Діагностика OCMOD, таблиць, колонок, шаблонів, прав і готовності до масового заповнення.&lt;/li&gt;&lt;li&gt;Без cron і фонових задач.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає швидко закрити порожні метаполя у великому каталозі й при цьому не знищити вже оптимізовані вручну сторінки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;SEO-фахівцям і магазинам із великою кількістю порожніх метаданих після імпорту або запуску нового каталогу.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=125 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Auto SEO Title PRO creates H1, Meta Title, Meta Description and Meta Keywords from controlled templates without changing the entity name itself.&lt;/p&gt;&lt;p&gt;Two workflows are intentionally separated: dynamic mode fills empty fields only at page-render time without database writes, while the manual database-fill workflow uses scan and preview before writing only truly empty values.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;The module builds SEO fields for products, categories, manufacturers, information pages, articles/news, the home page and module pages. Manual database filling is available only for detected tables with physical SEO columns; home and arbitrary module pages are dynamic-only.&lt;/li&gt;&lt;li&gt;The Hide SEO description on duplicate listing pages setting removes the visible long category/manufacturer text from page 2 onward and when non-empty limit, order, sort or filter parameters are present. The primary URL without parameters keeps its description. This reduces repeated text but does not change Meta Description, canonical or robots. If filter URLs are intended to be indexable landing pages, enable this behavior only after verifying the filter SEO strategy.&lt;/li&gt;&lt;li&gt;Uninstall removes module settings and exact OCMOD/Event records. SEO values previously written by the manual database action are intentionally retained as website data.&lt;/li&gt;&lt;li&gt;The selected database source is not supported or no longer exists. Reopen the module and scan the schema again.&lt;/li&gt;&lt;li&gt;Only existing physical columns are used: meta_title, meta_description, meta_keyword/meta_keywords and meta_h1/seo_h1/html_h1/h1. Compatible blog/article/news tables are discovered from the database schema. Missing columns are not created or guessed.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;SEO teams and large catalogs that need a safe way to fill missing metadata without overwriting hand-optimized pages.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=125 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Auto SEO Title PRO формирует H1, Meta Title, Meta Description и Meta Keywords по управляемым шаблонам, не изменяя само название товара, категории или статьи.&lt;/p&gt;&lt;p&gt;Два сценария разделены специально: динамический режим подставляет пустые SEO-поля только при выводе страницы без записи в БД, а ручное заполнение базы использует scan/preview и записывает только действительно пустые значения.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Модуль формирует SEO-поля для товаров, категорий, производителей, информационных страниц, статей/новостей, главной страницы и страниц модулей. Ручное заполнение базы доступно только для обнаруженных таблиц с физическими SEO-колонками; главная и произвольные страницы модулей работают только динамически.&lt;/li&gt;&lt;li&gt;В базу записываются только реально существующие колонки: meta_title, meta_description, meta_keyword/meta_keywords и meta_h1/seo_h1/html_h1/h1. Совместимые таблицы блогов, статей и новостей обнаруживаются по структуре базы. Если физической колонки нет, модуль ее не создает и не пытается записать.&lt;/li&gt;&lt;li&gt;Опциональная настройка «Noindex для технических параметров» по умолчанию выключена. При включении страницы категорий и производителей с параметрами limit, order, sort или filter получают robots noindex,follow. Параметр page не блокируется, а canonical остается под управлением OpenCart/темы.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;SEO-специалистам и большим каталогам, которым нужно безопасно заполнить отсутствующие метаданные без перезаписи вручную оптимизированных страниц.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=125 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;AI Newsletter PRO&lt;/strong&gt; — автономний модуль email-маркетингу для OpenCart/ocStore. Він підтримує автоматизовані товарні випуски й повністю ручні «Вільні листи», а відправлення проходить через контрольовану чергу, розклад, SMTP/PHP Mail, suppression і статистику.&lt;/p&gt;&lt;p&gt;Ключовий принцип — один випуск має один зафіксований набір товарів, текст, дизайн, банер і промокод для вибраної аудиторії. Модуль не генерує окремий AI-лист для кожного одержувача, тому результат можна переглянути й протестувати до масового запуску.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Джерела товарів: новинки, акції, популярні, ротація головних/вибраних категорій, змішаний режим і ручний product_id.&lt;/li&gt;&lt;li&gt;Розклад: щодня, щотижня, щомісяця, кожні N днів, один раз, генерація за N днів до відправлення.&lt;/li&gt;&lt;li&gt;Попередня підготовка 1–12 майбутніх випусків.&lt;/li&gt;&lt;li&gt;Редактор фінального набору товарів із autocomplete, зміною порядку та контролем застарілого тексту/банера.&lt;/li&gt;&lt;li&gt;Block Builder: Logo, Banner, Heading, Intro, Benefits, Coupon, Products, CTA, Category, Contacts, Social, Footer; unsubscribe завжди обов’язковий.&lt;/li&gt;&lt;li&gt;Вісім дизайнів листів, налаштування кольорів, ширини, радіуса й кількості товарів у рядку.&lt;/li&gt;&lt;li&gt;AI-провайдери OpenAI/ChatGPT, Gemini, Grok і Claude; AI викликається один раз на мову під час підготовки випуску.&lt;/li&gt;&lt;li&gt;AI отримує факти товарів і не повинен вигадувати характеристики, знижки, гарантії, рейтинги чи доставку.&lt;/li&gt;&lt;li&gt;Banner modes: локальний Auto Collage, власне зображення, AI background + real products, Full AI Banner або без банера.&lt;/li&gt;&lt;li&gt;Спільний промокод випуску через стандартний OpenCart coupon.&lt;/li&gt;&lt;li&gt;Перед реальною відправкою повторно перевіряються статус, залишок і ціна товарів.&lt;/li&gt;&lt;li&gt;Suppression list: відписка не видаляє адресу фізично й не дозволяє непомітно підписати її знову звичайною синхронізацією.&lt;/li&gt;&lt;li&gt;List-Unsubscribe-Post / one-click unsubscribe, From, Reply-To, Bounce/Envelope From.&lt;/li&gt;&lt;li&gt;Діагностика SPF, DMARC, DKIM selector, PTR/reverse DNS, envelope alignment і unsubscribe.&lt;/li&gt;&lt;li&gt;Open/click tracking окремі й OFF за замовчуванням; UTM може працювати незалежно.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль об’єднує каталог, AI, дизайн, доставку листів і статистику в одному контрольованому сценарії, але залишає адміністратору фінальний preview.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Інтернет-магазинам із регулярними акціями, новинками й товарними добірками, а також тим, кому потрібні ручні брендовані email-кампанії.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=126 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Newsletter PRO is a standalone email-marketing module for OpenCart/ocStore that supports both automated product newsletters and fully manual free-form campaigns.&lt;/p&gt;&lt;p&gt;One campaign uses one approved set of products, copy, design, banner and coupon for the selected audience. AI is not called separately for every recipient, so the issue can be previewed, tested and approved before the persistent send queue starts.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Free emails use the same audience selection, duplicate filtering, queue, scheduling, cron, SMTP/PHP Mail transport, suppression rules, unsubscribe/Hard Bounce/Spam Complaint handling, open/click tracking, SMTP webhook feedback and statistics as template newsletters. Always use Preview and Test Send before a bulk send.&lt;/li&gt;&lt;li&gt;Automatically uses store data; analyzes category/catalog rules; selects available products; creates subject, preheader, heading, intro, benefits, CTA and footer; improves copy with AI when configured; builds banner/collage; inserts product images, prices, links, contacts and social networks; rechecks availability before sending.&lt;/li&gt;&lt;li&gt;Create a campaign → choose products and audience → configure content/design/socials/coupon → prepare an issue → review and edit → preview and send a test → approve → send through the persistent queue by cron → review statistics and logs.&lt;/li&gt;&lt;li&gt;AI Newsletter PRO is an autonomous OpenCart/ocStore email marketing module. It supports both catalog-driven product newsletters and fully manual Free emails without the built-in template. Product mode can select products, generate AI copy/visuals and a coupon; Free email mode lets the administrator build multilingual content in the Visual or HTML editor. Both modes use the same controlled queue, scheduling, SMTP/PHP Mail transport, suppression, tracking and analytics.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores running recurring promotions, new-product campaigns or manual branded email communication with measurable delivery statistics.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=126 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Newsletter PRO — автономный модуль email-маркетинга для OpenCart/ocStore с автоматическими товарными выпусками и полностью ручными свободными письмами.&lt;/p&gt;&lt;p&gt;Один выпуск использует один утверждённый набор товаров, текст, дизайн, баннер и промокод для выбранной аудитории. AI не вызывается отдельно для каждого получателя, поэтому письмо можно проверить, протестировать и утвердить до запуска очереди.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;AI Newsletter PRO поддерживает и автоматические товарные рассылки, и полностью ручные свободные письма. Модуль может подбирать товары и генерировать текст/визуал либо дать администратору собрать многоязычное письмо в визуальном/HTML-редакторе; после подтверждения любой выпуск использует одну постоянную очередь, контроль доставки, tracking, suppression и статистику по каждому получателю.&lt;/li&gt;&lt;li&gt;Свободное письмо использует те же получатели, фильтрацию дублей, очередь, расписание, cron, SMTP/PHP Mail, блок-лист, отписки, Hard Bounce/Spam Complaint, tracking открытий/переходов, SMTP webhook и статистику, что и обычная рассылка. Перед массовой отправкой обязательно выполните предпросмотр и тестовую отправку.&lt;/li&gt;&lt;li&gt;Товарные рассылки и полностью ручные свободные письма: мультиязычный контент, выбор аудитории, расписание, AI/каталог при необходимости, контролируемая очередь, tracking и статистика по получателям.&lt;/li&gt;&lt;li&gt;Отписка, Hard Bounce, жалоба на спам и блокировка провайдером выключают адрес в базе AI Newsletter PRO. Все ещё ожидающие строки очереди для этого email переводятся в suppressed. Выпуски, которые будут сформированы позже, также не включат неактивный адрес. Непосредственно перед сетевой отправкой выполняется повторная проверка статуса подписчика. Письмо, уже переданное SMTP в момент события, технически отозвать невозможно.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с регулярными акциями, новинками и брендированными email-кампаниями, которым нужна очередь, отписки и измеримая статистика доставки.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=126 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;AI Content PRO&lt;/strong&gt; створює, покращує, перекладає та перевіряє контент магазину через зовнішніх AI-провайдерів. Модуль працює з товарами, категоріями, виробниками, інформаційними сторінками, сумісним ocStore Blog та підтримуваними UniShop2 Articles/News.&lt;/p&gt;&lt;p&gt;Це не просто кнопка «написати опис». Модуль має ручний режим, чернетки, масову постійну чергу, cron, provider/model fallback, історію, SEO-аудит, Rich Content Builder і контрольоване застосування результату.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Генерація description, H1, метаданих, FAQ, product tags і чернеток SEO URL.&lt;/li&gt;&lt;li&gt;Переклад між активними мовами магазину.&lt;/li&gt;&lt;li&gt;Ручна генерація підставляє результат у відкриту форму; збереження виконується стандартною кнопкою OpenCart.&lt;/li&gt;&lt;li&gt;Масова черга з retry, backoff, provider/model fallback, журналом і діагностикою.&lt;/li&gt;&lt;li&gt;Rich Content Builder: власні блоки, порядок, H2–H5, увімкнення/вимкнення без видалення.&lt;/li&gt;&lt;li&gt;AI Structure Planner пропонує структуру опису за фактами конкретного товару.&lt;/li&gt;&lt;li&gt;Replace / Before / After / Smart Merge для об’єднання з існуючим описом.&lt;/li&gt;&lt;li&gt;Перегенерація одного блоку без повторної генерації всього тексту.&lt;/li&gt;&lt;li&gt;SEO-аудит якості, схожості, шаблонності та технічних проблем.&lt;/li&gt;&lt;li&gt;Технічна очистка без AI: zero-width/BOM, NBSP, службові AI-маркери, небезпечні HTML/JS-фрагменти.&lt;/li&gt;&lt;li&gt;Контроль Google Merchant: description понад 5000 видимих символів позначається як критична проблема; виправлення має окремий ліміт.&lt;/li&gt;&lt;li&gt;Image Slots можуть передаватися в AI Image Studio PRO лише як опціональна інтеграція; результат залишається чернеткою.&lt;/li&gt;&lt;li&gt;Дослідження виробника може використовувати Gemini Google Search або OpenAI Web Search для формування підтвердженого досьє перед написанням.&lt;/li&gt;&lt;li&gt;Custom API має захист від SSRF, private IP, DNS rebinding, небезпечних redirect і надто великих відповідей.&lt;/li&gt;&lt;li&gt;Результати, черги, історія, логи й налаштування розділяються за store_id.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;AI Content PRO скорочує ручну роботу з великим каталогом, але не повинен автоматично перезаписувати важливий контент без контрольованого сценарію.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Власникам великих каталогів, SEO-фахівцям, контент-менеджерам і веб-студіям, які ведуть багатомовні магазини.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=127 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Content PRO generates, improves, translates and audits OpenCart content through external AI providers while keeping normal OpenCart saving under administrator control.&lt;/p&gt;&lt;p&gt;It is more than a single \'write description\' button: manual drafts, a persistent bulk queue, provider/model fallback, history, SEO audit, structured content blocks and optional image handoff are separate controlled workflows.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Quick workflow: enable the module, add API key and model id, test the key, open a product or category, click AI SEO, select language and operation, generate content, insert it into the open form and save with native Save button. For bulk work, run SEO audit first, add found records to queue, then process the queue in small batches.&lt;/li&gt;&lt;li&gt;This module generates SEO content for products, categories, and information pages through OpenAI, Gemini, DeepSeek, Grok, OpenRouter, or another OpenAI-compatible API. API keys are stored server-side and are not exposed to the browser. Bulk generation uses a queue to avoid slow admin pages and storefront performance issues.&lt;/li&gt;&lt;li&gt;When verified web research finds an official website, public company phone, general email or current address, the module appends a localized contact-information section to the manufacturer description. Missing data is omitted and dealer/importer contacts are not substituted.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Large catalogs, SEO teams and content managers maintaining multilingual products, categories and editorial content.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=127 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Content PRO создаёт, улучшает, переводит и проверяет контент OpenCart через внешних AI-провайдеров, сохраняя стандартное сохранение OpenCart под контролем администратора.&lt;/p&gt;&lt;p&gt;Это не одна кнопка «написать описание»: ручные черновики, постоянная массовая очередь, fallback провайдеров/моделей, история, SEO-аудит, структурированные блоки и опциональная передача изображений работают как отдельные управляемые сценарии.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Быстрый сценарий: включите модуль, добавьте API-ключ и model id, проверьте ключ, откройте товар или категорию, нажмите AI SEO, выберите язык и операцию, сгенерируйте текст, вставьте его в открытую форму и сохраните штатной кнопкой. Для массовой работы сначала запустите SEO-аудит, добавьте найденные записи в очередь, затем обработайте очередь небольшими пакетами.&lt;/li&gt;&lt;li&gt;Если включено, после черновика промта изображения очередь создаёт отдельную задачу image_generate. Файл сохраняется только внутри image/catalog/ai-content/... после проверки MIME, размера и пути. Включайте только после настройки провайдера изображений.&lt;/li&gt;&lt;li&gt;Добавлены Image Slots. AI Content формирует структурированное задание на изображение и безопасно передаёт его в очередь AI Image Studio PRO, если модуль установлен и включён. Результаты изображений остаются черновиками и не применяются автоматически.&lt;/li&gt;&lt;li&gt;Модуль генерирует SEO-контент для товаров, категорий и информационных страниц через OpenAI, Gemini, DeepSeek, Grok, OpenRouter или другой OpenAI-compatible API. API-ключи хранятся на сервере и не передаются в браузер. Массовая генерация работает через очередь, чтобы не грузить админку и не тормозить витрину.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Большим каталогам, SEO-командам и контент-менеджерам, которые ведут многоязычные товары, категории и статьи.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=127 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;AI Image Studio PRO&lt;/strong&gt; аналізує зображення OpenCart, знаходить маленькі, важкі, пошкоджені й дубльовані файли та створює контрольовані AI-чернетки для покращення або заміни візуалу.&lt;/p&gt;&lt;p&gt;Вихідний файл не перезаписується автоматично. AI-результат зберігається окремо, проходить preview і лише після прийняття підставляється в штатну форму товару, категорії, виробника, інформаційної сторінки або підтримуваної статті.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Аудит розміру, ваги, співвідношення сторін, пошкоджень, дублів і прозорості.&lt;/li&gt;&lt;li&gt;Видалення фону, генеративна заміна фону, покращення, commercial packshot, генерація за промптом, refine і regenerate.&lt;/li&gt;&lt;li&gt;OpenAI/GPT Image, Gemini та спеціалізовані image-провайдери за наявності відповідного API.&lt;/li&gt;&lt;li&gt;Provider/model registry із перевіркою сумісності операції та збереженого ключа.&lt;/li&gt;&lt;li&gt;Prompt Library як єдине джерело промптів.&lt;/li&gt;&lt;li&gt;Visual Context Builder використовує назву, бренд, model, SKU/MPN, категорії, характеристики та очищений опис товару.&lt;/li&gt;&lt;li&gt;Scene Library: тип об’єкта, провайдер, модель, пропорції, масштаб, позиція, освітлення й автоматичний підбір.&lt;/li&gt;&lt;li&gt;Mass AI Studio з фільтрами товарів, preview, 1–3 кандидатами, оцінкою задач і приблизної вартості.&lt;/li&gt;&lt;li&gt;Кандидати групуються; найкращий за контрольним score показується першим.&lt;/li&gt;&lt;li&gt;Rich Image Composer для вставки зображення в опис: before, after first paragraph, before H2/H3, before FAQ або в кінець.&lt;/li&gt;&lt;li&gt;Перед вставкою в description зберігається HTML snapshot конкретної мови для контрольованого rollback.&lt;/li&gt;&lt;li&gt;Інтеграція Image Slots із AI Content PRO є опціональною, а модулі залишаються незалежними.&lt;/li&gt;&lt;li&gt;API-ключі та cron-key приховані password-полями з кнопкою показу.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль дозволяє експериментувати з AI-візуалом без небезпечної автоматичної заміни оригіналів.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Магазинам із великою кількістю товарних зображень, маркетинговими банерами й потребою в контрольованій AI-обробці.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=128 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Image Studio PRO audits OpenCart images and creates controlled AI drafts for background removal, enhancement, commercial packshots, generation and refinement.&lt;/p&gt;&lt;p&gt;The original file is not overwritten automatically. Generated candidates are stored separately, reviewed in preview and only then applied to a normal OpenCart form or inserted into content.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Added Mass AI Studio with product filters for name/model/SKU, category, manufacturer, status, image availability, and quality-audit state (issues, good, not scanned); preview, 1–3 candidates, scene/provider/target selection, description insertion position, expected job count, and estimated API cost before queueing.&lt;/li&gt;&lt;li&gt;Value: fast catalog quality control, Mass AI Studio, commercial product imagery, safe background workflows, protected originals, description HTML snapshots, cron queue and complete version rollback.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Stores with large product-image libraries that need consistent commercial visuals and controlled AI-assisted image processing.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=128 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;AI Image Studio PRO проверяет изображения OpenCart и создаёт контролируемые AI-черновики для удаления/замены фона, улучшения, коммерческих packshot, генерации и доработки.&lt;/p&gt;&lt;p&gt;Исходный файл не перезаписывается автоматически. Кандидаты сохраняются отдельно, проходят preview и только после принятия применяются к штатной форме OpenCart или вставляются в контент.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Добавлен Mass AI Studio: фильтрация товаров по названию/модели/SKU, категории, производителю, статусу, наличию изображения и результату проверки качества (проблемные, хорошие, не проверенные); предварительный список, выбор 1–3 кандидатов, сцены, провайдера, места применения, позиции вставки в описание и оценка числа задач/ориентировочной стоимости до постановки в очередь.&lt;/li&gt;&lt;li&gt;Bria добавлен только как провайдер изображений: Product Cutout, белый Product Packshot и Lifestyle Product Shot по сцене. Модуль не генерирует SEO-тексты, описания, отзывы или статьи.&lt;/li&gt;&lt;li&gt;Полезность: быстрый контроль каталога, массовый AI Studio, коммерческое качество товарных фото, аккуратная работа с фоном, защита оригиналов, HTML-снимки описаний, cron-очередь и полноценный откат версий.&lt;/li&gt;&lt;li&gt;Модуль проверяет качество изображений, использует единый Prompt Engine с контекстом каталога и библиотекой сцен, создаёт безопасные AI-черновики, поддерживает массовую обработку, версии, кандидаты и управляемую вставку изображений в описания.&lt;/li&gt;&lt;li&gt;Модуль анализирует изображения в ocStore/OpenCart, выявляет маленькие, тяжёлые, повреждённые и дублирующиеся файлы, формирует рекомендации и создаёт безопасные AI-черновики. Поддерживаются удаление и замена фона, улучшение исходного фото, коммерческий packshot, генерация по промпту, перегенерация и уточнение результата.&lt;/li&gt;&lt;li&gt;Bria Product Shot использует исходное фото товара как обязательный референс. Для lifestyle и замены окружения используется английское описание выбранной сцены из Scene Library; модуль не выполняет скрытый перевод или генерацию текста.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Магазинам с большим количеством товарных изображений, которым нужен единый коммерческий стиль и контролируемая AI-обработка.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=128 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Currency Rates PRO&lt;/strong&gt; отримує курси з офіційних джерел і оновлює стандартну таблицю currency OpenCart/ocStore. Модуль не створює окрему систему цін і не перераховує збережені product.price.&lt;/p&gt;&lt;p&gt;Мета — безпечно підтримувати стандартні курси магазину для форматування й розрахунків OpenCart, не записуючи нульове або підозріле значення при помилці зовнішнього джерела.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Ручне оновлення і preview курсу до запису.&lt;/li&gt;&lt;li&gt;Джерела ECB, НБУ, CBR, NBP і PrivatBank.&lt;/li&gt;&lt;li&gt;Перевірка дати джерела та максимально допустимого стрибка курсу.&lt;/li&gt;&lt;li&gt;Індивідуальна процентна корекція для кожної валюти.&lt;/li&gt;&lt;li&gt;Опція оновлювати тільки ввімкнені валюти.&lt;/li&gt;&lt;li&gt;Популярні валюти можуть додаватися у вимкненому стані.&lt;/li&gt;&lt;li&gt;Основна валюта магазину завжди має value=1.00000000.&lt;/li&gt;&lt;li&gt;При timeout, неправильній відповіді, застарілій даті або надмірному стрибку попередній валідний курс зберігається.&lt;/li&gt;&lt;li&gt;Паралельні оновлення блокуються MySQL named lock.&lt;/li&gt;&lt;li&gt;Захищений cron із секретним ключем і готовою командою для Mirohost.&lt;/li&gt;&lt;li&gt;Пагінований журнал і діагностика джерел.&lt;/li&gt;&lt;li&gt;Опція приховати .00 змінює тільки кінцевий рядок ціни на витрині; розрахунки, кошик, податки й дані БД не змінюються.&lt;/li&gt;&lt;li&gt;Custom source URL обмежений дозволеними офіційними HTTPS-хостами; local/private IP і нестандартні порти блокуються.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль автоматизує обслуговування стандартних валют OpenCart і зберігає попереднє коректне значення при проблемах мережі.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Мультівалютним магазинам, які хочуть регулярно оновлювати стандартні курси OpenCart з офіційних джерел.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=129 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Currency Rates PRO downloads exchange rates from official sources and updates the native OpenCart currency table without creating a parallel pricing system.&lt;/p&gt;&lt;p&gt;It does not rewrite stored product.price values. If an external source times out, returns stale data or an excessive jump, the previous valid rate is preserved instead of writing zero or a suspicious value.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Version 1.7.2 restores the “Hide decimals when they are 00” option. It changes only the final storefront price string. Non-zero decimals remain visible: 1000.50 stays 1000.50. Calculations, cart, orders, taxes and database values are not changed. No global MutationObserver or JavaScript injection through catalog/common/header is used. Refresh modifications and clear the template cache after updating.&lt;/li&gt;&lt;li&gt;The option changes only the final storefront price string: 1000.00 is displayed as 1000, while 1000.50 remains 1000.50. Calculations, Currency::format(..., false), cart, orders, taxes and database values are not changed. The implementation does not use MutationObserver or inject scripts through the common header.&lt;/li&gt;&lt;li&gt;The module safely retrieves exchange rates from official sources and updates the standard OpenCart/ocStore currency table. It does not create a separate pricing system and does not change product prices, orders, taxes, payment or shipping calculations.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Multi-currency stores that want the standard OpenCart currency table to stay updated from official sources.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=129 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Currency Rates PRO получает курсы из официальных источников и обновляет стандартную таблицу currency OpenCart, не создавая отдельную систему цен.&lt;/p&gt;&lt;p&gt;Модуль не переписывает сохранённые product.price. При timeout, устаревшей дате или подозрительном скачке старый валидный курс сохраняется вместо записи нулевого или сомнительного значения.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Модуль безопасно получает курсы валют из официальных источников и обновляет стандартную таблицу currency OpenCart/ocStore. Он не создаёт отдельную систему цен и не изменяет цены товаров, заказов, налогов, оплаты или доставки.&lt;/li&gt;&lt;li&gt;В версии 1.7.2 возвращена опция «Не показывать копейки, если они равны 00». Она обрабатывает только окончательно сформированную строку цены на витрине. Значения с ненулевой дробной частью сохраняются: 1000.50 остаётся 1000.50. Расчёты, корзина, заказы, налоги и данные базы не меняются. Глобальный MutationObserver и подключение JavaScript через catalog/common/header не используются. После обновления обязательно обновите модификаторы и очистите кеш шаблона.&lt;/li&gt;&lt;li&gt;Не пересчитывает сохранённые цены товаров. Для товаров с исходной валютной ценой используется отдельный модуль Product Currency Input Pro.&lt;/li&gt;&lt;li&gt;Опция меняет только готовую строку цены на витрине: 1000.00 будет показано как 1000, а 1000.50 останется 1000.50. Расчёты, Currency::format(..., false), корзина, заказы, налоги и значения в базе не изменяются. Реализация не использует MutationObserver и не подключает скрипты через общий header.&lt;/li&gt;&lt;li&gt;Модуль обновляет стандартные курсы валют OpenCart через штатную таблицу currency и не создает отдельную систему цен.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Мультивалютным магазинам, которым нужно регулярно обновлять стандартные курсы OpenCart из официальных источников.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.0.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.x&lt;/li&gt;&lt;li&gt;PHP 7.4–8.5&lt;/li&gt;&lt;li&gt;UA / RU / EN&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=129 AND `language_id`=3;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;&lt;strong&gt;Database Index Optimizer PRO&lt;/strong&gt; аналізує індекси MySQL/MariaDB, показує перевірені кандидати й створює лише ті індекси, які адміністратор явно вибрав і поставив у постійну чергу.&lt;/p&gt;&lt;p&gt;Модуль навмисно консервативний: він не видаляє сторонні індекси «за оптимізацією», не виконує довільний raw SQL із профілів і не запускає важкі ALTER/OPTIMIZE тільки через відкриття сторінки налаштувань.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Можливості&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Сканування існуючих і відсутніх індексів за перевіреними профілями.&lt;/li&gt;&lt;li&gt;Явний вибір індексу перед постановкою в постійну queue.&lt;/li&gt;&lt;li&gt;ADD INDEX блокується для таблиць вище налаштованого безпечного ліміту.&lt;/li&gt;&lt;li&gt;OPTIMIZE за замовчуванням вимкнений, має окремий дозвіл і ліміт розміру.&lt;/li&gt;&lt;li&gt;Rollback видаляє тільки індекс, створений модулем, коли HMAC-підпис і фізичне визначення індексу збігаються.&lt;/li&gt;&lt;li&gt;Перекривні сторонні індекси показуються лише для ручної оцінки й автоматично не видаляються.&lt;/li&gt;&lt;li&gt;Конструктор custom profile: suffix таблиці, ccp_* ім’я, колонки, priority, risk, min rows і причина.&lt;/li&gt;&lt;li&gt;Custom/third-party профілі підтримуються як перевірені JSON-маніфести без довільного SQL.&lt;/li&gt;&lt;li&gt;Вкладка Performance запускається тільки вручну й аналізує Performance Schema, hot tables, стан сервера та історію росту таблиць.&lt;/li&gt;&lt;li&gt;Окремий список запитів, що створюють disk temporary tables, і статистика Created_tmp_*.&lt;/li&gt;&lt;li&gt;Безпечний EXPLAIN для доступних SELECT із Performance Schema history та порівняння плану «До/Після».&lt;/li&gt;&lt;li&gt;Стан MySQL/MariaDB: uptime, середні SQL commands/s, slow queries на годину/добу та частка від Questions.&lt;/li&gt;&lt;li&gt;Модуль не вмикає Performance Schema, slow query log і не змінює my.cnf автоматично.&lt;/li&gt;&lt;li&gt;При OFF не запускаються scan, queue, ALTER TABLE, ANALYZE, OPTIMIZE, session cleanup або cron.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Яка користь&lt;/h3&gt;&lt;p&gt;Модуль допомагає перейти від здогадок «додамо індекс і стане швидше» до контрольованого аналізу, черги й можливості безпечного rollback.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому підходить&lt;/h3&gt;&lt;p&gt;Розробникам і адміністраторам великих OpenCart/ocStore магазинів, де потрібен контроль індексів і SQL-навантаження.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Сумісність&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.4.1&lt;/li&gt;&lt;li&gt;PHP 8.1–8.3&lt;/li&gt;&lt;li&gt;MySQL / MariaDB&lt;/li&gt;&lt;li&gt;InnoDB / utf8mb4 для таблиць модуля&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важливо:&lt;/strong&gt; Зробіть резервну копію файлів і бази даних. Спочатку перевірте модуль на тестовій копії магазину й лише потім вмикайте його на робочому сайті.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкою&lt;/h3&gt;&lt;p&gt;Відкрийте тестову адмінку та перевірте модуль у роботі.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логін: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Склад модулів і тестові дані демо можуть змінюватися — перевіряйте наявність потрібної функції перед покупкою.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Відкрити демо-адмінку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=130 AND `language_id`=1;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Database Index Optimizer PRO audits MySQL/MariaDB indexes and creates only explicitly selected indexes through a persistent controlled queue.&lt;/p&gt;&lt;p&gt;It is intentionally conservative: third-party indexes are not deleted automatically, heavy ALTER/OPTIMIZE work is not triggered merely by opening the admin page, and rollback is limited to indexes previously created and registered by the module.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Features&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Concrete SQL attribution for disk temporary tables and real table read/write statistics requires server-level MariaDB/MySQL Performance Schema. The module never enables it automatically. If performance_schema=OFF, contact the hosting provider; a copy-ready request is shown in Diagnostics. Continuous use is appropriate when server resources are sufficient; constrained servers should be reviewed by the administrator.&lt;/li&gt;&lt;li&gt;Admin UX v1.4.4: scan summary cards act as quick filters by status and source; missing indexes use danger styling; queue tasks are shown at the top of maintenance; OPTIMIZE is clearly documented as a heavy table rebuild/compaction operation rather than routine maintenance. The SQL column no longer appears blank without explanation; the full Mirohost cron command is visible and copyable.&lt;/li&gt;&lt;li&gt;Analyzes the OpenCart database schema, table sizes, available Performance Schema counters and MySQL/MariaDB state. It supports core and curated third-party profiles, creates only explicitly selected indexes through a persistent step queue, registers them for controlled rollback and helps verify real impact with EXPLAIN.&lt;/li&gt;&lt;li&gt;The module is OFF. No scans, queues, maintenance, session cleanup, cron work or operational logging are executed until you enable and save it.&lt;/li&gt;&lt;li&gt;1) Create a full backup. 2) Scan indexes. 3) Review missing recommendations. 4) Use Performance manually to review costly statements and hot tables. 5) Save a Before EXPLAIN for the relevant SELECT. 6) Queue the selected index. 7) Compare the After EXPLAIN. 8) Use ANALYZE/OPTIMIZE only when separately justified.&lt;/li&gt;&lt;li&gt;Safe database-index analysis for ocStore 3.0.4.1 / OpenCart 3.x, creation of explicitly selected curated indexes through a persistent queue, controlled rollback, table maintenance and safe cleanup of expired sessions only.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Who it is for&lt;/h3&gt;&lt;p&gt;Developers and administrators of larger OpenCart/ocStore databases who need controlled index maintenance and SQL diagnostics.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Compatibility&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.4.1&lt;/li&gt;&lt;li&gt;PHP 8.1–8.3&lt;/li&gt;&lt;li&gt;MySQL / MariaDB&lt;/li&gt;&lt;li&gt;InnoDB / utf8mb4&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Important:&lt;/strong&gt; Back up your files and database. Test the module on a staging copy first and enable it on the live store only afterwards.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Try the demo before you buy&lt;/h3&gt;&lt;p&gt;Open the demo admin and see the module in action.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Login: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Password: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Demo modules and test data may change — check that the feature you need is present before purchasing.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Open the demo admin&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=130 AND `language_id`=2;
UPDATE `oc_product_description` SET `description`='&lt;div class=&quot;ccp-pd&quot;&gt;&lt;p class=&quot;ccp-pd__lead&quot;&gt;Database Index Optimizer PRO анализирует индексы MySQL/MariaDB и создаёт только явно выбранные индексы через постоянную управляемую очередь.&lt;/p&gt;&lt;p&gt;Модуль специально консервативен: сторонние индексы автоматически не удаляются, тяжёлые ALTER/OPTIMIZE не запускаются просто при открытии админки, а rollback разрешён только для индексов, которые ранее создал и зарегистрировал сам модуль.&lt;/p&gt;&lt;div class=&quot;ccp-pd__grid&quot;&gt;&lt;section class=&quot;ccp-pd__card ccp-pd__card--wide&quot;&gt;&lt;h3&gt;Возможности&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__list&quot;&gt;&lt;li&gt;Анализирует схему базы OpenCart, размеры таблиц, доступные счётчики Performance Schema и состояние MySQL/MariaDB. Поддерживает ядро и курируемые профили сторонних модулей, создаёт только явно выбранные индексы через постоянную пошаговую очередь, регистрирует их для контролируемого отката и помогает проверить реальный эффект через EXPLAIN.&lt;/li&gt;&lt;li&gt;Для определения конкретных SQL-запросов, создающих временные таблицы, и для реальной статистики чтения/записи таблиц требуется Performance Schema на уровне MariaDB/MySQL. Модуль не включает её автоматически. Если performance_schema=OFF, обратитесь к хостингу; готовый текст запроса показан во вкладке «Диагностика». Для постоянной диагностики Performance Schema можно держать включённой при достаточных ресурсах сервера; на малом VPS/общем хостинге нагрузку и память должен оценить администратор.&lt;/li&gt;&lt;li&gt;Интерфейс v1.4.4: карточки результата сканирования работают как быстрые фильтры по статусу и источнику; отсутствующие индексы выделены красным; задания очереди находятся вверху вкладки обслуживания; OPTIMIZE отдельно объяснён как тяжёлая перестройка/уплотнение таблицы, а не обычная профилактическая операция. SQL-столбец не остаётся пустым без причины; cron Mirohost показан полностью и копируется одной кнопкой.&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Кому подходит&lt;/h3&gt;&lt;p&gt;Разработчикам и администраторам крупных баз OpenCart/ocStore, которым нужен контролируемый аудит индексов и SQL-диагностика.&lt;/p&gt;&lt;/section&gt;&lt;section class=&quot;ccp-pd__card&quot;&gt;&lt;h3&gt;Совместимость&lt;/h3&gt;&lt;ul class=&quot;ccp-pd__chips&quot;&gt;&lt;li&gt;OpenCart 3.x&lt;/li&gt;&lt;li&gt;ocStore 3.0.4.1&lt;/li&gt;&lt;li&gt;PHP 8.1–8.3&lt;/li&gt;&lt;li&gt;MySQL / MariaDB&lt;/li&gt;&lt;li&gt;InnoDB / utf8mb4&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/div&gt;&lt;div class=&quot;ccp-pd__note&quot;&gt;&lt;strong&gt;Важно:&lt;/strong&gt; Сделайте резервную копию файлов и базы данных. Сначала проверьте модуль на тестовой копии магазина и только затем включайте его на рабочем сайте.&lt;/div&gt;&lt;div class=&quot;ccp-pd__demo&quot;&gt;&lt;div&gt;&lt;h3&gt;Демо перед покупкой&lt;/h3&gt;&lt;p&gt;Откройте тестовую админку и проверьте модуль в работе.&lt;/p&gt;&lt;p class=&quot;ccp-pd__creds&quot;&gt;&lt;span&gt;Логин: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;span&gt;Пароль: &lt;b&gt;Demo&lt;/b&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;ccp-pd__small&quot;&gt;Состав модулей и тестовые данные демо могут меняться — проверяйте наличие нужной функции перед покупкой.&lt;/p&gt;&lt;/div&gt;&lt;a class=&quot;ccp-pd__btn&quot; href=&quot;https://demo.codecartpro.com/admin/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Открыть демо-админку&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;' WHERE `product_id`=130 AND `language_id`=3;
